extern bool checkUserMacAddress();
FILE *LOGFILEPTR = NULL; // global pointer

// writing message to stdout
/****************************************************************************/
void writeMessageToParetoLog(const char format[],...)
{
    va_list(args);
    char tempStr[1024*16];
    va_start(args, format);
    vsprintf(tempStr,format,args);
    va_end (args);
    cout << tempStr << endl;

    if (LOGFILEPTR == NULL)return;

    fprintf(LOGFILEPTR,"%s \n", tempStr);
    fflush(LOGFILEPTR);
}

/**********************************************************************/
AFElasticity::AFElasticity()
{
    h_nNodes = 0;
    h_nElems = 0;


    h_nQuadraticNodes = 0;// only used by Navier stokes and other special applications
    h_elem27Nodes = NULL;// only used by Navier stokes and other special applications

    // set variables that will not depend on the mesh
    h_hexmesh_verbose = false;
    h_deflation_verbose = false;
    disableHexmeshGPUVerbose();
    // Compute gradients of shape functions

    double a = 1.0/sqrt(3.0);
    double xi[8] = {-a,a,a,-a,-a,a,a,-a};
    double eta[8] = {-a,-a,a,a,-a,-a,a,a};
    double mu[8] = {-a,-a,-a,-a,a,a,a,a};

    for (int i =0; i < 8; i++){
        computeN(xi[i],eta[i],mu[i],h_N[i]);
        computeGrad_H8(xi[i],eta[i],mu[i],h_gradNxi[i],h_gradNeta[i],h_gradNmu[i]);
    }
    computeGrad_H8(0,0,0,h_gradNxi0,h_gradNeta0,h_gradNmu0);

    // Workspace
    ws_deflationType = DEFLATION_NONE;
    ws_nodeAssignmentMethod = 0;
    ws_nGroups = 0;
    ws_DCGMaxIter = 1000;

    removeAllMaterials();

    InitializeAllAFElasticityVariables();
}
/**********************************************************************/
void AFElasticity::removeAllMaterials(void)
{
    //typically called when a geometry is loaded
    h_nParts = 0;
    h_nMaterials = 0;// no material
    for (int i = 0; i < MAX_MATERIALS; i++){
        h_partToMaterialMap[i] = -1;// no material assigned
        h_partOptimize[i] = true;
        strcpy(h_materialName[i],"NoMaterial");
        h_E[i] = 2e11;
        h_nu[i] = 0.33;
        h_Y[i] = 500e6;
        h_rho[i] = 7800;
        h_conductivity[i] = 16;
        h_alpha[i] = 1e-6;
        h_specificHeat[i] = 6000;
    }
    h_keepAllMaterials = false;
}
/**********************************************************************/
void AFElasticity::InitializeAllAFElasticityVariables(void)
{
    int i;
    if (h_hexmesh_verbose) cout << "AFElasticity: Initializing All AFElasticity Variables" << endl;

    releaseCPUMemory();
    h_nNodes = 0;
    h_nElems = 0;

    // Compute gradients of shape functions

    double a = 1.0/sqrt(3.0);
    double xi[8] = {-a,a,a,-a,-a,a,a,-a};
    double eta[8] = {-a,-a,a,a,-a,-a,a,a};
    double mu[8] = {-a,-a,-a,-a,a,a,a,a};

    for (int i =0; i < 8; i++){
        computeN(xi[i],eta[i],mu[i],h_N[i]);
        computeGrad_H8(xi[i],eta[i],mu[i],h_gradNxi[i],h_gradNeta[i],h_gradNmu[i]);
    }
    computeGrad_H8(0,0,0,h_gradNxi0,h_gradNeta0,h_gradNmu0);

    // Workspace
    ws_deflationType = DEFLATION_NONE;
    ws_nodeAssignmentMethod = 0;
    ws_nGroups = 0;
    ws_DCGMaxIter = 1000;

    h_nTemplateElements = 0;
    h_maxNeighboringElements = 0;

    h_simpMode = false;// by default, use Pareto
    h_usingPreconditioner = false;//typically used in SIMP mode


    h_nLinearSolves = 0;
    h_cgNorm = NULL;
    h_nCGItersActual = 0;

    h_hexmeshTimer.stop();//stop timing

    //The following few variables are used to accelerate code for uniform grid
    h_voxelgrid = false; //not uniform grid by default
    h_gridNodeToRealNode = NULL;

    h_nodeWithMaxDeformation = h_nodeWithMaxStress = 0;
    h_x = NULL;
    h_y = NULL;
    h_z = NULL;
    h_modelScale = 1.0;

    h_Eexponent = 3.0;// for pseudo density scaling of stiffness
    h_Mexponent = 3.0;// for pseudo density scaling of mass

    h_pseudoDensityCutoff = 0.01;// for SIMP calculations
    isStaticResultValid = false;
    h_workSpaceInitialized = false;

    h_nodeLabels = NULL;

    h_elems = NULL;
    h_pseudoDensity = NULL;
    h_nodeExists = NULL;
    h_neighborElems = NULL;
    h_nNeighboringElems = NULL;
    h_neighborNodes = NULL;
    h_nodeSignature = NULL;
    h_templateID = NULL;
    h_free = NULL;
    h_dirichlet = NULL;
    h_retain = NULL;

    //Morphological oepration, decides the neihbor pattern; options are 1,7,19,27
    h_StructuringSize = 27;
    h_StructuringElems = NULL; // morphology

    h_nMeshComponents = 0;

    h_elemComponent = NULL;
    h_keepElem = NULL;
    // eigen values, etc
    h_useEigenProjection = false;
    h_nEigenModes = 0;// zero eigen modes stored
    h_eigenValues = NULL;
    h_eigenModes = NULL;

    h_f = NULL;
    h_bodyForce = NULL;
    h_isThereAcceleration = false;
    h_output = NULL;
    h_materialIdOfElem = NULL;
    h_partIdOfElem = NULL;
    h_KeNode = NULL;
    h_MeNode = NULL;
    h_KETemplates = NULL;
    h_METemplates = NULL;
    h_sol = NULL;
    h_solErr = NULL;
    for ( i = 0; i < 6; i++) {
        h_elemstrains[i] = NULL;
        h_elemstresses[i] = NULL;
        h_nodestrains[i] = NULL;
        h_nodestresses[i] = NULL;
    }
    h_nodevonmises = NULL;

    for (int part = 0; part < MAX_PARTS; part++)
        h_vonmisesMaxInPart[part] = 0;

    ts_currentIsoCounter = -1;
    isStaticResultValid = false;
    for (i=0; i < 3;i++) {
        h_uvwMax[i] = -HUGE_VAL;
        h_uvwMin[i] = HUGE_VAL;
    }

    h_nodeBasedAssembly = false;
    h_CGMaxIter = 20000; // default
    h_CGRelativeResErr = 1e-10; // default

    h_elemSignatureTolerance = 1e-10;// default

    h_maxLabel = 0;
    // GPU variables
    usingGPU = false;
    h_gpuData.h_nNodes = 0; //

    for (i = 0; i < HEXMESH_MAX_FACE_LABELS;i++)
        h_NumNodesWithLabel[i] = 0;

    h_numTesselationPoints = 0;
    h_numTesselationTriangles = 0;
    h_tessellationNormals = 0;
    h_tessellationXYZ = NULL;
    h_tessellationTriangles = NULL;
    h_tessellationUVW = NULL;
    h_tessellationModalUVW = NULL;
    h_tessellationVonMises = NULL;
    h_tessellationTemperature = NULL;

    LOGFILEPTR = NULL;
}
