/**********************************************************************/
void AFElasticity::enableDeflation(int workSpaceReductionType)
{
    int nWorkGroups;
    nWorkGroups = int (1.0*h_nNodes/1000.0);// heuristic
    nWorkGroups = MIN(MAX_WORKSPACE_GROUPS,MAX(nWorkGroups,MIN_WORKSPACE_GROUPS));
    if (!ws_deflationType)// not using deflation previously
        if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Enabling deflation with %d groups ",nWorkGroups);

    if ((ws_nGroupsDesired != nWorkGroups) || (ws_deflationType != workSpaceReductionType))
        ReleaseWorkSpace();

    ws_nGroupsDesired = nWorkGroups;
    ws_deflationType = workSpaceReductionType;
    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Enabling deflation with %d groups ",nWorkGroups);
}
/**********************************************************************/
void AFElasticity::enableDeflation(int workSpaceReductionType,int nWorkGroups)
{
    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Enabling deflation with %d groups ",nWorkGroups);

    if ((ws_nGroupsDesired != nWorkGroups) || (ws_deflationType != workSpaceReductionType))
        ReleaseWorkSpace();

    ws_nGroupsDesired = nWorkGroups;
    ws_deflationType = workSpaceReductionType;
    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Enabling deflation with %d groups ",nWorkGroups);
}
/**********************************************************************/
void AFElasticity::disableDeflation(void)
{
    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Disabling deflation ");
    ws_deflationType = DEFLATION_NONE;
    ReleaseWorkSpace();
} 
