/**********************************************************************/
void AFElasticity::enableGPU(void)
{
#ifdef COMPILE_GPUCODE
    if (isThereValidCudaDevice() ==1) {
        if (h_hexmesh_verbose)  writeMessageToParetoLog("AFElasticity: Enabling GPU ");
        usingGPU = true;
        transferForcesBCToGPU();
    }
    else {
        writeMessageToParetoLog("AFElasticity: No valid GPU device ");
        if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Disabling GPU ");
        usingGPU = false;
    }
#else
    writeMessageToParetoLog("AFElasticity: No valid GPU device ");
    writeMessageToParetoLog("AFElasticity: Disabling GPU ");
    usingGPU = false;
#endif
}
/**********************************************************************/
