/**********************************************************************/
void AFElasticity::getGridIndicesOfElem(int elem,int gridIndices[3])
{
    double center[3];

    getElemCenter( elem, center);

    gridIndices[0] = MIN(h_nelx-1,MAX(0,NEARESTINT((center[0] - h_xMin)/h_dx-0.5)));
    gridIndices[1] = MIN(h_nely-1,MAX(0,NEARESTINT((center[1] - h_yMin)/h_dy-0.5)));
    gridIndices[2] = MIN(h_nelz-1,MAX(0,NEARESTINT((center[2] - h_zMin)/h_dz-0.5)));

}
/**********************************************************************/
void AFElasticity::getElemCenter(int elem,double center[3])
{
    int node;

    center[0] = 0;
    center[1] = 0;
    center[2] = 0;

    if (elem<0 || elem>h_nElems-1)
        return;

    for (int m = 0;m < 8; m++) {
        node = h_elems[(h_nElems)*m + elem];
        center[0] += h_x[node];
        center[1] += h_y[node];
        center[2] += h_z[node];
    }
    center[0]/=8.0;
    center[1]/=8.0;
    center[2]/=8.0;
}
/**********************************************************************/
void AFElasticity::getNodeLocationWithDeformation(int node,double pt[3],double scale)
{
    pt[0] = h_x[node]+scale* h_sol[3*node];
    pt[1] = h_y[node]+scale* h_sol[3*node+1];
    pt[2] = h_z[node]+scale* h_sol[3*node+2];
}
/**********************************************************************/
void AFElasticity::getElemNodeLocationWithDeformation(int elem,double x[8],double y[8],double z[8],double scale)
{
    int node;
    for (int m = 0;m < 8; m++) {
        node = h_elems[(h_nElems)*m + elem];
        x[m] = h_x[node]+scale* h_sol[3*node];
        y[m] = h_y[node]+scale* h_sol[3*node+1];
        z[m] = h_z[node]+scale* h_sol[3*node+2];
    }
}
/**********************************************************************/
bool AFElasticity::getElasticitySolutionInCenterOfElem(int elem,double uvw[3],double stresses[6],double *vonMises)
{
    int nodes[8],node;

    if (!h_voxelgrid) return false;
    uvw[0] = uvw[1] = uvw[2] = 0;
    for (int component = 0; component < 6; component++)
        stresses[component] = 0;
    *vonMises = 0;

    if ((elem < 0) || (elem >= h_nElems)) return false;

    getElemNodes(elem,nodes);
    // at the center
    for (int m = 0;m < 8; m++) {
        node = nodes[m];
        uvw[0] += h_sol[3*node]/8.0;
        uvw[1] += h_sol[3*node+1]/8.0;
        uvw[2] += h_sol[3*node+2]/8.0;
        for (int component = 0; component < 6; component++)
            stresses[component] += h_nodestresses[component][node]/8;

        *vonMises += h_nodevonmises[node]/8.0;
    }
    return true;
}
/**********************************************************************/
bool AFElasticity::getElasticitySolutionAt(double pt[3],double uvw[3],double stresses[6],double *vonMises)
{
    int elem,nodes[8],node;
    if (!h_voxelgrid) return false;

    uvw[0] = uvw[1] = uvw[2] = 0;
    for (int component = 0; component < 6; component++)
        stresses[component] = 0;
    *vonMises = 0;

    elem = findNonVoidElemClosestTo(pt[0],pt[1],pt[2],3);// within relative tolerance
    if ((elem < 0) || (elem >= h_nElems))
        return false;

    getElemNodes(elem,nodes);
    int method;
    method = 1;

    if (method == 0) {
        // at the center
        for (int m = 0;m < 8; m++) {
            node = nodes[m];
            uvw[0] += h_sol[3*node]/8.0;
            uvw[1] += h_sol[3*node+1]/8.0;
            uvw[2] += h_sol[3*node+2]/8.0;
            for (int component = 0; component < 6; component++)
                stresses[component] += h_nodestresses[component][node]/8;

            *vonMises += h_nodevonmises[node]/8.0;
        }

    }
    else {
        // more accurate based on interpolation

        double xietamu[3],x[8],y[8],z[8],unode[8],vnode[8],wnode[8],stressesNodes[8][6],N[8],vonMisesAtNodes[8];
        //get the element corners

        for (int m = 0;m < 8; m++) {
            x[m] = h_x[nodes[m]];
            y[m] = h_y[nodes[m]];
            z[m] = h_z[nodes[m]];
        }
        // find the normalized coordinates of point
        xietamu[0] = (2*pt[0] - (x[1]+x[0]))/(x[1] - x[0]);
        xietamu[1] = (2*pt[1] - (y[2]+y[1]))/(y[2] - y[1]);
        xietamu[2] = (2*pt[2] - (z[4]+z[0]))/(z[4] - z[0]);

        for (int m =0; m <3; m++)
            xietamu[m] = MAX(-1,MIN(xietamu[m],1));

        getElemNodesVonMisesStresses(elem,vonMisesAtNodes);
        // now get the solution
        for (int m = 0;m < 8; m++) {
            node = h_elems[(h_nElems)*m + elem];
            unode[m] = h_sol[3*node];
            vnode[m] = h_sol[3*node+1];
            wnode[m] = h_sol[3*node+2];

            for (int component = 0; component < 6; component++)
                stressesNodes[m][component] = h_nodestresses[component][node];
        }

        computeN(xietamu[0],xietamu[1],xietamu[2],N);
        uvw[0] = uvw[1] = uvw[2] = 0;
        stresses[0] = stresses[1] = stresses[2] = stresses[3] = stresses[4] = stresses[5] = 0;
        *vonMises  = 0;
        for (int m = 0;m < 8; m++) {
            uvw[0] += N[m]*unode[m];
            uvw[1] += N[m]*vnode[m];
            uvw[2] += N[m]*wnode[m];
            for (int component = 0; component < 6; component++)
                stresses[component] += N[m]*stressesNodes[m][component];
            *vonMises += N[m]*vonMisesAtNodes[m];
        }
    }
    return true;
}
/**********************************************************************/
bool AFElasticity::getModalSolutionAt(double pt[3],int eigenMode,double modaluvw[3])
{
    int elem,nodes[8],node;
    if (!h_voxelgrid) return false;

    if (eigenMode < 0) return false;

    modaluvw[0] = modaluvw[1] = modaluvw[2] = 0;


    elem = findNonVoidElemClosestTo(pt[0],pt[1],pt[2],3);// within relative tolerance
    //return true;
    if ((elem < 0) || (elem >= h_nElems)) {
        return false;
    }

    getElemNodes(elem,nodes);
    // at the center
    for (int m = 0;m < 8; m++) {
        node = nodes[m];
        modaluvw[0] += h_eigenModes[eigenMode][3*node]/8.0;
        modaluvw[1] += h_eigenModes[eigenMode][3*node+1]/8.0;
        modaluvw[2] += h_eigenModes[eigenMode][3*node+2]/8.0;

    }
    //return true;// if we return here, it will be a crude approximation
    double xietamu[3],x[8],y[8],z[8],unode[8],vnode[8],wnode[8],N[8];
    //get the element corners

    for (int m = 0;m < 8; m++) {
        x[m] = h_x[nodes[m]];
        y[m] = h_y[nodes[m]];
        z[m] = h_z[nodes[m]];
    }
    // find the normalized coordinates of point
    xietamu[0] = (2*pt[0] - (x[1]+x[0]))/(x[1] - x[0]);
    xietamu[1] = (2*pt[1] - (y[2]+y[1]))/(y[2] - y[1]);
    xietamu[2] = (2*pt[2] - (z[4]+z[0]))/(z[4] - z[0]);

    for (int m =0; m <3; m++)
        xietamu[m] = MAX(-1,MIN(xietamu[m],1));

    // now get the solution
    for (int m = 0;m < 8; m++) {
        node = h_elems[(h_nElems)*m + elem];
        unode[m] = h_eigenModes[eigenMode][3*node];
        vnode[m] = h_eigenModes[eigenMode][3*node+1];
        wnode[m] = h_eigenModes[eigenMode][3*node+2];
    }
    computeN(xietamu[0],xietamu[1],xietamu[2],N);
    modaluvw[0] = modaluvw[1] = modaluvw[2] = 0;

    for (int m = 0;m < 8; m++) {
        modaluvw[0] += N[m]*unode[m];
        modaluvw[1] += N[m]*vnode[m];
        modaluvw[2] += N[m]*wnode[m];
    }
    return true;
}
