void AFElasticity::getNodeDeformation(int node,double *u,double *v,double *w,double *vonmises)
{
    *u = h_sol[3*node];
    *v = h_sol[3*node+1];
    *w = h_sol[3*node+2];
    *vonmises = h_nodevonmises[node];
}
