/**********************************************************************/
void AFElasticity::getBoundingBox(double boundingBox[3][2])
{
    boundingBox[0][0] = h_xMin;
    boundingBox[1][0] = h_yMin;
    boundingBox[2][0] = h_zMin;

    boundingBox[0][1] = h_xMin + h_nelx*h_dx;
    boundingBox[1][1] = h_yMin + h_nely*h_dy;
    boundingBox[2][1] = h_zMin + h_nelz*h_dz;

}
/**********************************************************************/
void AFElasticity::getCenterOfGeometry(double center[3])
{
    double boundingBox[3][2];
    getBoundingBox(boundingBox);

    for(int i = 0; i < 3; i++)
        center[i] = (boundingBox[i][0] + boundingBox[i][1])/2.0;
}

/**********************************************************************/
void AFElasticity::getElemNodesStresses(int elem,int component,double stresses[8])
{
    int node;
    for (int m = 0;m < 8; m++) {
        node = h_elems[(h_nElems)*m + elem];
        stresses[m] = h_nodestresses[component][node];
    }
}
/**********************************************************************/
void AFElasticity::getElemNodesVonMisesStresses(int elem,double stresses[8])
{
    int node;

    for (int m = 0;m < 8; m++) {
        node = h_elems[(h_nElems)*m + elem];
        stresses[m] = h_nodevonmises[node];
    }
}
/**********************************************************************/
void AFElasticity::getElemNodesForceNorm(int elem,double forces[8])
{
    int node;

    for (int m = 0;m < 8; m++) {
        node = h_elems[(h_nElems)*m + elem];
        forces[m] = sqrt(h_f[3*node]*h_f[3*node] +  h_f[3*node+1]*h_f[3*node+1] +  h_f[3*node+2]*h_f[3*node+2]);
    }
}
/**********************************************************************/
double AFElasticity::getElemVonMisesStress(int elem)
{
    double vonMises,vonMisesNodes[8];
    int counter;
    getElemNodesVonMisesStresses(elem,vonMisesNodes);
    vonMises= 0;
    counter = 0;
    for (int i = 0; i < 8; i++){
        if (vonMisesNodes[i] > 0) {// non void
            vonMises +=vonMisesNodes[i];
            counter++;
        }
    }
    counter = MAX(1,counter);// avoid division by 0
    return vonMises/counter;
}
/**********************************************************************/
void	AFElasticity::getAllElemVonMisesStresses(double *vonMises)
{
    // assumes memory has been allocated by user
    for (int elem = 0; elem < h_nElems; elem++)
        vonMises[elem] = getElemVonMisesStress(elem);
}
