/**********************************************************************/
void AFElasticity::computeDistanceOfNodesToEvolvingBoundary(double *distanceToBoundary)
{
    // find the signed distance from each node to the evolving boundary
    // if the node is inside, the distance is positive, else negative
    // assumed that the memory is allocated for distanceToBoundary
    // Algorithm
    // 1.Find all nodes on the  evolving boundary, and set the distance to zero
    // 2.Find all neighbors of processed nodes and increment/decrement distance
    // 3. Repeat until no other node is left to process

    Timer tempTimer;
    int node0, *neighboringNodes,nNeighboringNodes,node1;
    IntegerSet lastSetOfProcessedNodes,tempSet;
    bool *nodeProcessed;
    double dist0,meshSize,minDistance,maxDistance;

    tempTimer.start();
    meshSize = MIN(MIN(h_dx,h_dy),h_dz);

    neighboringNodes = (int *)malloc(h_nNodes*sizeof(int));
    nodeProcessed = (bool *)malloc(h_nNodes*sizeof(bool));

    memset(distanceToBoundary,0,h_nNodes*sizeof(double));
    memset(neighboringNodes,0,h_nNodes*sizeof(int));
    memset(nodeProcessed,0,h_nNodes*sizeof(bool));
    lastSetOfProcessedNodes.clear();
    for (int node = 0; node < h_nNodes; node++){
        if (isNodeOnEvolvingBoundary(node)){
            distanceToBoundary[node] = 0.0;
            lastSetOfProcessedNodes.insertNoCheckForUnique(node);
            nodeProcessed[node] = true;
        }
    }
    minDistance = maxDistance = 0;
    tempSet.clear();
    while (lastSetOfProcessedNodes.size() > 0){
        for (int i = 0; i < lastSetOfProcessedNodes.size(); i++){
            node0 = lastSetOfProcessedNodes.elementAt(i);
            dist0 = distanceToBoundary[node0];
            nNeighboringNodes = getAllNeighborNodesOfNode(node0,neighboringNodes);
            for (int k = 0; k < nNeighboringNodes; k++ ){
                node1 = neighboringNodes[k];
                if (nodeProcessed[node1]) continue;
                tempSet.insertNoCheckForUnique(node1);
                if (isNodeWithinEvolvingMesh(node1))
                    distanceToBoundary[node1] = dist0 + meshSize;
                else
                    distanceToBoundary[node1] = dist0 - meshSize;
                minDistance = MIN(minDistance,distanceToBoundary[node1]);
                maxDistance = MAX(maxDistance,distanceToBoundary[node1]);
                nodeProcessed[node1] = true;
            }
        }
        lastSetOfProcessedNodes.clear();
        // copy all the last set of processed nodes
        for (int k = 0; k < tempSet.size(); k++)
            lastSetOfProcessedNodes.insertCheckForUnique(tempSet.elementAt(k));
        tempSet.clear();
    }

    //cout << "Min distance: " << minDistance << "; max distance: " << maxDistance << endl;
    lastSetOfProcessedNodes.clear();
    tempSet.clear();

    free(nodeProcessed);
    free(neighboringNodes);
    //cout << "Time in secs: " << tempTimer.getElapsedTimeInSec()<< endl;
}
/**********************************************************************/
void AFElasticity::getNodeSignatures(int *nodeSignatures)
{
    memcpy(nodeSignatures,h_nodeSignature,h_nNodes*sizeof(int));
}
/**********************************************************************/
void AFElasticity::getNeighborNodes(int *neighborNodes)
{
    memcpy(neighborNodes,h_neighborNodes,27*h_nNodes*sizeof(int));
}
/**********************************************************************/
int AFElasticity::getAllNeighborNodesOfNode(int node,int *neighborNodes)
{
    // here, we are trying to find all nodes (whether they are in or out)
    // we cannot use h_neighborNodes since this data structure gets updated as
    // topology optimization proceeds
    int count,neighboringElements[8],nNeighboringElems,elem,elemNodes[8];
    IntegerSet nodeSet;
    count = 0;
    nNeighboringElems = getNeighboringElemsOfNode(node,neighboringElements);

    nodeSet.clear();
    for (int i = 0; i < nNeighboringElems; i++){
        elem = neighboringElements[i];
        getElemNodes(elem,elemNodes);
        for (int j = 0; j < 8; j++)
            nodeSet.insertCheckForUnique(elemNodes[j]);
    }
    count = 0;
    for (int j =0; j < nodeSet.size(); j++)
        neighborNodes[count++] = nodeSet.elementAt(j);

    nodeSet.clear();
    return count;
}
/**********************************************************************/
int AFElasticity::getNeighborNodesOfNode(int node,int *neighborNodes)
{
    int neighbor,count;
    count = 0;
    for (int j =0; j < 27; j++) {
        neighbor = h_neighborNodes[j*h_nNodes + node];
        if ((neighbor < 0) || (neighbor >= h_nNodes)) continue;
        if (!isNodeWithinEvolvingMesh(neighbor)) continue;
        neighborNodes[count++] = neighbor;
    }
    return count;
}
/**********************************************************************/
void AFElasticity::getElemDensityAtElemNodes(int elem,double pseudoDensity[8])
{
    int k,node,codedElemNum,nodeIndex;
    int nodeElem;
    for (int m = 0;m < 8; m++) {
        node = h_elems[(h_nElems)*m + elem];
        pseudoDensity[m] = 0.;
        for (k = 0; k < h_nNeighboringElems[node];k++) {
            //Note that both the index m and the element number are coded into a single integer
            codedElemNum = h_neighborElems[(h_nNodes)*k + node];
            nodeIndex = codedElemNum/MAXELEMS;
            nodeElem = codedElemNum - nodeIndex*MAXELEMS;
            pseudoDensity[m] += h_pseudoDensity[nodeElem];
        }
        pseudoDensity[m] /=  8.0;//h_nNeighboringElems[node];
    }
}
/**********************************************************************/
int AFElasticity::getNumberOfMeshComponents(void)
{
    return h_nMeshComponents;
}
/**********************************************************************/
int	AFElasticity::getMeshComponentOfElem(int elem)
{
    return h_elemComponent[elem];
}
/**********************************************************************/
bool AFElasticity::findConnectedComponentsOfMesh(bool reset)
{
    int elem,currentComponent,currentElem,neighborElem,component,startComponent;

    if (!h_voxelgrid) {
        writeMessageToParetoLog("ContourExtraction: Connected components only works on voxel grid");
        return false;
    }
    if(h_hexmesh_verbose) writeMessageToParetoLog("ContourExtraction: Finding connected components of mesh");
    Queue Q;
    bool isElemIn,isNeighborElemIn;

    if (reset){
        memset(h_elemComponent,-1,h_nElems*sizeof(int));// default of -1
        startComponent = 0;
    }
    else
        startComponent = 0;

    double discardComponentsCutoff = 0.001;
    currentComponent = startComponent;
    Q = CreateQueue(h_nElems);
    MakeEmpty(Q);
    for (elem = 0; elem < h_nElems;elem++) {
        if (h_elemComponent[elem] >=0) continue;// already assigned
        isElemIn = (getElemPseudoDensity(elem) > h_pseudoDensityCutoff);
        Enqueue(elem, Q); // add elem
        h_elemComponent[elem] = currentComponent;
        while (!IsEmpty(Q)) {
            currentElem = Front(Q);
            Dequeue(Q);
            for (int i=0;i<7;i++){// only consider 6 face neighbors + self
                neighborElem = h_StructuringElems[h_StructuringSize*currentElem+i];
                if (neighborElem == -1) continue;
                if (h_elemComponent[neighborElem] >= 0) continue;
                isNeighborElemIn = (getElemPseudoDensity(neighborElem) > h_pseudoDensityCutoff);
                if (isNeighborElemIn != isElemIn) continue;
                Enqueue(neighborElem, Q);
                h_elemComponent[neighborElem] = currentComponent;
            }
        }
        currentComponent++;
        MakeEmpty(Q);
    }
    DisposeQueue(Q);

    if(h_hexmesh_verbose) writeMessageToParetoLog("Number of Mesh Components = %d ",currentComponent);
    // many of these compoenents may contain very few elements ...get rid of these components
    double componentTolerance = discardComponentsCutoff*h_nElems;
    int *tempCounter = (int *)malloc(currentComponent*sizeof(int));
    memset(tempCounter,0,currentComponent*sizeof(int));
    // count the number of elements in each component
    for (elem = 0; elem < h_nElems; elem++) {
        component = h_elemComponent[elem];
        if ((component < 0) || (component >= currentComponent)) continue;
        tempCounter[component]++;
    }
    if(h_hexmesh_verbose)
        for (component = 0; component < currentComponent;component++)
            writeMessageToParetoLog("#Elements in component %d is %d ",component,tempCounter[component]);

    if(h_hexmesh_verbose)
        writeMessageToParetoLog("componentTolerance = %f ",componentTolerance);

    //now map components
    int *mapping = (int *)malloc(currentComponent*sizeof(int));
    int counter;
    counter = 0;
    for (component = 0; component < currentComponent;component++){
        mapping[component] = -1;//default
        if (tempCounter[component] > componentTolerance) {
            mapping[component] = counter;
            counter++;
        }
    }
    currentComponent = counter;
    for (elem = 0; elem < h_nElems; elem++) {
        component = h_elemComponent[elem];
        h_elemComponent[elem] = mapping[component];
    }
    safeFree(mapping);
    safeFree(tempCounter);

    if(h_hexmesh_verbose) writeMessageToParetoLog("Number of Mesh Components after deletion = %d ",currentComponent);

    h_nMeshComponents = currentComponent;

    return true;
}
/**********************************************************************/
bool AFElasticity::findConnectedSingleLargestComponentOfMesh(bool reset,double cutoff)
{
    int elem,currentComponent,currentElem,neighborElem,component,startComponent;

    if (!h_voxelgrid) {
        writeMessageToParetoLog("AFElasticity: Connected components only works on voxel grid");
        return false;
    }
    if(h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Finding connected components of mesh");
    Queue Q;
    double discardComponentsCutoff = 0.001;
    if (reset){
        memset(h_elemComponent,-1,h_nElems*sizeof(int));// default of -1
        startComponent = 0;
    }
    else
        startComponent = 0;

    currentComponent = startComponent;
    Q = CreateQueue(h_nElems);
    MakeEmpty(Q);
    for (elem = 0; elem < h_nElems;elem++) {
        if (h_elemComponent[elem] >=0) continue;// already assigned
        if(getElemPseudoDensity(elem) < cutoff) continue;
        Enqueue(elem, Q); // add elem
        h_elemComponent[elem] = currentComponent;
        while (!IsEmpty(Q)) {
            currentElem = Front(Q);
            Dequeue(Q);
            for (int i=0;i<7;i++){// only consider 6 face neighbors + self
                neighborElem = h_StructuringElems[h_StructuringSize*currentElem+i];
                if (neighborElem == -1) continue;
                if (h_elemComponent[neighborElem] >= 0) continue;
                if (getElemPseudoDensity(neighborElem) < cutoff) continue;
                Enqueue(neighborElem, Q);
                h_elemComponent[neighborElem] = currentComponent;
            }
        }
        currentComponent++;
        MakeEmpty(Q);
    }
    DisposeQueue(Q);

    if(h_hexmesh_verbose) writeMessageToParetoLog("Number of Mesh Components = %d ",currentComponent);
    // many of these compoenents may contain very few elements ...get rid of these components

    int *tempCounter = (int *)malloc(currentComponent*sizeof(int));
    memset(tempCounter,0,currentComponent*sizeof(int));
    // count the number of elements in each component
    for (elem = 0; elem < h_nElems; elem++) {
        component = h_elemComponent[elem];
        if ((component < 0) || (component >= currentComponent)) continue;
        tempCounter[component]++;
    }
    if(h_hexmesh_verbose)
        for (component = 0; component < currentComponent;component++)
            writeMessageToParetoLog("AFElasticity: #Elements in component %d is %d ",component,tempCounter[component]);


    //find out the component to retain
    int componentToRetain = 0, maxElemsInOneComponent = 0;
    for (component = 0; component < currentComponent;component++){
        if(tempCounter[component] > maxElemsInOneComponent){
            componentToRetain = component;
            maxElemsInOneComponent = tempCounter[component];
        }
    }

    for (elem = 0; elem < h_nElems; elem++) {
        component = h_elemComponent[elem];
        if(component == componentToRetain) {
            h_elemComponent[elem] = 0;
        }
        else {
            setPseudoDensityOfElem(elem,0);
            h_elemComponent[elem] = -1;
        }
    }

    h_nMeshComponents = 1;
    free(tempCounter);
    return true;
}
/**********************************************************************/
bool AFElasticity::findConnectedComponentsOfMesh_Material(bool reset)
{
    int elem,currentComponent,currentElem,neighborElem,component,startComponent;

    if (!h_voxelgrid) {
        writeMessageToParetoLog("AFElasticity: Connected components only works on voxel grid");
        return false;
    }

    double discardComponentsCutoff = 0.001;


    if(h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Finding connected components of mesh");
    Queue Q;
    bool isElemIn,isNeighborElemIn;
    int ElemMaterialID,NeighborMaterialID;
    if (reset){
        memset(h_elemComponent,-1,h_nElems*sizeof(int));// default of -1
        startComponent = 0;
    }
    else
        startComponent = h_nMeshComponents;

    currentComponent = startComponent;
    Q = CreateQueue(h_nElems);
    MakeEmpty(Q);
    for (elem = 0; elem < h_nElems;elem++) {
        if (h_elemComponent[elem] >=0) continue;

        isElemIn = (getElemPseudoDensity(elem) > h_pseudoDensityCutoff);
        if (!isElemIn) continue;
        ElemMaterialID = getMaterialIdOfElem(elem);
        Enqueue(elem, Q); // add elem
        h_elemComponent[elem] = currentComponent;
        while (!IsEmpty(Q)) {
            currentElem = Front(Q);
            Dequeue(Q);
            h_elemComponent[currentElem] = currentComponent;
            for (int i=0;i<h_StructuringSize;i++){
                neighborElem = h_StructuringElems[h_StructuringSize*currentElem+i];
                if (neighborElem == -1) continue;
                isNeighborElemIn = (getElemPseudoDensity(neighborElem) > h_pseudoDensityCutoff);
                if (isNeighborElemIn != isElemIn) continue;
                NeighborMaterialID = getMaterialIdOfElem(neighborElem);
                if (NeighborMaterialID != ElemMaterialID) continue;
                if ( (neighborElem != -1) && (h_elemComponent[neighborElem] == -1)){//not visited
                    Enqueue(neighborElem, Q);
                    h_elemComponent[neighborElem] = currentComponent;
                }
            }
        }
        currentComponent++;
    }
    DisposeQueue(Q);
    if(h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Number of Mesh Components = %d ",currentComponent);
    // many of these compoenents may contain very few elements ...get rid of these components
    double componentTolerance = discardComponentsCutoff*h_nElems;
    int *tempCounter = (int *)malloc(currentComponent*sizeof(int));
    memset(tempCounter,0,currentComponent*sizeof(int));
    // count the number of elements in each component
    for (elem = 0; elem < h_nElems; elem++) {
        component = h_elemComponent[elem];
        if ((component < 0) || (component >= currentComponent)) continue;
        tempCounter[component]++;
    }
    //now map components
    int *mapping = (int *)malloc(currentComponent*sizeof(int));
    int counter;
    counter = 0;
    for (component = 0; component < currentComponent;component++){
        if(h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Component %d size is %d ",component,tempCounter[component]);
        mapping[component] = -1;//default
        if (tempCounter[component] > componentTolerance) {
            mapping[component] = counter;
            counter++;
        }
    }
    currentComponent = counter;
    for (elem = 0; elem < h_nElems; elem++) {
        component = h_elemComponent[elem];
        h_elemComponent[elem] = mapping[component];
    }
    free(mapping);
    free(tempCounter);
    if(h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Number of Mesh Components after deletion = %d",currentComponent);

    h_nMeshComponents = currentComponent;

    return true;
}
/**********************************************************************/
void AFElasticity::clearNodeExists(void)
{
    for (int node =0; node < h_nNodes;node++)
        h_nodeExists[node] = false;

#ifdef COMPILE_GPUCODE
    setGPUNodeExists( h_nNodes,h_nodeExists,&h_gpuData);
#endif
}
/**********************************************************************/
void  AFElasticity::removeHangingElems(void)
{
    int elem, node,neighboringElems[100],nNeighbors;

    if(h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: In removeHangingElems ");

    for (elem = 0; elem < h_nElems; elem++) {
        nNeighbors = getNeighboringElementsOfElem(elem,neighboringElems);
        if (nNeighbors <= 1)// element is not connected to any other element
            h_pseudoDensity[elem] = VOID_EPS;
    }
    clearNodeExists();
    for (node = 0; node < h_nNodes; node++) {
        nNeighbors = getNeighboringElemsOfNode(node,neighboringElems);
        for (int i = 0; i < nNeighbors; i++)
            if (h_pseudoDensity[neighboringElems[i]] > h_pseudoDensityCutoff)
                h_nodeExists[node] = true;
    }
    // for node based K*u, recompute node-neighbors
    if (isSpMVMethodNodeBased())
        findNeighboringNodesOfNodes();
#ifdef COMPILE_GPUCODE
    setGPUPseudoDensity(h_nElems,h_pseudoDensity,&h_gpuData);
    setGPUNodeExists( h_nNodes,h_nodeExists,&h_gpuData);
#endif
}
/**********************************************************************/
void AFElasticity::removeDeadMaterial(void)
{
    // assuming a static problem has been solved
    // remove elements if there is NO stress, unless there are forced to be kept
    int elem,node,m,nElemsRemoved,inElems,nodes[8];
    double vonMisesElem;

    if(h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: In removeDeadMaterial ");
    clearNodeExists();
    nElemsRemoved = 0;
    inElems = 0;
    for (elem = 0; elem < h_nElems; elem++) {
        if (h_pseudoDensity[elem] < h_pseudoDensityCutoff) continue;
        getElemNodes(elem,nodes);
        vonMisesElem = 0;
        for (int i = 0; i < 8; i++)
            vonMisesElem += h_nodevonmises[nodes[i]];
        vonMisesElem /=8;
        if ((vonMisesElem/h_vonmisesMax < 1e-7) && (!h_keepElem[elem]) ) {// element is 'dead'
            h_pseudoDensity[elem] = VOID_EPS;
            nElemsRemoved++;
        }
        if (h_pseudoDensity[elem] > h_pseudoDensityCutoff) {// bring the nodes back
            inElems++;
            for (m = 0;m < 8; m++) {
                node = h_elems[(h_nElems)*m + elem];
                h_nodeExists[node] = true;
            }
        }
    }

    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Number of dead elements removed: %d",nElemsRemoved);
#ifdef COMPILE_GPUCODE
    setGPUPseudoDensity(h_nElems,h_pseudoDensity,&h_gpuData);
    setGPUNodeExists( h_nNodes,h_nodeExists,&h_gpuData);
#endif

    // for node based K*u, recompute node-neighbors
    if (isSpMVMethodNodeBased()) {
        findNeighboringNodesOfNodes();
    }
    // make current static solution invalid
    if (nElemsRemoved > 0) {
        isStaticResultValid = false;
    }
    return;
}
/**********************************************************************/
void AFElasticity::deleteStaticFEAResults()
{
    isStaticResultValid = false;
    ReleaseWorkSpace();
}
/**********************************************************************/
bool AFElasticity::isStaticFEAValid()
{
    return isStaticResultValid;
}

/**********************************************************************/
void  AFElasticity::setElementToVoid(bool restart,double *topSensElem, double TSCutoff,int nElemsToRemoveMax)
{
    int elem,node,m,nElemsRemoved;


    clearNodeExists();
    nElemsRemoved= 0;

    for (elem = 0; elem < h_nElems; elem++) {
        if (restart)
            h_pseudoDensity[elem] = 1.0;// elements is 'in' to start with
        if ((topSensElem[elem] < TSCutoff) ) {// element below level-set
            h_pseudoDensity[elem] = VOID_EPS;
            nElemsRemoved++;
        }
        if (h_pseudoDensity[elem] > h_pseudoDensityCutoff) {
            for (m = 0;m < 8; m++) {
                node = h_elems[(h_nElems)*m + elem];
                h_nodeExists[node] = true;
            }
        }
        if (nElemsRemoved > nElemsToRemoveMax)
            break;
    }
    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Setting %d elements to void",nElemsRemoved);
    if (!h_isThereAcceleration)
        removeNonManifoldElements();// with acceleration this causes problems

    removeDisconnectedElements();

    ReleaseWorkSpace();// if assigned
#ifdef COMPILE_GPUCODE
    setGPUPseudoDensity(h_nElems,h_pseudoDensity,&h_gpuData);
    setGPUNodeExists( h_nNodes,h_nodeExists,&h_gpuData);
#endif

    // for node based K*u, recompute node-neighbors
    if (isSpMVMethodNodeBased())
        findNeighboringNodesOfNodes();

    isStaticResultValid = false; // make current static solution invalid
    return;
}
/**********************************************************************/
bool AFElasticity::removeDisconnectedElements(double cutoff)
{
    // cutoff is the SIMP density

    if (!h_voxelgrid) {
        writeMessageToParetoLog("AFElasticity: removeDisconnectedComponents only works on voxel grid");
        return false;
    }
    int elem,currentElem,neighborElem,startElement,nElemsToRemove;
    bool *elemVisited,foundOneElement;
    Queue Q;


    elemVisited = (bool *) malloc(h_nElems*sizeof(bool));
    memset(elemVisited,false,h_nElems*sizeof(false));
    Q = CreateQueue(h_nElems);
    MakeEmpty(Q);

    foundOneElement = false;
    for (elem = 0; elem < h_nElems;elem++) {
        if (!h_keepElem[elem]) continue;// find an element that we must keep
        if (elemVisited[elem]) continue;// try a different element
        foundOneElement = true;
        startElement = elem;
        Enqueue(startElement, Q); // add elem to queue
        elemVisited[startElement] = true;
        while (!IsEmpty(Q)) {
            currentElem = Front(Q);
            Dequeue(Q);
            for (int i=0;i<7;i++){// only consider 6 face neighbors + self
                neighborElem = h_StructuringElems[h_StructuringSize*currentElem+i];
                if (neighborElem == -1) continue;
                if (elemVisited[neighborElem]) continue;
                if (getElemPseudoDensity(neighborElem) < cutoff) continue;
                Enqueue(neighborElem, Q);
                elemVisited[neighborElem] = true;
            }
        }
    }
    if (!foundOneElement) return false;// this can happen for pure gravity problems
    MakeEmpty(Q);
    DisposeQueue(Q);
    nElemsToRemove= 0;
    for (elem = 0; elem < h_nElems;elem++) {
        if ((!elemVisited[elem]) && (getElemPseudoDensity(elem) > cutoff) && (!h_keepElem[elem])){
            setPseudoDensityOfElem(elem,0);// remove it
            nElemsToRemove++;
        }
    }
    if(h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Number of disconnected elements removed = %d ",nElemsToRemove);
    safeFree(elemVisited);
    return true;
}
/**********************************************************************/
void AFElasticity::setPseudoDensityOfElem(int elem,double pseudoDensity)
{
    int nodes[8];
    int elems[100],nElems;
    h_pseudoDensity[elem] = pseudoDensity;

    if (h_simpMode)
        return;// for SIMP mode, we don't turn off elements


    getElemNodes(elem,nodes);
    if (pseudoDensity > h_pseudoDensityCutoff) {// turning on element
        for (int i = 0; i < 8; i++)
            h_nodeExists[nodes[i]] = true;
        return;
    }
    //turning off element
    for (int i = 0; i < 8; i++) {
        h_nodeExists[nodes[i]] = false;
        nElems = getNeighboringElemsOfNode(nodes[i],elems);
        for (int j = 0; j < nElems; j++){
            if (h_pseudoDensity[elems[j]] > 0)
                h_nodeExists[nodes[i]] = true;
        }
    }
    ReleaseWorkSpace();
#ifdef COMPILE_GPUCODE
    setGPUPseudoDensity(h_nElems,h_pseudoDensity,&h_gpuData);
    setGPUNodeExists( h_nNodes,h_nodeExists,&h_gpuData);
#endif
}
/**********************************************************************/
void AFElasticity::setPseudoDensity(double *pseudoDensity)
{
    int node;
    if(h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: In setPseudoDensity");
    if (h_pseudoDensity == NULL){
        writeMessageToParetoLog("AFElasticity: Please allocate memory");
        return;
    }
    memcpy(h_pseudoDensity,pseudoDensity,h_nElems*sizeof(double));

    clearNodeExists();

    for (int elem = 0; elem < h_nElems;elem++) {
        if (h_pseudoDensity[elem] > 0) {
            for (int m = 0;m < 8; m++) {
                node = h_elems[(h_nElems)*m + elem];
                h_nodeExists[node] = true;
            }
        }
    }

    ReleaseWorkSpace();
#ifdef COMPILE_GPUCODE
    setGPUPseudoDensity(h_nElems,h_pseudoDensity,&h_gpuData);
    setGPUNodeExists( h_nNodes,h_nodeExists,&h_gpuData);
#endif

    // for node based K*u, recompute node-neighbors
    if (isSpMVMethodNodeBased())
        findNeighboringNodesOfNodes();

    isStaticResultValid = false; // make current static solution invalid
}
/**********************************************************************/
int AFElasticity::countNumElemsIn(void)
{
    int count;
    count = 0;
    for (int elem = 0; elem < h_nElems;elem++)
        if (h_pseudoDensity[elem] > 0.5)
            count++;

    return count;
}

/**********************************************************************/
void AFElasticity::initializePseudoDensity(void)
{
    clearNodeExists();
    for (int elem = 0; elem < h_nElems;elem++)
        h_pseudoDensity[elem] = 1.0;

    for (int node = 0; node < h_nNodes;node++)
        h_nodeExists[node] = true;

#ifdef COMPILE_GPUCODE
    setGPUPseudoDensity(h_nElems,h_pseudoDensity,&h_gpuData);
    setGPUNodeExists( h_nNodes,h_nodeExists,&h_gpuData);
#endif

    ReleaseWorkSpace();

    // for node based K*u, recompute node-neighbors
    if (isSpMVMethodNodeBased())
        findNeighboringNodesOfNodes();

    isStaticResultValid = false; // make current static solution invalid
}

