/**********************************************************************/
int AFElasticity::isNodeOnCorner(int node)
{
    if (h_nNeighboringElems[node] == 1)
        return 1;
    else
        return 0;
}
/**********************************************************************/
int AFElasticity::isNodeOnEdge(int node)
{
    if (h_nNeighboringElems[node] == 2)
        return 1;
    else
        return 0;
}
/**********************************************************************/
bool AFElasticity::isNodeOnBoundary(int node)
{
    if (h_nNeighboringElems[node] < 8)
        return true;
    else
        return false;
}
/**********************************************************************/
bool	AFElasticity::isNodeOnEvolvingBoundary(int node)
{	//surrounding elements include: in & out
    //Two cases:
    // (1) node is on boundary and is valid
    // (2) node is interior, and surrounded by both in and out elements

    bool oneElemInside, oneElemOutside;
    int  codedElemNum,nodeIndex,elem;

    if (!h_nodeExists[node]) return false;
    // case 1
    if (isNodeOnBoundary(node))// from above, we know that node  exists
        return true;

    oneElemInside = oneElemOutside = false;
    // case 2
    int maxElem = h_nNeighboringElems[node];// how many elements connected to node
    for (int j =0; j < maxElem; j++) {
        codedElemNum = h_neighborElems[(h_nNodes)*j + node];// process elem-j neighbor
        nodeIndex = codedElemNum/MAXELEMS;
        elem =codedElemNum - nodeIndex*MAXELEMS;
        if(getElemPseudoDensity(elem) < h_pseudoDensityCutoff)//  one elem is outside
            oneElemOutside = true;
        if(getElemPseudoDensity(elem) > h_pseudoDensityCutoff)//  one elem is inside
            oneElemInside = true;
    }
    if ((oneElemOutside) && (oneElemInside)) return true;
    else return false;

}
/**********************************************************************/
bool	AFElasticity::isNodeInInterior(int node)
{	
    int codedElemNum,nodeIndex,elem;
    int maxElem = h_nNeighboringElems[node];// how many elements connected to node
    if (maxElem < 8) return false;// interior nodes must have 8 neighboring elements
    for (int j =0; j < maxElem; j++) {
        codedElemNum = h_neighborElems[(h_nNodes)*j + node];// process elem-j neighbor
        nodeIndex = codedElemNum/MAXELEMS;
        elem =codedElemNum - nodeIndex*MAXELEMS;
        if(getElemPseudoDensity(elem) < h_pseudoDensityCutoff)
            return false;
    }
    return (true);
}
/**********************************************************************/
bool	AFElasticity::isNodeWithinEvolvingMesh(int node)
{	
    int codedElemNum,nodeIndex,elem;
    int maxElem = h_nNeighboringElems[node];// how many elements connected to node
    for (int j =0; j < maxElem; j++) {
        codedElemNum = h_neighborElems[(h_nNodes)*j + node];// process elem-j neighbor
        nodeIndex = codedElemNum/MAXELEMS;
        elem =codedElemNum - nodeIndex*MAXELEMS;
        if(getElemPseudoDensity(elem) > h_pseudoDensityCutoff)//  at least one elem inside
            return true;
    }
    return (false);
}
/**********************************************************************/
bool AFElasticity::isElemOnEvolvingBoundary(int element)
{	
    int neighbor;
    // if elem is void, it is not on evolving boundary
    if (h_pseudoDensity[element] < h_pseudoDensityCutoff) return false;

    // else, elem is on evolving boundary if any of the six face neighbors are absent
    for (int i=1;i<7;i++){// 0 is self, followed by 6 face neighbors
        neighbor = h_StructuringElems[h_StructuringSize*element+i];
        if (neighbor < 0) return true;
        if (h_pseudoDensity[neighbor] < h_pseudoDensityCutoff) return true;
    }
    return false;
}
/**********************************************************************/
bool AFElasticity::doesElemHaveConcaveEdge(int elem)
//Heuristic
{
    int nodes[8],i;
    getElemNodes(elem,nodes);
    for (i = 0; i < 8; i++) {
        if (isNodeOnConcaveEdge(nodes[i]))
            return true;//
    }
    return false;
}
/**********************************************************************/
bool AFElasticity::isNodeOnConcaveEdge(int node)
//Heuristic
{
    if ( (h_nNeighboringElems[node] == 3) || (h_nNeighboringElems[node] == 6))
        return true;
    else
        return false;
}
/**********************************************************************/
bool AFElasticity::isElemInInteriorOfPart(int elem, int part)
{
    // is the element entirely surrounded by other elements that belong to the given part
    int neighboringElements[27], nNeighbors;

    if (getPartIdOfElem(elem) != part) return false;
    nNeighbors = getNeighboringElementsOfElem(elem,neighboringElements);
    for (int i = 0; i < nNeighbors; i++)
        if (getPartIdOfElem(neighboringElements[i]) != part) return false;

    return true;
}
/**********************************************************************/
bool AFElasticity::isElemInInterior(int elem)
{
    int nodes[8],i;
    getElemNodes(elem,nodes);
    for (i = 0; i < 8; i++) {
        if (isNodeOnBoundary(nodes[i]))
            return false;// if any of the nodes are on the boundary, return false
    }
    return true;
}
/**********************************************************************/
bool AFElasticity::doesElemHaveConcaveNode(int elem)
{
    int nodes[8],i;
    getElemNodes(elem,nodes);
    for (i = 0; i < 8; i++) {
        if (isNodeOnConcaveEdge(nodes[i]))
            return true;//
    }
    return false;
}
