/**********************************************************************/
bool AFElasticity::isSpMVMethodNodeBased(void)
{
    return h_nodeBasedAssembly;
}
/**********************************************************************/
void AFElasticity::disableNodalSpMV(void)
{
    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: ElemBased SpMV ");

    h_nodeBasedAssembly = false;// if set to true, K*u and M*u are node-based; only valid for voxel meshes
}
/**********************************************************************/
void AFElasticity::enableNodalSpMV(void)
{
    if (((!h_voxelgrid) || (h_nMaterials > 1))){
        if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Nodebased SpMV only for voxel grid with single material");
        if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: ElemBased SpMV ");
        h_nodeBasedAssembly = false;// if set to true, K*u and M*u are node-based; only valid for voxel meshes
    }
    else if (h_voxelgrid){
        if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Nodebased SpMV ");
        h_nodeBasedAssembly = true;// if set to true, K*u and M*u are node-based; only valid for voxel meshes
    }
}
/**********************************************************************/
void AFElasticity::printPseudoDensityRange(void)
{
    double minVal = HUGE_VAL,maxVal = -HUGE_VAL;

    for (int i = 0; i < h_nElems;i++){
        minVal = min(minVal,h_pseudoDensity[i]);
        maxVal = max(maxVal,h_pseudoDensity[i]);
    }
    writeMessageToParetoLog("AFElasticity: Pseudodensity range: (%.3f, %.3f) ",minVal,maxVal);
}
/**********************************************************************/
void AFElasticity::setPseudoDensityLimits(double minValue,double maxValue)
{
    int node;
#pragma omp parallel for 
    for (int i = 0; i < h_nElems;i++)
        h_pseudoDensity[i] = min(max(h_pseudoDensity[i],minValue),maxValue);


    clearNodeExists();
    for (int elem = 0; elem < h_nElems;elem++) {
        if (h_pseudoDensity[elem] > 0) {
            for (int m = 0;m < 8; m++) {
                node = h_elems[(h_nElems)*m + elem];
                h_nodeExists[node] = true;
            }
        }
    }

    ReleaseWorkSpace();
#ifdef COMPILE_GPUCODE
    setGPUPseudoDensity(h_nElems,h_pseudoDensity,&h_gpuData);
#endif

    // for node based K*u, recompute node-neighbors
    if (isSpMVMethodNodeBased())
        findNeighboringNodesOfNodes();
}
