/**********************************************************************/
double AFElasticity::computeCompliance(void)
{
    int i;
    double J=0;

    for (i =0; i < h_nNodes; i++)
        if (h_nodeExists[i])
            J += (h_sol[3*i]*h_f[3*i] + h_sol[3*i+1]*h_f[3*i+1] + h_sol[3*i+2]*h_f[3*i+2]);
    return J;
}
/**********************************************************/
void AFElasticity::removeInherentStrainFromElements(int nElems,int *elems)
{
    int elem,elemnodes[8];
    for(int i = 0; i<nElems ; i++){
        elem = elems[i];
        getElemNodes(elem,elemnodes);
        for(int j = 0; j<8 ; j++) {
            h_f[3*elemnodes[j]]   = 0;
            h_f[3*elemnodes[j]+1] = 0;
            h_f[3*elemnodes[j]+2] = 0;
        }
    }
}

/**********************************************************/
void AFElasticity::addInherentStrainToElements(double strain[3], int nElems,int *elems)
{
    //compute the body force due to an inherent strain {ex,ey,ez} and apply to all elements listed
    double dx,dy,dz,Y,nu,alpha,rho,specificHeat,K;
    double fe[24],ex,ey,ez;
    int elemnodes[8],elem;
    char materialName[256];

    dx = h_dx;
    dy = h_dy;
    dz = h_dz;

    getMaterialOfPart(0,&Y,&nu,&rho,&K,&alpha,&specificHeat,materialName);
    ex = strain[0];
    ey = strain[1];
    ez = strain[2];

    //obtained from MatLab by doing triple integration of (dJ*B'*D*dummyvector')
    fe[0] = (Y*h_dy*h_dz*(ex*-2.0+ey+ez)*(1.0/1.2E1))/(nu+1.0)+(Y*h_dy*h_dz*(ex+ey+ez)*(1.0/1.2E1))/(nu*2.0-1.0);
    fe[1]= (Y*h_dy*h_dz*(ex*-2.0+ey+ez)*(-1.0/1.2E1))/(nu+1.0)-(Y*h_dy*h_dz*(ex+ey+ez)*(1.0/1.2E1))/(nu*2.0-1.0);
    fe[2]= (Y*h_dy*h_dz*(ex*-2.0+ey+ez)*(-1.0/1.2E1))/(nu+1.0)-(Y*h_dy*h_dz*(ex+ey+ez)*(1.0/1.2E1))/(nu*2.0-1.0);
    fe[3]= (Y*h_dy*h_dz*(ex*-2.0+ey+ez)*(1.0/1.2E1))/(nu+1.0)+(Y*h_dy*h_dz*(ex+ey+ez)*(1.0/1.2E1))/(nu*2.0-1.0);
    fe[4]= (Y*h_dy*h_dz*(ex*-2.0+ey+ez)*(1.0/1.2E1))/(nu+1.0)+(Y*h_dy*h_dz*(ex+ey+ez)*(1.0/1.2E1))/(nu*2.0-1.0);
    fe[5]= (Y*h_dy*h_dz*(ex*-2.0+ey+ez)*(-1.0/1.2E1))/(nu+1.0)-(Y*h_dy*h_dz*(ex+ey+ez)*(1.0/1.2E1))/(nu*2.0-1.0);
    fe[6]= (Y*h_dy*h_dz*(ex*-2.0+ey+ez)*(-1.0/1.2E1))/(nu+1.0)-(Y*h_dy*h_dz*(ex+ey+ez)*(1.0/1.2E1))/(nu*2.0-1.0);
    fe[7]= (Y*h_dy*h_dz*(ex*-2.0+ey+ez)*(1.0/1.2E1))/(nu+1.0)+(Y*h_dy*h_dz*(ex+ey+ez)*(1.0/1.2E1))/(nu*2.0-1.0);
    fe[8]= (Y*h_dx*h_dz*(ex-ey*2.0+ez)*(1.0/1.2E1))/(nu+1.0)+(Y*h_dx*h_dz*(ex+ey+ez)*(1.0/1.2E1))/(nu*2.0-1.0);
    fe[9]= (Y*h_dx*h_dz*(ex-ey*2.0+ez)*(1.0/1.2E1))/(nu+1.0)+(Y*h_dx*h_dz*(ex+ey+ez)*(1.0/1.2E1))/(nu*2.0-1.0);
    fe[10]= (Y*h_dx*h_dz*(ex-ey*2.0+ez)*(-1.0/1.2E1))/(nu+1.0)-(Y*h_dx*h_dz*(ex+ey+ez)*(1.0/1.2E1))/(nu*2.0-1.0);
    fe[11]= (Y*h_dx*h_dz*(ex-ey*2.0+ez)*(-1.0/1.2E1))/(nu+1.0)-(Y*h_dx*h_dz*(ex+ey+ez)*(1.0/1.2E1))/(nu*2.0-1.0);
    fe[12]= (Y*h_dx*h_dz*(ex-ey*2.0+ez)*(1.0/1.2E1))/(nu+1.0)+(Y*h_dx*h_dz*(ex+ey+ez)*(1.0/1.2E1))/(nu*2.0-1.0);
    fe[13]= (Y*h_dx*h_dz*(ex-ey*2.0+ez)*(1.0/1.2E1))/(nu+1.0)+(Y*h_dx*h_dz*(ex+ey+ez)*(1.0/1.2E1))/(nu*2.0-1.0);
    fe[14]= (Y*h_dx*h_dz*(ex-ey*2.0+ez)*(-1.0/1.2E1))/(nu+1.0)-(Y*h_dx*h_dz*(ex+ey+ez)*(1.0/1.2E1))/(nu*2.0-1.0);
    fe[15]= (Y*h_dx*h_dz*(ex-ey*2.0+ez)*(-1.0/1.2E1))/(nu+1.0)-(Y*h_dx*h_dz*(ex+ey+ez)*(1.0/1.2E1))/(nu*2.0-1.0);
    fe[16]= (Y*h_dx*h_dy*(ex+ey-ez*2.0)*(1.0/1.2E1))/(nu+1.0)+(Y*h_dx*h_dy*(ex+ey+ez)*(1.0/1.2E1))/(nu*2.0-1.0);
    fe[17]= (Y*h_dx*h_dy*(ex+ey-ez*2.0)*(1.0/1.2E1))/(nu+1.0)+(Y*h_dx*h_dy*(ex+ey+ez)*(1.0/1.2E1))/(nu*2.0-1.0);
    fe[18]= (Y*h_dx*h_dy*(ex+ey-ez*2.0)*(1.0/1.2E1))/(nu+1.0)+(Y*h_dx*h_dy*(ex+ey+ez)*(1.0/1.2E1))/(nu*2.0-1.0);
    fe[19]= (Y*h_dx*h_dy*(ex+ey-ez*2.0)*(1.0/1.2E1))/(nu+1.0)+(Y*h_dx*h_dy*(ex+ey+ez)*(1.0/1.2E1))/(nu*2.0-1.0);
    fe[20]= (Y*h_dx*h_dy*(ex+ey-ez*2.0)*(-1.0/1.2E1))/(nu+1.0)-(Y*h_dx*h_dy*(ex+ey+ez)*(1.0/1.2E1))/(nu*2.0-1.0);
    fe[21]= (Y*h_dx*h_dy*(ex+ey-ez*2.0)*(-1.0/1.2E1))/(nu+1.0)-(Y*h_dx*h_dy*(ex+ey+ez)*(1.0/1.2E1))/(nu*2.0-1.0);
    fe[22]= (Y*h_dx*h_dy*(ex+ey-ez*2.0)*(-1.0/1.2E1))/(nu+1.0)-(Y*h_dx*h_dy*(ex+ey+ez)*(1.0/1.2E1))/(nu*2.0-1.0);
    fe[23]= (Y*h_dx*h_dy*(ex+ey-ez*2.0)*(-1.0/1.2E1))/(nu+1.0)-(Y*h_dx*h_dy*(ex+ey+ez)*(1.0/1.2E1))/(nu*2.0-1.0);

    for(int i = 0; i<nElems ; i++){
        elem = elems[i];
        if (getElemPseudoDensity(elem) < h_pseudoDensityCutoff) continue;
        getElemNodes(elem,elemnodes);
        for(int j = 0; j<8 ; j++) {
            if (isNodeFree(elemnodes[j])) {
                h_f[3*elemnodes[j]]   += fe[j];
                h_f[3*elemnodes[j]+1] += fe[j+8];
                h_f[3*elemnodes[j]+2] += fe[j+16];
            }
        }
    }
}

