/**********************************************************************/
void AFElasticity::initializeToZeros(double *x)
{
    int i;
#pragma omp parallel for private(i)
    for (i =0; i < 3*h_nNodes; i++)
        x[i] = 0;
}
/**********************************************************************/
void AFElasticity::enforceDirichlet0(double *x)
{
    int i,freeEncoded,wfree,ufree,vfree;

#pragma omp parallel for private(i,freeEncoded,wfree,ufree,vfree)
    for (i =0; i < h_nNodes; i++) {
        if (!doesNodeExist(i)) continue;
        freeEncoded = h_free[i];
        wfree = freeEncoded/4;// 0 (fixed) or 1 (free)
        vfree = (freeEncoded - wfree*4)/2;// 0 or 1
        ufree = (freeEncoded - wfree*4 -vfree*2);// 0 or 1
        x[3*i] *= ufree;
        x[3*i+1] *= vfree;
        x[3*i+2] *= wfree;
    }
}
/**********************************************************************/
void AFElasticity::enforceDirichlet(double *x)
{
    int i,freeEncoded,wfree,ufree,vfree;

    for (i =0; i < h_nNodes; i++) {
        if (!doesNodeExist(i)) continue;
        freeEncoded = h_free[i];
        wfree = freeEncoded/4;
        vfree = (freeEncoded - wfree*4)/2;
        ufree = (freeEncoded - wfree*4 -vfree*2);
        if (!ufree) x[3*i] = h_dirichlet[3*i];
        if (!vfree) x[3*i+1] = h_dirichlet[3*i+1];
        if (!wfree) x[3*i+2] =h_dirichlet[3*i+2];
    }
}
/**********************************************************************/
void AFElasticity::initializeRandomVector(double *x)
{
    int i,freeEncoded,wfree,ufree,vfree;

    for (i =0; i < h_nNodes; i++) {
        if (!doesNodeExist(i)) continue;
        freeEncoded = h_free[i];
        wfree = freeEncoded/4;
        vfree = (freeEncoded - wfree*4)/2;
        ufree = (freeEncoded - wfree*4 -vfree*2);
        x[3*i] = 1.0*ufree*rand()/RAND_MAX;// 0 if Dirichlet else random
        x[3*i+1]  = 1.0*vfree*rand()/RAND_MAX;
        x[3*i+2]  = 1.0*wfree*rand()/RAND_MAX;
    }
}
/**********************************************************************/
void AFElasticity::initializeSolution(void)
{
    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: initializeSolution()");
    memcpy(h_sol,h_dirichlet,3*h_nNodes*sizeof(double));
    isStaticResultValid = false; // make the current solution invalid

#ifdef COMPILE_GPUCODE
    setGPUSolution(h_nNodes,h_sol,&h_gpuData);
#endif
}
/**********************************************************************/
void AFElasticity::allocVector(int N,double **x)
{
    *x = (double *)malloc(N*sizeof(double));
}
/**********************************************************************/
void AFElasticity::allocMatrix(int N,int M,double ***A)
{
    int i;

    *A = (double **)malloc(N*sizeof(double *));
    for (i=0; i < N; i++)
        (*A)[i] = (double *)malloc(M*sizeof(double));
}

/**********************************************************************/
void AFElasticity::freeMatrix(int N,double **A)
{
    int i;

    if (A == NULL) return;
    for (i=0; i < N; i++)
        if (A[i] != NULL)
            free(A[i]);
    free(A);
}
/**********************************************************************/
int AFElasticity::findDuplicateIsotropicMaterial(double E, double nu,double rho,double K,double alpha,double specificHeat)
{
    int duplicateMaterial;
    double E0,nu0,rho0,K0,alpha0,specificHeat0,err[6];

    if (h_hexmesh_verbose) cout << ">>Entering " << __func__ << endl;
    duplicateMaterial = -1; // no duplicate
    if (h_nMaterials == 0) return duplicateMaterial;

    if ( (fabs(E) < 1.0/HUGE_VAL) || (fabs(nu) < 1.0/HUGE_VAL) || (fabs(rho) < 1.0/HUGE_VAL)|| (fabs(alpha) < 1.0/HUGE_VAL)|| (fabs(specificHeat) < 1.0/HUGE_VAL)){
        writeMessageToParetoLog("AFElasticity:\tError in findDuplicateIsotropicMaterial, incorrect material properties");
        return duplicateMaterial;
    }

    for (int matl =0; matl < h_nMaterials;matl++) {
        E0 = h_E[matl];
        nu0 = h_nu[matl];
        rho0 = h_rho[matl];
        K0 = h_conductivity[matl];
        alpha0 = h_alpha[matl];
        specificHeat0 = h_specificHeat[matl];

        if (h_hexmesh_verbose) writeMessageToParetoLog("Reference material (%d): %.2e %.2e %.2e %.2e %.2e %.2e ",matl,E0,nu0,rho0,K0,alpha0,specificHeat0);
        err[0] = fabs(E-E0)/(E0+1e-32);
        err[1] = fabs(nu-nu0)/(nu0+1e-32);
        err[2] = fabs(rho-rho0)/(rho0+1e-32);
        err[3] = fabs(K-K0)/(K0+1e-32);
        err[4] = fabs(alpha-alpha0)/(alpha0+1e-32);
        err[5] = fabs(specificHeat-specificHeat0)/(specificHeat0+1e-32);
        //if (h_hexmesh_verbose) writeMessageToParetoLog("Error: %.2e %.2e %.2e %.2e %.2e %.2e ",err[0],err[1],err[2],err[3],err[4],err[5]);

        if ((err[0]+err[1]+err[2]+err[3]+err[4]+err[5]) < 1e-6){
            duplicateMaterial = matl;
            break;
        }
    }
    return duplicateMaterial;
}
/**********************************************************************/
bool	 AFElasticity::getElasticMaterialProperties(int matID,double *E,double *nu)
{
    if ( (matID <0) || (matID >= h_nMaterials)) return false;
    *E = h_E[matID];
    *nu = h_nu[matID];

    return true;
}
/**********************************************************************/
bool AFElasticity::shouldPartBeOptimized(int partNum)
{
    return h_partOptimize[partNum];
}
/**********************************************************************/
void AFElasticity::setPartToBeOptimized(int partNum)
{
    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: In setPartToBeOptimized; partNum = %d",partNum);

    if (partNum >= h_nParts){
        writeMessageToParetoLog("AFElasticity:Part %d exceeds current max (%d) \n",partNum,h_nParts);
    }
    h_partOptimize[partNum] = true;
}
/**********************************************************************/
void AFElasticity::setMaterialIndexOfPart(int partNum,int materialIndex)
{
    if ((partNum < 0) || (partNum >= h_nParts))
        return;

    if ((materialIndex < 0) || (materialIndex >= h_nMaterials))
        return;

    h_partToMaterialMap[partNum] = materialIndex;
}
/**********************************************************************/
void AFElasticity::setPartToNonDesign(int partNum)
{
    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: In setPartToNonDesign; partNum = %d",partNum);

    if (partNum >= h_nParts){
        writeMessageToParetoLog("AFElasticity:Part %d exceeds current max (%d) ",partNum,h_nParts);
    }
    h_partOptimize[partNum] = false;
}
/**********************************************************************/
void AFElasticity::keepUnusedMaterial(bool state)
{
    h_keepAllMaterials = state;
}
/**********************************************************************/
bool AFElasticity::setIsotropicMaterialPropertiesOfPart(int partNum, double materialProperties[7],const char *materialName,double materialPrice)
{
    int matlIndex;
    double E,nu,Y,rho,K,alpha,Cp;

    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: In setIsotropicMaterialOfPart; h_nMaterials = %d",h_nMaterials);

    E = materialProperties[0];
    nu = materialProperties[1];
    Y = materialProperties[2];// Yield strength
    rho = materialProperties[3];
    K = materialProperties[4];
    alpha = materialProperties[5];
    Cp = materialProperties[6];

    isStaticResultValid = false;
    if (h_hexmesh_verbose) writeMessageToParetoLog("Incoming material: %.2e %.2e %.2e %.2e %.2e %.2e %.2g ",E,nu,rho,K,alpha,Cp,materialPrice);

    h_nParts = MAX(h_nParts,partNum+1);
    if (h_nParts >= MAX_PARTS){
        writeMessageToParetoLog("AFElasticity: Number of parts exceeds maximum allowed (%d) ",MAX_PARTS);
        return false;
    }
    // first check if this material already exists
    matlIndex = findDuplicateIsotropicMaterial(E,nu,rho,K,alpha,Cp);

    if (matlIndex < 0) {//this material does not exist
        //  check if the partNum already has a different material

        // we will not have to create a new materialID if this is the only part
        if ((!h_keepAllMaterials) && (h_nParts == 1) && (h_partToMaterialMap[partNum] >= 0)) {// if so, overwrite
            matlIndex = h_partToMaterialMap[partNum];
        }
        else {//create a new material
            if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Creating new material %d",h_nMaterials);
            matlIndex = h_nMaterials;
            h_nMaterials++;// increase the number of materials
            if (h_nMaterials >= MAX_MATERIALS) {
                if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Number of materials exceeds maximum allowed (%d) ",MAX_MATERIALS);
                h_nMaterials = MAX(h_nMaterials,MAX_MATERIALS);
                return false;
            }

        }

        strcpy(h_materialName[matlIndex],materialName);
        h_E[matlIndex] = E;
        h_nu[matlIndex] = nu;
        h_Y[matlIndex] = Y;
        h_rho[matlIndex] = rho;
        h_conductivity[matlIndex] = K;
        h_alpha[matlIndex] = alpha;
        h_specificHeat[matlIndex] = Cp;
        h_materialPrice[matlIndex] = materialPrice;
        computeIsotropicDMatrix(matlIndex,E,nu);

        if (h_hexmesh_verbose) cout <<"AFElasticity: Completing setIsotropicMaterialOfPart; h_nMaterials = " << h_nMaterials << endl;
    }
    else {
        h_Y[matlIndex] = Y;// material exists (from stiffness perspective), just overwrite yield strength
    }
    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Part %d assigned to material index %d",partNum,matlIndex);
    h_partToMaterialMap[partNum] = matlIndex;

    if (h_nMaterials > 1) {
        if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity:h_nMaterials = %d ... disabling nodalSpMV",h_nMaterials);
        disableNodalSpMV(); // node-based SpMV not allowed for multiple materials
    }
    releaseKeAndMeNodal();
    return true;
}

/**********************************************************************/
bool AFElasticity::setIsotropicMaterialOfPart(int partNum, double E, double nu,double rho,double K, double alpha, double specificHeat,const char *materialName)
{
    int matlIndex;

    if (h_hexmesh_verbose) cout <<"AFElasticity: In setIsotropicMaterialOfPart; h_nMaterials = " << h_nMaterials << endl;

    isStaticResultValid = false;
    if (h_hexmesh_verbose) writeMessageToParetoLog("Incoming material: %.2e %.2e %.2e %.2e %.2e %.2e ",E,nu,rho,K,alpha,specificHeat);
    h_nParts = MAX(h_nParts,partNum+1);
    if (h_nParts >= MAX_PARTS){
        writeMessageToParetoLog("AFElasticity: Number of parts exceeds maximum allowed (%d) ",MAX_PARTS);
        return false;
    }
    // first check if this material already exists
    matlIndex = findDuplicateIsotropicMaterial(E,nu,rho,K,alpha,specificHeat);

    if (matlIndex < 0) {//this material does not exist
        //  check if the partNum already has a different material
        if (h_partToMaterialMap[partNum] >= 0) {// if so, overwrite
            matlIndex = h_partToMaterialMap[partNum];
        }
        else {//create a new material
            if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Creating new material %d",h_nMaterials);
            matlIndex = h_nMaterials;
            h_nMaterials++;// increase the number of materials
            if (h_nMaterials >= MAX_MATERIALS) {
                if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Number of materials exceeds maximum allowed (%d) ",MAX_MATERIALS);
                h_nMaterials = MAX(h_nMaterials,MAX_MATERIALS);
                return false;
            }
        }

        strcpy(h_materialName[matlIndex],materialName);
        h_E[matlIndex] = E;
        h_nu[matlIndex] = nu;
        h_rho[matlIndex] = rho;
        h_conductivity[matlIndex] = K;
        h_alpha[matlIndex] = alpha;
        h_specificHeat[matlIndex] = specificHeat;
        computeIsotropicDMatrix(matlIndex,E,nu);
        //if (h_hexmesh_verbose)  printDMatrix(matlIndex);
        if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: In setIsotropicMaterialOfPart; h_nMaterials = %d",h_nMaterials);
    }

    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Part %d assigned to material index %d",partNum,matlIndex);
    h_partToMaterialMap[partNum] = matlIndex;

    if (h_nMaterials > 1) {
        if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity:h_nMaterials = %d ... disabling nodalSpMV",h_nMaterials);
        disableNodalSpMV(); // node-based SpMV not allowed for multiple materials
    }
    releaseKeAndMeNodal();
    cout << endl;
    return true;
}
/**********************************************************************/
int AFElasticity::generateCuboidMesh(int nElemsDesired, double boundingBox[3][2])
{
    // Initialize the following data
    /*
    % 1. Number of nodes
    % 2. Number of elements
    % 3. The max number of template elements (1 for a regular isotropic mesh)
    % 4. Max number of elements connected to any node (8 for a regular grid)
    % 5. For every element, its 8 nodes (mesh description)
    % 6. For every node, its neighboring elements, padded with zeros if necessary
    % 7. The number of Dirichlet dof
    % 8. All the Dirichlet dof
    % 9. The number of forced dof
    % 10. All the forced dof
    % 11. The forces at these dof
    % 12. For every element, its KElement ID (ranging from 1 to M)
    % 13. For each of the M distinct KElementID, 24*24 values

    */
    int node,elem,i,j,k,m,startNode,nels[3];
    int nelx,nely,nelz;
    double dx,dy,dz,Lx,Ly,Lz,volume,h,eta[3],maxAspectRatio,dsize[3];


    maxAspectRatio = 1.;

    Lx = (boundingBox[0][1]-boundingBox[0][0]);
    Ly = (boundingBox[1][1]-boundingBox[1][0]);
    Lz = (boundingBox[2][1]-boundingBox[2][0]);
    volume = Lx*Ly*Lz;
    h = pow(volume/nElemsDesired,1./3.0);// cube-root of ..


    if ((Lx > Ly) && (Lx > Lz)) {
        eta[0] = 1.0;
        eta[1] = MAX(Ly/Lx,1./maxAspectRatio);// between 0 and 1
        eta[2] = MAX(Lz/Lx,1./maxAspectRatio);

        dsize[0] = pow(volume/nElemsDesired/(eta[0]*eta[1]*eta[2]),1./3.0);// cube-root of
        dsize[1] = dsize[0]*eta[1];
        dsize[2] = dsize[0]*eta[2];
    }
    else if ((Ly > Lx) && (Ly > Lz)) {
        eta[1] = 1.0;
        eta[0] = MAX(Lx/Ly,1./maxAspectRatio);// between 0 and 1
        eta[2] = MAX(Lz/Ly,1./maxAspectRatio);

        dsize[1] = pow(volume/nElemsDesired/(eta[0]*eta[1]*eta[2]),1./3.0);// cube-root of
        dsize[0] = dsize[1]*eta[0];
        dsize[2] = dsize[1]*eta[2];
    }
    else if ((Lz > Lx) && (Lz > Lx)) {
        eta[2] = 1.0;
        eta[0] = MAX(Lx/Lz,1./maxAspectRatio);// between 0 and 1
        eta[1] = MAX(Ly/Lz,1./maxAspectRatio);

        dsize[2] = pow(volume/nElemsDesired/(eta[0]*eta[1]*eta[2]),1./3.0);// cube-root of
        dsize[0] = dsize[2]*eta[0];
        dsize[1] = dsize[2]*eta[1];
    }
    else {
        dsize[0]  =h;
        dsize[1] = h;
        dsize[2] = h;
    }
    nels[0] = (int) MAX(NEARESTINT(Lx/dsize[0]),2);
    nels[1] = (int) MAX(NEARESTINT(Ly/dsize[1]),2);
    nels[2] = (int) MAX(NEARESTINT(Lz/dsize[2]),2);
    dsize[0] = Lx/nels[0];
    dsize[1] = Ly/nels[1];
    dsize[2] = Lz/nels[2];


    writeMessageToParetoLog("generateCuboidMesh: %d %d %d ",nels[0],nels[1],nels[2]);

    writeMessageToParetoLog("generateCuboidMesh: %f %f %f ",dsize[0],dsize[1],dsize[2]);

    nelx = nels[0];
    nely = nels[1];
    nelz = nels[2];
    h_nelx = nelx;
    h_nely = nely;
    h_nelz = nelz;

    dx = dsize[0];
    dy = dsize[1];
    dz = dsize[2];
    h_voxelgrid = true; // uniform grid
    h_nMaterials = 0;// no material assigned
    h_dx = dx;
    h_dy = dy;
    h_dz = dz;

    releaseCPUMemory();// if there is memory assigned

    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: creating a grid mesh");

    h_nNodes = (nelx+1)*(nely+1)*(nelz+1);
    h_nElems = (nelx)*(nely)*(nelz);
    h_nTemplateElements = 1;
    h_maxNeighboringElements = 8;// for regular grid

    if (h_hexmesh_verbose)  writeMessageToParetoLog("AFElasticity: nDOF   = \t%d ",3*h_nNodes);

    if (allocateNodeMemory() != 1)
        return -1;
    if (allocateElemMemory() != 1)
        return -1;

    // also allocate for grid node mapping
    safeFree(h_gridNodeToRealNode);
    int nGridNodes = h_nNodes;// all grid nodes are in by construction
    h_gridNodeToRealNode =(int *)malloc(nGridNodes*sizeof(int));
    // and they map to the corresponding node
    for (i = 0; i < nGridNodes; i++)
        h_gridNodeToRealNode[i] = i;

    h_neighborElems =(int *)malloc((h_nNodes)*h_maxNeighboringElements*sizeof(int));//8 for a regular grid

    //x,y,z location, nodes are numbered first along x, then along y and then along z
    int nodeNum;
    int yOffset = (nelx+1); // difference in 2 nodes that are next to each other in y
    int zOffset = (nelx+1)*(nely+1); // difference in 2 nodes that are next to each other in z
    // Global and local node numbering: first along x, then along y and then along z
    nodeNum  = 0;
    h_modelScale = nelx*dx;
    h_modelScale = (nely*dy > h_modelScale)? nely*dy:h_modelScale;
    h_modelScale = (nelz*dz > h_modelScale)? nelz*dz:h_modelScale;

    h_xMin = -nelx*dx/2;
    h_yMin = -nely*dy/2;
    h_zMin = -nelz*dz/2;
    for (k = 0; k < nelz+1; k++) {//slowest
        for (j = 0; j < nely+1; j++)  {//next
            for (i = 0; i < nelx+1; i++)  {//fastest change
                h_x[nodeNum] = i*dx + h_xMin;
                h_y[nodeNum] = j*dy + h_yMin;
                h_z[nodeNum] = k*dz + h_zMin;
                nodeNum++;
            }
        }
    }
    // Linear hex: 8 nodes per hex
    elem = 0;

    int nodeIndex[8] = {0,1,yOffset+1,yOffset,zOffset,zOffset+1,zOffset+yOffset+1,zOffset+yOffset};
    for (k = 0; k < nelz; k++) {//slowest
        for (j = 0; j < nely; j++)  {//next
            for (i = 0; i < nelx; i++)  {//fastest change
                startNode = i + j*yOffset + k*zOffset; // start node number for a given hex
                for (m = 0; m < 8; m++)
                    h_elems[(h_nElems)*m + elem] = startNode + nodeIndex[m];;
                elem = elem+1;
            }
        }
    }

    //Initialize template IDs and density
    memset(h_materialIdOfElem,0,h_nElems*sizeof(int));
    memset(h_partIdOfElem,0,h_nElems*sizeof(int));
    memset(h_templateID,0,h_nElems*sizeof(int));

    //  neighboring elems,initialize the arrays
    for (node = 0; node < h_nNodes; node++) {
        h_nNeighboringElems[node] = 0;// no neighboring elems
        for (m = 0; m < 8; m++)
            h_neighborElems[(h_nNodes)*m + node] = -1;
    }
    for (elem =0; elem < h_nElems; elem++)
        h_pseudoDensity[elem] = 1.0;

    findNeighboringElemsOfNodes();
    findNeighboringNodesOfNodes();

#ifdef COMPILE_GPUCODE
    releaseHexmeshGPUMemory(&h_gpuData);
    createAFElasticityGPUMemory( h_nNodes,h_nElems,h_maxNeighboringElements,h_nTemplateElements,&h_gpuData);
#endif

    return 1;
}
/**********************************************************************/
void AFElasticity::fixX0Plane(void)
{
    // only valid for a uniform grid
    // fix x=0 plane
    // Set the nodes on x= 0 plane to fixed

    int nelx = h_nelx;

    if (h_nNodes < (h_nelx+1)*(h_nely+1)*(h_nelz+1)) {
        writeMessageToParetoLog("AFElasticity: Error, fixX0Plane can only be used with a cuboid mesh ");
        return;
    }
    for (int node = 0; node < h_nNodes; node += (nelx+1)) {
        h_free[node] = 0; // 1*0 + 2*0 + 4*0

        h_dirichlet[3*node] = 0;
        h_dirichlet[3*node+1] = 0;
        h_dirichlet[3*node+2] = 0;
    }
}
/**********************************************************************/
void AFElasticity::applyUnitTipLoad(void)
{
    int nelx = h_nelx;

    if (h_nNodes < (h_nelx+1)*(h_nely+1)*(h_nelz+1)) {
        writeMessageToParetoLog("AFElasticity: Error, applyUnitTipLoad can only be used with a cuboid mesh ");
        return;
    }

    // only valid for a uniform grid
    int forcedNode = (int) ceil((double) h_nNodes/2.0)+ ceil((double) nelx/2.0)-1;
    h_f[3*forcedNode+1] = 1.0;
}
/**********************************************************************/
void AFElasticity::applyUnitEdgeLoad(void)
{
    int nelx,nely;
    nelx = h_nelx;
    nely = h_nely;

    if (h_nNodes < (h_nelx+1)*(h_nely+1)*(h_nelz+1)) {
        writeMessageToParetoLog("AFElasticity: Error, applyUnitEdgeLoad can only be used with a cuboid mesh ");
        return;
    }
    // only valid for a uniform grid
    for (int node = nelx; node < h_nNodes; node += (nelx+1)*(nely+1))
        h_f[3*node+1] = -1.0;

}
/**********************************************************************/
void AFElasticity::createEdgeLoadedProblem(int nelx,int nely,int nelz)
{
    int nels[3];
    nels[0] = nelx;
    nels[1] = nely;
    nels[2] = nelz;
    double dsize[3] = {1,1,1}; // grid size along x, y and z
    double boundingBox[3][2];

    boundingBox[0][0] = 0;boundingBox[0][1] = 10;
    boundingBox[1][0] = -1;boundingBox[1][1] = 1;
    boundingBox[2][0] = -1;boundingBox[2][1] = 1;

    generateCuboidMesh(nelx*nely*nelz,boundingBox);
    fixX0Plane();
    applyUnitEdgeLoad();

}

/**********************************************************************/
int AFElasticity::find_word(FILE *filein, const char *word)
{
    char str[256];
    fpos_t pos;
    fgetpos(filein, &pos);
    while(fscanf(filein, " %s", str) !=EOF) {
        if (strcmp(str,word) == 0)
            return 1;
    }
    // failed, return back to original position
    fsetpos(filein,&pos);
    return 0;
}
//*********************************************
bool AFElasticity::readTessellationFile(const char *fileName)
// Read STLGeom file (binary)
/*
UINT8[80] � Header
UINT32 � Number of triangles

foreach triangle
REAL32[3] � Normal vector
REAL32[3] � Vertex 1
REAL32[3] � Vertex 2
REAL32[3] � Vertex 3
UINT16 � Attribute byte count
end*/
{
    char header[80];
    unsigned int tempNTriangles;
    unsigned short attribute;
    float pt[3],normal[3];
    FILE *filein;

    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Reading Tessellation file ... ");
    filein = fopen(fileName,"rb");// binary file
    if (filein == 0) {
        writeMessageToParetoLog("AFElasticity: Could not find %s ",fileName);
        return false;
    }

    h_numTesselationTriangles  = 0;
    h_numTesselationPoints = 0;
    safeFree(h_tessellationTriangles);
    safeFree(h_tessellationXYZ);
    safeFree(h_tessellationUVW);
    safeFree(h_tessellationModalUVW);
    safeFree(h_tessellationVonMises);
    safeFree(h_tessellationTemperature);

    fread(&header,80*sizeof(byte),1,filein);
    fread(&tempNTriangles,sizeof(unsigned int),1,filein);
    h_numTesselationTriangles = tempNTriangles;


    h_tessellationTriangles= (int *)malloc(3*h_numTesselationTriangles*sizeof(int));
    h_tessellationNormals= (double *)malloc(3*h_numTesselationTriangles*sizeof(double));// 3 per triangle
    h_tessellationXYZ = (double *)malloc(9*h_numTesselationTriangles*sizeof(double));// 9 data points for every triangle
    h_tessellationUVW = (double *)malloc(9*h_numTesselationTriangles*sizeof(double));// 9 data points for every triangle
    h_tessellationVonMises = (double *)malloc(3*h_numTesselationTriangles*sizeof(double));// 3 data points for every triangle
    h_tessellationTemperature = (double *)malloc(3*h_numTesselationTriangles*sizeof(double));// 3 data points for every triangle
    h_tessellationModalUVW = (double *)malloc(9*h_numTesselationTriangles*sizeof(double));// 9 data points for every triangle

    memset(h_tessellationTriangles,0,3*h_numTesselationTriangles*sizeof(int));
    memset(h_tessellationXYZ,0,9*h_numTesselationTriangles*sizeof(double));
    memset(h_tessellationUVW,0,9*h_numTesselationTriangles*sizeof(double));
    memset(h_tessellationVonMises,0,3*h_numTesselationTriangles*sizeof(double));
    memset(h_tessellationModalUVW,0,9*h_numTesselationTriangles*sizeof(double));
    h_numTesselationTriangles = 0;
    h_numTesselationPoints = 0;
    for (unsigned int tri = 0; tri < tempNTriangles; tri++) {
        fread(&normal[0],sizeof(float),1,filein);
        fread(&normal[1],sizeof(float),1,filein);
        fread(&normal[2],sizeof(float),1,filein);
        for (int i =0; i < 3; i++)
            h_tessellationNormals[3*tri+i] = normal[i];

        for (int i =0; i < 3; i++) {// read three points
            fread(&pt[0],sizeof(float),1,filein);
            fread(&pt[1],sizeof(float),1,filein);
            fread(&pt[2],sizeof(float),1,filein);
            h_tessellationXYZ[3*h_numTesselationPoints] = pt[0];
            h_tessellationXYZ[3*h_numTesselationPoints+1] = pt[1];
            h_tessellationXYZ[3*h_numTesselationPoints+2] = pt[2];

            h_tessellationTriangles[3*tri+i] = h_numTesselationPoints;
            h_numTesselationPoints++;
        }

        fread(&attribute,sizeof(attribute),1,filein);
        h_numTesselationTriangles++;
    }
    fclose(filein);
    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticitiy: Read %d triangles and %d points of tessellation ",h_numTesselationTriangles,h_numTesselationPoints);
    return true;
}
//*********************************************
int AFElasticity::getNumTessellationTriangles(void)
{
    return h_numTesselationTriangles;
}
//*********************************************
int		AFElasticity::getNumTessellationPoints(void)
{
    return h_numTesselationPoints;
}
//*********************************************
bool	 AFElasticity::getTessellationPoint(int node,double pt[3])
{
    if ((node < 0) || (node >= h_numTesselationPoints)) return false;

    pt[0] =  h_tessellationXYZ[3*node];
    pt[1] =  h_tessellationXYZ[3*node+1];
    pt[2] =  h_tessellationXYZ[3*node+2];

    return true;
}
//*********************************************
bool	 AFElasticity::getTessellationTriangleNodes(int tri,int nodes[3])
{
    if ((tri < 0) || (tri >= h_numTesselationTriangles)) return false;

    for (int i = 0; i < 3; i++)
        nodes[i] = h_tessellationTriangles[3*tri+i];

    return true;
}
//*********************************************
bool	AFElasticity::getTessellationTriangleNormal(int tri,double normal[3])
{
    if ((tri < 0) || (tri >= h_numTesselationTriangles)) return false;

    for (int i = 0; i < 3; i++)
        normal[i] = h_tessellationNormals[3*tri+i];

    return true;
}
//*********************************************
bool	AFElasticity::getTessellationNodeDisplacement(int node,double uvw[3])
{
    if ((node < 0) || (node >= h_numTesselationPoints)) return false;

    uvw[0] = h_tessellationUVW[3*node];
    uvw[1] = h_tessellationUVW[3*node+1];
    uvw[2] = h_tessellationUVW[3*node+2];

    return true;
}
//*********************************************
bool	AFElasticity::getTessellationNodeVonMises(int node,double vonMises[1])
{
    if ((node < 0) || (node >= h_numTesselationPoints)) return false;

    vonMises[0] = h_tessellationVonMises[node];
    return true;
}
//*********************************************
bool	AFElasticity::getTessellationNodeTemperature(int node,double temperature[1])
{
    if ((node < 0) || (node >= h_numTesselationPoints)) return false;

    temperature[0] = 0;// not implemented yet
    return true;
}
//*********************************************
bool	AFElasticity::getTessellationNodeModalDisplacement(int node,double uvw[3])
{
    if ((node < 0) || (node >= h_numTesselationPoints)) return false;

    uvw[0] = h_tessellationModalUVW[3*node];
    uvw[1] = h_tessellationModalUVW[3*node+1];
    uvw[2] = h_tessellationModalUVW[3*node+2];

    return true;
}
//*********************************************
bool AFElasticity::getTessellationVerticesOfTriangle(int tri,double x[3],double y[3],double z[3],double triNormal[3])
{
    int nodes[3];
    if ((tri < 0) || (tri >= h_numTesselationTriangles)) return false;

    for (int i = 0; i < 3; i++)
        nodes[i] = h_tessellationTriangles[3*tri+i];

    for (int i = 0; i < 3; i++){
        x[i] = h_tessellationXYZ[3*nodes[i]];
        y[i] = h_tessellationXYZ[3*nodes[i]+1];
        z[i] = h_tessellationXYZ[3*nodes[i]+2];
        triNormal[i] = h_tessellationNormals[3*tri+i];
    }
    return true;
}
//*********************************************
bool AFElasticity::getTessellationElasticitySolutionOfTriangle(int tri,double u[3],double v[3],double w[3],double vonMises[3])
{
    int nodes[3];
    if ((tri < 0) || (tri >= h_numTesselationTriangles)) return false;


    for (int i = 0; i < 3; i++)
        nodes[i] = h_tessellationTriangles[3*tri+i];

    for (int i = 0; i < 3; i++){
        u[i] = h_tessellationUVW[3*nodes[i]];
        v[i] = h_tessellationUVW[3*nodes[i]+1];
        w[i] = h_tessellationUVW[3*nodes[i]+2];
        vonMises[i] = h_tessellationVonMises[nodes[i]];
    }
    return true;
}
//*********************************************
bool AFElasticity::getTessellationModalSolutionOfTriangle(int tri,double u[3],double v[3],double w[3])
{
    int nodes[3];
    if ((tri < 0) || (tri >= h_numTesselationTriangles)) return false;


    for (int i = 0; i < 3; i++)
        nodes[i] = h_tessellationTriangles[3*tri+i];

    for (int i = 0; i < 3; i++){
        u[i] = h_tessellationModalUVW[3*nodes[i]];
        v[i] = h_tessellationModalUVW[3*nodes[i]+1];
        w[i] = h_tessellationModalUVW[3*nodes[i]+2];
    }
    return true;
}
/**********************************************************************/
int AFElasticity::readAbaqusInpFile(const char *fileName)
{
    /*
    Heading
    ** Job name: block Model name: block
    ** Generated by: Abaqus/CAE Student Edition 6.9-2
    *Preprint, echo=NO, model=NO, history=NO, contact=NO
    **
    ** PARTS
    **
    *Part, name=PART-1
    *Node
    1,         -7.5,          25.,          20.
    2,         -7.5,    21.041666,          20.
    3,         -7.5,    17.083334,          20.
    4,         -7.5,       13.125,          20.
    5,         -7.5,   9.16666698,          20.
    6,         -7.5,   5.20833349,          20.
    7,         -7.5,         1.25,          20.
    ...
    *Element, type=C3D8R
    1,  43,  44,  51,  50,   1,   2,   9,   8
    2,  44,  45,  52,  51,   2,   3,  10,   9
    3,  45,  46,  53,  52,   3,   4,  11,  10
    4,  46,  47,  54,  53,   4,   5,  12,  11
    5,  47,  48,  55,  54,   5,   6,  13,  12
    6,  48,  49,  56,  55,   6,   7,  14,  13
    7,  50,  51,  58,  57,   8,   9,  16,  15
    8,  51,  52,  59,  58,   9,  10,  17,  16
    ...
    *BOUNDARY
    1, ENCASTRE
    2, ENCASTRE
    5, ENCASTRE
    7, ENCASTRE
    ...
    *CLOAD
    421, 2, -3.1250e+002
    422, 2, -3.1250e+002
    423, 2, -3.1250e+002
    ...
    CAVEAT:
    Only .inp files with linear hex elements generated by Abaqus are read.
    The format is  limited to above
    */
    int startNode,startElem,node,i,j,elem,dof,maxNodeNum,tempInt;
    char line[1024],*pch;
    double x,y,z,xMin,xMax,yMin,yMax,zMin,zMax,force;
    bool readLoads;
    fpos_t nodeStartPos,elemStartPos,constraintStartPos,cloadStartPos;
    FILE *fptr;

    h_voxelgrid = false;// arbitrary hex mesh
    readLoads = false;
    releaseCPUMemory();// if there is memory assigned
    if (h_hexmesh_verbose)  writeMessageToParetoLog("AFElasticity: reading Abaqus file %s",fileName);
    fptr = fopen(fileName,"r");
    if (fptr == NULL) {
        writeMessageToParetoLog("AFElasticity: Unable to find input file %s ",fileName);
        return -1;
    }
    // Search for the keyword "*NODE"
    while (fgets(line,sizeof(line), fptr ) != NULL ) {
        pch = strtok (line," ,\n");
        if ((strcmp(pch,"*NODE")==0) || (strcmp(pch,"*Node")==0))
            break;
    }

    fgetpos(fptr,&nodeStartPos);//store file location
    // Now count the number of nodes to allocate memory
    fgets(line,sizeof(line), fptr );
    pch = strtok (line," ,\n");
    startNode =  atoi(pch);
    if (startNode !=1 ) {
        writeMessageToParetoLog("AFElasticity: Node numbering starts at %d; must start at 1 ... exiting ",startNode);
        fclose(fptr);
        return -1;
    }
    h_nNodes =1;
    maxNodeNum = 0;
    while ( fgets(line,sizeof(line), fptr ) != NULL ) {
        pch = strtok (line," ,\n");
        sscanf(pch,"%d ",&node);
        maxNodeNum = max(node,maxNodeNum);
        if (pch[0]=='*')
            break;
        h_nNodes++;
    }
    writeMessageToParetoLog("AFElasticity: nNodes = %d;maxNodeNum = %d ",h_nNodes,maxNodeNum);


    if (allocateNodeMemory() != 1)
        return -1;

    // Rewind and read node locations
    fsetpos(fptr,&nodeStartPos);
    h_modelScale = 0;
    xMin = 1e20;yMin = 1e20;zMin = 1e20;
    xMax = -1e20;yMax = -1e20;zMax = -1e20;


    // the nodes may not be sequential ... so we need to create a map
    int *nodeMapping;
    maxNodeNum++;
    nodeMapping = (int *)malloc(maxNodeNum*sizeof(int));
    memset(nodeMapping,0,maxNodeNum*sizeof(int));
    node = 0;
    for (i = 0; i < h_nNodes; i++) {
        if (i == 0)
            fscanf(fptr,"%lf,%lf,%lf ",&x,&y,&z);// bug in file repositioning
        else
            fscanf(fptr,"%d,%lf,%lf,%lf ",&node,&x,&y,&z);
        nodeMapping[node] = i;
        h_free[i] =7;
        h_x[i] = (double) x;
        h_y[i] = (double) y;
        h_z[i] = (double) z;
        xMin = (x < xMin)? x:xMin;
        yMin = (y < yMin)? y:yMin;
        zMin = (z < zMin)? z:zMin;

        xMax = (x > xMax)? x:xMax;
        yMax = (y > yMax)? y:yMax;
        zMax = (z > zMax)? z:zMax;
    }
    h_modelScale = (xMax-xMin);
    h_modelScale = ((yMax-yMin) > h_modelScale)? (yMax-yMin):h_modelScale;
    h_modelScale = ((zMax-zMin) > h_modelScale)? (zMax-zMin):h_modelScale;

    for (i = 0; i <h_nNodes; i++) {
        h_x[i] -= (xMin+xMax)/2;
        h_y[i] -= (yMin+yMax)/2;
        h_z[i] -= (zMin+zMax)/2;
    }

    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: XYZ Min = (%.3e, %.3e, %.3e) ",xMin,yMin,zMin);
    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: XYZ Max = (%.3e, %.3e, %.3e) ",xMax,yMax,zMax);

    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: h_modelScale = %e ",h_modelScale);
    // Search for the keyword "*ELEMENT"
    while (fgets(line,sizeof(line), fptr ) != NULL ) {
        pch = strtok (line," ,\n");
        if ( (strcmp(pch,"*ELEMENT")==0) || (strcmp(pch,"*Element")==0) )
            break;
    }

    fgetpos(fptr,&elemStartPos);//store file location
    // Now count the number of elements to allocate memory
    fgets(line,sizeof(line), fptr );
    pch = strtok (line," ,\n");
    startElem =  atoi(pch);
    h_nElems =1;
    while ( fgets(line,sizeof(line), fptr ) != NULL ) {
        pch = strtok (line," ,\n");
        if (pch[0]=='*')
            break;
        h_nElems++;
    }
    writeMessageToParetoLog("AFElasticity: nElems = %d ",h_nElems);
    if (allocateElemMemory() != 1) {
        free(nodeMapping);
        return -1;
    }
    // rewind
    fsetpos(fptr,&elemStartPos);
    // Read the mesh description
    elem= 0;
    for (i = 0; i < h_nElems; i++) {
        h_pseudoDensity[i] = 1.0;//all elements are in
        fgets(line,sizeof(line), fptr );
        if (i > 0){// a bug on file positioning for the first line
            pch = strtok (line," ,\n");
            tempInt =  atoi(pch)-1;
        }
        for (j =0; j <8; j++) {// store the first nodes of all elements, then second nodes, etc
            pch = strtok (NULL," ,\n");
            node =  atoi(pch);
            h_elems[j*h_nElems + elem] = nodeMapping[node]; // map to the actual node
        }
        elem++;
    }
    for (i = 0; i < HEXMESH_MAX_FACE_LABELS; i++)
        h_NumNodesWithLabel[i] = 0;

    free(nodeMapping);

    if (readLoads) {
        writeMessageToParetoLog("AFElasticity: Reading BOUNDARY ");
        // Search for the keyword "*BOUNDARY"
        while (fgets(line,sizeof(line), fptr ) != NULL ) {
            pch = strtok (line," ,\n");
            if ( (strcmp(pch,"*BOUNDARY")==0) || (strcmp(pch,"*Boundary")==0) )
                break;
        }
        int nConstraints;
        nConstraints = 0;
        fgetpos(fptr,&constraintStartPos);//store file location
        // Now count the number of constraints
        fgets(line,sizeof(line), fptr );
        pch = strtok (line," ,\n");
        while ( fgets(line,sizeof(line), fptr ) != NULL ) {
            pch = strtok (line," ,\n");
            if (pch[0]=='*')
                break;
            nConstraints++;
        }
        writeMessageToParetoLog("AFElasticity: nConstraints = %d ",nConstraints);

        // rewind
        fsetpos(fptr,&constraintStartPos);
        // Read the constraints
        for (i = 0; i < nConstraints; i++) {
            fgets(line,sizeof(line), fptr );
            pch = strtok (line," ,\n");
            node =  atoi(pch)-1;//offset by 1
            pch = strtok (NULL," ,\n");
            dof =  atoi(pch)-1;//offset by 1
            if (dof == 0)
                h_free[node] -= 1;
            else if (dof == 1)
                h_free[node] -= 2;
            else if (dof == 2)
                h_free[node] -= 4;

        }

        // Search for the keyword "*CLOAD"
        while (fgets(line,sizeof(line), fptr ) != NULL ) {
            pch = strtok (line," ,\n");
            if ( (strcmp(pch,"*CLOAD")==0) || (strcmp(pch,"*Cload")==0) )
                break;
        }
        int nLoads;
        nLoads = 0;
        fgetpos(fptr,&cloadStartPos);//store file location
        // Now count the number of constraints
        fgets(line,sizeof(line), fptr );
        pch = strtok (line," ,\n");
        while ( fgets(line,sizeof(line), fptr ) != NULL ) {
            pch = strtok (line," ,\n");
            if (pch[0]=='*')
                break;
            nLoads++;
        }
        writeMessageToParetoLog("AFElasticity: nLoads = %d ",nLoads);

        // rewind
        fsetpos(fptr,&cloadStartPos);
        // Read the loads
        for (i = 0; i < nLoads; i++) {
            fgets(line,sizeof(line), fptr );
            pch = strtok (line," ,\n");
            node =  atoi(pch)-1;// startNode is 1, so offset
            pch = strtok (NULL," ,\n");
            dof =  atoi(pch)-1;//offset by 1
            pch = strtok (NULL," ,\n");
            force =  atof(pch);
            h_f[3*node+dof] = force;
        }
    }
    //Initialize template IDs and density
    memset(h_materialIdOfElem,0,h_nElems*sizeof(int));
    memset(h_partIdOfElem,0,h_nElems*sizeof(int));
    discardTemplates();// all elements are distinct by default

    findNeighboringElemsOfNodes();
    findNeighboringNodesOfNodes();

    fclose(fptr);

#ifdef COMPILE_GPUCODE
    releaseHexmeshGPUMemory(&h_gpuData);
    createAFElasticityGPUMemory( h_nNodes,h_nElems,h_maxNeighboringElements,h_nTemplateElements,&h_gpuData);
#endif
    return 1;
}
/**********************************************************************/
int AFElasticity::readAbaqusRPTFile(const char *fileName)
{
    /*
    ********************************************************************************
    Field Output Report, written Fri Apr 06 05:16:15 2012
    ...
    Node            U.U1            U.U2            U.U3
    Label          @Loc 1          @Loc 1          @Loc 1
    -----------------------------------------------------------------
    1    -1.33452E-36    -2.00592E-36    -11.5082E-36
    2    -1.73876E-36    -9.14959E-36    -10.5357E-36
    3    -461.362E-39    -6.49288E-36    -1.44239E-36
    */

    FILE *fptr;
    char line[1024];
    int i,node=0;


    if (h_hexmesh_verbose)  writeMessageToParetoLog("AFElasticity: reading Abaqus file %s",fileName);

    fptr = fopen(fileName,"r");

    if (fptr == NULL) {
        writeMessageToParetoLog("AFElasticity: Unable to find file %s ",fileName);
        return -1;
    }
    // Search for the keyword "Label"
    find_word(fptr,"Label");
    fgets(line,sizeof(line),fptr); //rest of line
    fgets(line,sizeof(line),fptr); //extra line -------------------
    for (i = 0; i < h_nNodes; i++)
        fscanf(fptr,"%d %lf %lf %lf",&node,&(h_sol[3*i]),&(h_sol[3*i+1]),&(h_sol[3*i+2]));
    fclose(fptr);
    computeDeformationMax();

    return 1;

}
/**********************************************************************/
void AFElasticity::readQuadMeshAndSweep(const char *fileName,double sweepLength)
{
    // Read a quad mesh and each node location depends on the normal at of mesh at that point
    // The quad mesh Example
    /* 1886
    1776
    0.000000e+000 0.000000e+000
    0.000000e+000 2.307692e+001
    2.285714e+001 0.000000e+000
    ....

    1 3 4 2
    3 5 6 4
    ...
    */
    FILE *fptr;
    int i,j,nQuadNodes,nQuadElements,nElementsAlongSweep,*nodes,*numParentQuads;
    double xMin,yMin,zMin,xMax,yMax,zMax,sweepDir[3];
    double **quadPts,*pt0,*pt1,*pt2,*pt3,v01[3],v12[3],normal[3],nrm,hSize,h,**quadPtNormals;
    int **quadElements;

    sweepDir[0] = -3;
    sweepDir[1] = -1;
    sweepDir[2] = 0;

    fptr = fopen(fileName,"r");
    if (!fptr) {
        writeMessageToParetoLog("AFElasticity: File %s does not exist ",fileName);
        return;
    }
    fscanf(fptr,"%d ",&nQuadNodes);
    if (nQuadNodes <= 0) {
        writeMessageToParetoLog("AFElasticity: nNodes %d is incorrect ",nQuadNodes);
        return;
    }
    fscanf(fptr,"%d ",&nQuadElements);
    if (nQuadElements <= 0) {
        writeMessageToParetoLog("AFElasticity: nQuadElements %d is incorrect",nQuadElements);
        return;
    }
    quadPts = (double **)malloc(nQuadNodes*sizeof(double *));
    quadPtNormals = (double **)malloc(nQuadNodes*sizeof(double *));
    numParentQuads = (int *)malloc(nQuadNodes*sizeof(int));
    memset(numParentQuads,0,nQuadNodes*sizeof(int));
    for (i = 0; i < nQuadNodes; i++) {
        quadPts[i] = (double *)malloc(3*sizeof(double));
        quadPtNormals[i] = (double *)malloc(3*sizeof(double));
        fscanf(fptr,"%lf %lf %lf \n",&(quadPts[i][0]),&(quadPts[i][1]),&(quadPts[i][2]));
    }
    quadElements = (int **)malloc(nQuadElements*sizeof(int *));
    for (i = 0; i < nQuadElements; i++) {
        quadElements[i] = (int *)malloc(4*sizeof(int));
        for (j = 0; j < 4; j++) {
            fscanf(fptr,"%d  \n",&(quadElements[i][j]));
        }
    }
    fclose(fptr);
    // compute the  normal at all quad elements
    hSize = 0;
    for (i = 0; i < nQuadElements; i++) {
        nodes = quadElements[i];
        pt0  = quadPts[nodes[0]];
        pt1  = quadPts[nodes[1]];
        pt2  = quadPts[nodes[2]];
        pt3  = quadPts[nodes[3]];
        SUBTRACT3D(v01,pt1,pt0);
        SUBTRACT3D(v12,pt2,pt1);
        normal[0] = v01[1]*v12[2] - v01[2]*v12[1];
        normal[1] = -(v01[0]*v12[2] - v01[2]*v12[0]);
        normal[2] = v01[0]*v12[1] - v01[1]*v12[0];
        nrm = NORM3D(normal);
        normal[0] /= nrm;//approximate normal
        normal[1] /= nrm;
        normal[2] /= nrm;

        for (j = 0; j < 4;j++) {
            numParentQuads[nodes[j]]++;
            quadPtNormals[nodes[j]][0] += normal[0];//cumulative
            quadPtNormals[nodes[j]][1] += normal[1];
            quadPtNormals[nodes[j]][2] += normal[2];
        }
        h = NORM3D(v01);
        hSize += h;
    }
    // average the normals
    for (i = 0; i < nQuadNodes; i++) {
        if (numParentQuads[i] > 0){
            quadPtNormals[i][0] /= numParentQuads[i];
            quadPtNormals[i][1] /= numParentQuads[i];
            quadPtNormals[i][2] /= numParentQuads[i];

            nrm = NORM3D(quadPtNormals[i]);

            quadPtNormals[i][0] /= nrm;
            quadPtNormals[i][1] /= nrm;
            quadPtNormals[i][2] /= nrm;
        }
    }
    hSize /= nQuadElements; // average mesh size
    writeMessageToParetoLog("Average size = %e ",hSize);


    nElementsAlongSweep =  (int) (sweepLength/hSize);
    nElementsAlongSweep = MAX(1,nElementsAlongSweep);
    writeMessageToParetoLog("nElementsAlongSweep = %d ",nElementsAlongSweep);
    hSize = sweepLength/nElementsAlongSweep;

    // Create hex mesh
    releaseCPUMemory();// if there is memory assigned

    writeMessageToParetoLog("AFElasticity: creating Hexmesh");
    h_nNodes = nQuadNodes*(nElementsAlongSweep+1);
    writeMessageToParetoLog("AFElasticity: nNodes = %d ",h_nNodes);
    if (allocateNodeMemory() != 1)
        return;

    // Set node coordinates
    h_modelScale = 0;
    xMin = 1e20;yMin = 1e20;zMin = 1e20;
    xMax = -1e20;yMax = -1e20;zMax = -1e20;

    h_nNodes = 0;
    nrm = NORM3D(sweepDir);
    for (j = 0; j <= nElementsAlongSweep;j++) {
        for (i = 0; i < nQuadNodes; i++) {

            sweepDir[0] = -quadPtNormals[i][0];
            sweepDir[1] = -quadPtNormals[i][1];
            sweepDir[2] = -quadPtNormals[i][2];

            h_x[h_nNodes] = quadPts[i][0] + hSize*j*sweepDir[0];
            h_y[h_nNodes] = quadPts[i][1] + hSize*j*sweepDir[1];
            h_z[h_nNodes] = quadPts[i][2] + hSize*j*sweepDir[2];
            xMin = (h_x[h_nNodes] < xMin)? h_x[h_nNodes]:xMin;
            yMin = (h_y[h_nNodes] < yMin)? h_y[h_nNodes]:yMin;
            zMin = (h_z[h_nNodes] < zMin)? h_z[h_nNodes]:zMin;

            xMax = (h_x[h_nNodes] > xMax)? h_x[h_nNodes]:xMax;
            yMax = (h_y[h_nNodes] > yMax)? h_y[h_nNodes]:yMax;
            zMax = (h_z[h_nNodes] > zMax)? h_z[h_nNodes]:zMax;
            h_nNodes++;
        }
    }
    h_modelScale = (xMax-xMin);
    h_modelScale = ((yMax-yMin) > h_modelScale)? (yMax-yMin):h_modelScale;
    h_modelScale = ((zMax-zMin) > h_modelScale)? (zMax-zMin):h_modelScale;

    h_modelScale *= 2;
    h_nElems = nQuadElements*nElementsAlongSweep;
    writeMessageToParetoLog("AFElasticity: nElems = %d ",h_nElems);

    if (allocateElemMemory() != 1)
        return;

    //  the mesh description
    int nElems;
    nElems = 0;
    for (j = 0; j < nElementsAlongSweep;j++) {
        for (i = 0; i < nQuadElements; i++) {
            h_pseudoDensity[nElems] = 1.0;//all elements are in

            h_elems[(h_nElems)*0 + nElems] = quadElements[i][0] + nQuadNodes*(j); ;// store the first nodes of all elements, then second nodes, etc
            h_elems[(h_nElems)*1 + nElems] = quadElements[i][1] + nQuadNodes*(j);
            h_elems[(h_nElems)*2 + nElems] = quadElements[i][2] + nQuadNodes*(j);
            h_elems[(h_nElems)*3 + nElems] = quadElements[i][3] + nQuadNodes*(j);

            h_elems[(h_nElems)*4 + nElems] = quadElements[i][0] + nQuadNodes*(j+1);
            h_elems[(h_nElems)*5 + nElems] = quadElements[i][1] + nQuadNodes*(j+1);
            h_elems[(h_nElems)*6 + nElems] = quadElements[i][2] + nQuadNodes*(j+1);
            h_elems[(h_nElems)*7 + nElems] = quadElements[i][3] + nQuadNodes*(j+1);

            nElems++;
        }
    }

    for (i = 0; i < HEXMESH_MAX_FACE_LABELS; i++)
        h_NumNodesWithLabel[i] = 0;

    memset(h_materialIdOfElem,0,h_nElems*sizeof(int));
    memset(h_partIdOfElem,0,h_nElems*sizeof(int));

    discardTemplates();
    findNeighboringElemsOfNodes();
    findNeighboringNodesOfNodes();
#ifdef COMPILE_GPUCODE
    releaseHexmeshGPUMemory(&h_gpuData);
    createAFElasticityGPUMemory( h_nNodes,h_nElems,h_maxNeighboringElements,h_nTemplateElements,&h_gpuData);
#endif

    // Release quad element memory
    for (i = 0; i < nQuadNodes; i++) {
        free(quadPts[i]);
        free(quadPtNormals[i]);
    }
    free(quadPts);
    free(numParentQuads);
    free(quadPtNormals);
    for (i = 0; i < nQuadElements; i++) {
        free(quadElements[i]);
    }
    free(quadElements);
}
/**********************************************************************/
void AFElasticity::readGen4uQuadMeshAndSweepAlongZDirection(const char *fileName,double sweepLength)
{
    // Example
    /*
    # Resultats del nou Gen4u.
    10521    10000        0        0        0
    1     -0.2500000     -0.0100000      0.0000000
    1001      0.2500000     -0.0100000      0.0000000
    1039      0.2500000      0.0100000      0.0000000
    ...
    10521      0.2440000     -0.0050000      0.0000000
    1 0 quad        1        3        4        2
    2 0 quad        3        5        6        4
    3 0 quad        5        7        8        6
    ...
    10000 0 quad    10519    10521    10473    10472
    */


    FILE *fptr;
    int i,j,nQuadNodes,nQuadElements,nElementsAlongSweep,node,elem,node1,node2,node3,node4,temp;
    double **quadPts,*pt1,*pt2,dist[3],hSize,h,x,y,xMin,yMin,zMin,xMax,yMax,zMax;
    int **quadElements;

    h_voxelgrid = false;/// not a voxel grid
    fptr = fopen(fileName,"r");
    if (!fptr) {
        writeMessageToParetoLog("AFElasticity: File %s does not exist ",fileName);
        return;
    }
    char str[256];
    fgets (str,255, fptr); // discard line
    fscanf(fptr,"%d ",&nQuadNodes);
    if (nQuadNodes <= 0) {
        writeMessageToParetoLog("AFElasticity: nNodes %d is incorrect ",nQuadNodes);
        return;
    }
    writeMessageToParetoLog("nQuadNodes = %d ",nQuadNodes);
    fscanf(fptr,"%d ",&nQuadElements);
    if (nQuadElements <= 0) {
        writeMessageToParetoLog("AFElasticity: nQuadElements %d is incorrect ",nQuadElements);
        return;
    }
    writeMessageToParetoLog("nQuadElements = %d ",nQuadElements);
    fgets (str,255, fptr); // discard rest of line

    // Allocate memory
    quadPts = (double **)malloc(nQuadNodes*sizeof(double *));
    for (i = 0; i < nQuadNodes; i++)
        quadPts[i] = (double *)malloc(3*sizeof(double));

    quadElements = (int **)malloc(nQuadElements*sizeof(int *));
    for (i = 0; i < nQuadElements; i++)
        quadElements[i] = (int *)malloc(4*sizeof(int));

    // read  (x,y) coordinates
    for (i = 0; i < nQuadNodes; i++){
        fscanf(fptr,"%d %lf %lf \n",&node,&x,&y);
        quadPts[node-1][0] = x;// note the offset by 1
        quadPts[node-1][1] = y;
        quadPts[node-1][2] = 0;
        fgets (str,255, fptr); // discard rest of line
    }

    // read element data
    for (i = 0; i < nQuadElements; i++) {
        fscanf(fptr,"%d %d %s %d %d %d %d \n",&elem,&temp,str,&node1,&node2,&node3,&node4);
        quadElements[elem-1][0] = node1-1;
        quadElements[elem-1][1] = node2-1;
        quadElements[elem-1][2] = node3-1;
        quadElements[elem-1][3] = node4-1;
    }
    fclose(fptr);

    hSize = 0;
    for (i = 0; i < nQuadElements; i++) {
        pt1  = quadPts[quadElements[i][0]];
        pt2  = quadPts[quadElements[i][2]];
        SUBTRACT3D(dist,pt1,pt2);
        h = NORM3D(dist);
        hSize += h;
    }
    hSize /= nQuadElements; // average mesh size
    writeMessageToParetoLog("Average size = %e ",hSize);

    nElementsAlongSweep =  (int) (sweepLength/hSize);
    nElementsAlongSweep = MAX(1,nElementsAlongSweep);
    writeMessageToParetoLog("nElementsAlongSweep = %d ",nElementsAlongSweep);
    hSize = sweepLength/nElementsAlongSweep;

    // Create hex mesh
    releaseCPUMemory();// if there is memory assigned

    writeMessageToParetoLog("AFElasticity: creating Hexmesh");
    h_nNodes = nQuadNodes*(nElementsAlongSweep+1);
    writeMessageToParetoLog("AFElasticity: nNodes = %d ",h_nNodes);
    if (allocateNodeMemory() != 1)
        return;

    // Set node coordinates
    h_modelScale = 0;
    xMin = 1e20;yMin = 1e20;zMin = 1e20;
    xMax = -1e20;yMax = -1e20;zMax = -1e20;

    h_nNodes = 0;
    for (j = 0; j <= nElementsAlongSweep;j++) {
        for (i = 0; i < nQuadNodes; i++) {
            h_x[h_nNodes] = quadPts[i][0];
            h_y[h_nNodes] = quadPts[i][1];
            h_z[h_nNodes] = hSize*j;
            xMin = (h_x[h_nNodes] < xMin)? h_x[h_nNodes]:xMin;
            yMin = (h_y[h_nNodes] < yMin)? h_y[h_nNodes]:yMin;
            zMin = (h_z[h_nNodes] < zMin)? h_z[h_nNodes]:zMin;

            xMax = (h_x[h_nNodes] > xMax)? h_x[h_nNodes]:xMax;
            yMax = (h_y[h_nNodes] > yMax)? h_y[h_nNodes]:yMax;
            zMax = (h_z[h_nNodes] > zMax)? h_z[h_nNodes]:zMax;
            h_nNodes++;
        }
    }
    h_modelScale = (xMax-xMin);
    h_modelScale = ((yMax-yMin) > h_modelScale)? (yMax-yMin):h_modelScale;
    h_modelScale = ((zMax-zMin) > h_modelScale)? (zMax-zMin):h_modelScale;

    h_modelScale *= 2;
    for (i = 0; i <h_nNodes; i++) {
        h_x[i] -= (xMin+xMax)/2;
        h_y[i] -= (yMin+yMax)/2;
        h_z[i] -= (zMin+zMax)/2;
    }
    h_nElems = nQuadElements*nElementsAlongSweep;
    writeMessageToParetoLog("AFElasticity: nElems = %d ",h_nElems);

    if (allocateElemMemory() != 1)
        return;

    //  the mesh description
    int nElems;
    nElems = 0;
    for (j = 0; j < nElementsAlongSweep;j++) {
        for (i = 0; i < nQuadElements; i++) {
            h_pseudoDensity[nElems] = 1.0;//all elements are in

            h_elems[(h_nElems)*0 + nElems] = quadElements[i][0] + nQuadNodes*(j); ;// store the first nodes of all elements, then second nodes, etc
            h_elems[(h_nElems)*1 + nElems] = quadElements[i][1] + nQuadNodes*(j);
            h_elems[(h_nElems)*2 + nElems] = quadElements[i][2] + nQuadNodes*(j);
            h_elems[(h_nElems)*3 + nElems] = quadElements[i][3] + nQuadNodes*(j);

            h_elems[(h_nElems)*4 + nElems] = quadElements[i][0] + nQuadNodes*(j+1);
            h_elems[(h_nElems)*5 + nElems] = quadElements[i][1] + nQuadNodes*(j+1);
            h_elems[(h_nElems)*6 + nElems] = quadElements[i][2] + nQuadNodes*(j+1);
            h_elems[(h_nElems)*7 + nElems] = quadElements[i][3] + nQuadNodes*(j+1);

            nElems++;
        }
    }

    for (i = 0; i < HEXMESH_MAX_FACE_LABELS; i++)
        h_NumNodesWithLabel[i] = 0;

    memset(h_materialIdOfElem,0,h_nElems*sizeof(int));
    memset(h_partIdOfElem,0,h_nElems*sizeof(int));

    discardTemplates();
    findNeighboringElemsOfNodes();
    findNeighboringNodesOfNodes();
#ifdef COMPILE_GPUCODE
    releaseHexmeshGPUMemory(&h_gpuData);
    createAFElasticityGPUMemory( h_nNodes,h_nElems,h_maxNeighboringElements,h_nTemplateElements,&h_gpuData);
#endif

    // Release quad element memory
    for (i = 0; i < nQuadNodes; i++)
        free(quadPts[i]);
    free(quadPts);
    for (i = 0; i < nQuadElements; i++)
        free(quadElements[i]);
    free(quadElements);
}
/**********************************************************************/
void AFElasticity::releaseEigen(void)
{
    int i;
    if (h_nEigenModes > 0) {
        safeFree(h_eigenValues);
        h_eigenValues = NULL;
        if (h_eigenModes)
            for (i = 0; i < h_nEigenModes;i++)
                safeFree(h_eigenModes[i]);
        safeFree(h_eigenModes);
        h_eigenModes = NULL;
    }
    h_nEigenModes = 0;
}
/**********************************************************************/
double AFElasticity::getFirstEigenValue(void)
{
    if (h_eigenValues == NULL) return 0;
    else return h_eigenValues[0];
}
/**********************************************************************/
void AFElasticity::populateEigen(int nEigenModes, double *eigenValues,double **eigenModes)
{
    int i,j;
    releaseEigen();
    h_nEigenModes = nEigenModes;
    h_eigenValues  =		(double *)malloc((nEigenModes)*sizeof(double));
    h_eigenModes  =			(double **)malloc((nEigenModes)*sizeof(double *));
    for (i = 0; i < h_nEigenModes;i++)
        h_eigenModes[i]  =	(double *)malloc((3*h_nNodes)*sizeof(double));


    for (i = 0; i < h_nEigenModes;i++) {
        h_eigenValues[i] = eigenValues[i];
        for (j = 0; j < 3*h_nNodes; j++)
            h_eigenModes[i][j]= eigenModes[i][j];
    }
}
/**********************************************************************/
bool AFElasticity::allocateNodeMemory(void)
{
    int i;
    // allocate all node related memory
    h_x  =					(double *)malloc((h_nNodes)*sizeof(double));
    h_y  =					(double *)malloc((h_nNodes)*sizeof(double));
    h_z  =					(double *)malloc((h_nNodes)*sizeof(double));
    h_nodeLabels =			(int *)malloc((h_nNodes)*sizeof(int));
    h_nodeExists =			(bool *)malloc((h_nNodes)*sizeof(bool));
    h_sol =					(double *)malloc((3*h_nNodes)*sizeof(double));
    h_solErr =				(double *)malloc((3*h_nNodes)*sizeof(double));
    h_residual =			(double *)malloc((3*h_nNodes)*sizeof(double));

    for (i = 0; i < 6; i++) {
        h_nodestrains[i] = (double *)malloc((h_nNodes)*sizeof(double));
        h_nodestresses[i] = (double *)malloc((h_nNodes)*sizeof(double));
    }
    h_nodevonmises =		(double *)malloc((h_nNodes)*sizeof(double));
    h_free =				(int *)malloc((h_nNodes)*sizeof(int));// all 3 components encoded
    h_dirichlet =			(double *)malloc((3*h_nNodes)*sizeof(double));
    h_retain =				(bool *)malloc((h_nNodes)*sizeof(bool));
    h_f =					(double *)malloc((3*h_nNodes)*sizeof(double));
    h_output =				(double *)malloc((3*h_nNodes)*sizeof(double));
    h_nNeighboringElems  =	(int *)malloc((h_nNodes)*sizeof(int));

    if (h_nNeighboringElems == NULL) {
        writeMessageToParetoLog("AFElasticity: Count not allocate node memory");
        return false;
    }
    // initialize
    for (i =0; i < h_nNodes;i++) {
        h_nNeighboringElems[i] = 0;
        h_nodeLabels[i] = 0;
        h_nodeExists[i] = true;
    }

    memset(h_sol,0,3*h_nNodes*sizeof(double));
    memset(h_solErr,0,3*h_nNodes*sizeof(double));
    memset(h_dirichlet,0,3*h_nNodes*sizeof(double));
    memset(h_f,0,3*h_nNodes*sizeof(double));
    memset(h_output,0,3*h_nNodes*sizeof(double));
    memset(h_retain,false,h_nNodes*sizeof(bool));

    for (i = 0; i < h_nNodes; i++)
        h_free[i] = 7; ;// all free dof; 1*h_freeu + 2*h_freev + 4*h_freew

    if (h_hexmesh_verbose)
        writeMessageToParetoLog("AFElasticity: Allocated Node Memory ");

    return true;
}
/**********************************************************************/
bool AFElasticity::allocateElemMemory(void)
{
    int i;
    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Allocating elem memory");

    h_elems =						(int *)malloc((h_nElems)*8*sizeof(int));
    h_pseudoDensity =				(double *)malloc((h_nElems)*sizeof(double));
    h_templateID  =					(int *)malloc((h_nElems)*sizeof(int));
    h_materialIdOfElem =			(int *)malloc((h_nElems)*sizeof(int));
    h_partIdOfElem =				(int *)malloc((h_nElems)*sizeof(int));

    h_StructuringElems =			(int *)malloc(h_StructuringSize*h_nElems*sizeof(int));
    h_bodyForce =					(double *)malloc((3*h_nElems)*sizeof(double));
    h_elemComponent =				(int *)malloc((h_nElems)*sizeof(int));


    if (h_materialIdOfElem == NULL) {
        writeMessageToParetoLog("AFElasticity: Count not allocate elem memory");
        return false;
    }
    for (i = 0; i < 6; i++) {
        h_elemstrains[i] = (double *)malloc((h_nElems)*sizeof(double));
        h_elemstresses[i] = (double *)malloc((h_nElems)*sizeof(double));
    }
    //Initialize template IDs and density
    memset(h_materialIdOfElem,0,h_nElems*sizeof(int));
    memset(h_partIdOfElem,0,h_nElems*sizeof(int));
    memset(h_templateID,0,h_nElems*sizeof(int));

#pragma omp parallel for 
    for (int i = 0; i < h_nElems;i++)
        h_pseudoDensity[i] = 1.0;// cannot use memset to set to 1.0

    memset(h_StructuringElems,1,h_StructuringSize*h_nElems*sizeof(int));// set to -1

    h_keepElem  = (bool *)malloc(h_nElems*sizeof(bool));
    memset(h_keepElem,false,h_nElems*sizeof(bool));
    memset(h_bodyForce,0,3*h_nElems*sizeof(double));


    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Allocated Elem Memory ");
    return true;
}
/**********************************************************************/
void AFElasticity::resetBC(void)
{
    int node,i;
    for (node = 0; node < h_nNodes; node++) {
        h_free[node] = 7; // default free
        h_retain[node] = false;
        for (i =0; i < 3; i++) {
            h_dirichlet[3*node+i] = 0.0;
            h_f[3*node+i] = 0.0;
        }
    }
}
/**********************************************************************/
void AFElasticity::assignNodeLabel(int node, int nodeLabel)
{
    if ((node < 0) || (node > h_nNodes)) return;
    if (h_nodeLabels[node] == nodeLabel) return; // don't count twice
    if (h_nodeLabels[node] > 0) {//previously assigned
        h_NumNodesWithLabel[h_nodeLabels[node]]--;//remove the countng
    }
    h_nodeLabels[node] = nodeLabel;
    h_NumNodesWithLabel[nodeLabel]++;// used in force averaging
}
/**********************************************************************/
void AFElasticity::setBCOnSingleNode(int node,int BCType[3],double BCValue[])
{
    // Used in exact fields
    int i;

    if ((node <0) || (node >= h_nNodes)) {
        writeMessageToParetoLog("AFElasticity: Incorrect node %d ",node);
        return;
    }
    h_free[node] = 7;
    for (i =0; i < 3; i++) {
        if (BCType[i] == ELASTICITY_DIRICHLET) {
            h_free[node] -= (int) pow(2.0,i);// initial value of 7, subtract 1 for u component, 2 for v, 4 for w
            h_dirichlet[3*node+i] = BCValue[i];
        }
        else if (BCType[i] == ELASTICITY_NEUMANN)
            h_f[3*node+i] = (double) BCValue[i];
    }
}
/**********************************************************************/
void AFElasticity::retainNodesWithLabel(int nodeLabel)
{
    for (int node = 0; node < h_nNodes; node++) {
        if (!doesNodeExist(node)) continue;
        if (h_nodeLabels[node] == nodeLabel) {// node lies on a face with the given face ID or label
            h_retain[node] = true;
        }
    }
}
/**********************************************************************/
double AFElasticity::distanceOfPointFromLine3D(double *Pt,double *Pt1,double *Pt2,double *PtClosest)
{

    // Let the nearest point on the triangle be Pt0
    // Pt0 = Pt1*t + Pt2*(1-t)
    // Pt0 = Pt2 + t(Pt1-Pt2)
    // Vector from Pt to Pt0 is
    // Pt2-Pt + t(Pt1-Pt2)
    // Distance^2 from Pt0 to Pt is
    // distsqr = (Pt2-Pt + t(Pt1-Pt2)).(Pt2-Pt + t(Pt1-Pt2))
    // Setting the derivative with respect to  t to zero, we have
    // (Pt2-Pt + t(Pt1-Pt2)).(Pt1-Pt2) = 0
    // t = -(Pt2-Pt).(Pt1-Pt2) /(Pt1-Pt2)).(Pt1-Pt2)
    // Foce t to lie between 0 and 1


    double pt1_pt2[3], pt2_pt[3], t;
    double a,b, distance;
    int i;
    for ( i=0; i < 3; i++) {
        pt1_pt2[i] = Pt1[i] - Pt2[i];
        pt2_pt[i] = Pt2[i] - Pt[i];
    }

    a = DOTPROD3D(pt1_pt2,pt2_pt);
    b = DOTPROD3D(pt1_pt2,pt1_pt2);


    t = -a/b;
    t = MIN(1.,MAX(0,t));
    for ( i=0; i < 3; i++)
        PtClosest[i] = Pt1[i]*t + Pt2[i]*(1-t);

    distance = DIST3D(Pt,PtClosest);
    return distance;

}
/**********************************************************************/
void AFElasticity::setBCOnNodesWithLabel(int nodeLabel,int BCType[3],double BCValue[])
{
    int node,i;
    double axisDir[3],axisPoint[3],vec[3],forceDir[3],radius,dtprod,nrm,totalTorque;
    double totalForce;// for pressure problems
    double radiusSqrSum; // for torque problems
    double cornerWt, edgeWt, eta;
    int nCornerNodes=0,nEdgeNodes=0,nFaceNodes=0;
    double nodeCG[3],moment[3],momentMagnitude,momentDirection[3];// Needed for remote loading
    double momentLinePt1[3],momentLinePt2[3];
    double nodePt[3],closestPt[3],sumOfRadiiSquare, remoteLoadForceConstant;

    if (h_hexmesh_verbose) writeMessageToParetoLog("Applying BC on Nodes");
    // some preprocessing is needed to avoid high forces near corners
    for (node = 0; node < h_nNodes; node++) {
        if (!doesNodeExist(node)) continue;
        if (h_nodeLabels[node] == nodeLabel) {// node lies on a face with the given face ID or label
            if (isNodeOnCorner(node))
                nCornerNodes++;
            else if (isNodeOnEdge(node))
                nEdgeNodes++;
            else
                nFaceNodes++;
        }
    }
    // precompute for remote loading
    if (BCType[0] == ELASTICITY_REMOTE_LOAD){
        nodeCG[0] = nodeCG[1] = nodeCG[2] = 0.0;
        for (node = 0; node < h_nNodes; node++) {
            if (!doesNodeExist(node)) continue;
            if (h_nodeLabels[node] == nodeLabel) {// node lies on a face with the given face ID or label
                nodeCG[0] += h_x[node];
                nodeCG[1] += h_y[node];
                nodeCG[2] += h_z[node];
            }
        }
        nodeCG[0] /= h_NumNodesWithLabel[nodeLabel];
        nodeCG[1] /= h_NumNodesWithLabel[nodeLabel];
        nodeCG[2] /= h_NumNodesWithLabel[nodeLabel];

        // Compute the equivalent moment about the center
        double vec[3],Force[3];
        Force[0] = BCValue[0];
        Force[1] = BCValue[1];
        Force[2] = BCValue[2];

        // BCValue[3..5] is the location of the remote force
        vec[0] = BCValue[3] - nodeCG[0];
        vec[1] = BCValue[4] - nodeCG[1];
        vec[2] = BCValue[5] - nodeCG[2];
        // Moment = vec (cross) Force
        moment[0] = vec[1]*Force[2] - vec[2]*Force[1];
        moment[1] = vec[2]*Force[0] - vec[0]*Force[2];
        moment[2] = vec[0]*Force[1] - vec[1]*Force[0];

        momentMagnitude = NORM3D(moment) + 1e-12;// to avoid division by zero
        momentDirection[0] = moment[0]/momentMagnitude;
        momentDirection[1] = moment[1]/momentMagnitude;
        momentDirection[2] = moment[2]/momentMagnitude;

        // The moment vector will be replaced by a force vector at each node
        // The moment line is the line passing through the node center in the direction of the moment
        // The direction of each node force will be tangential to shortest line joining that node and the moment line
        // The magnitude of each node force will be proportional to the distance to the moment line
        // We will have to first figure out the proportional constant and then use it later to apply force on each node

        //compute two points on moment line
        for (int i = 0; i < 3; i++){
            momentLinePt1[i] = nodeCG[i] - 10*h_modelScale*momentDirection[i];
            momentLinePt2[i] = nodeCG[i] + 10*h_modelScale*momentDirection[i];
        }

        sumOfRadiiSquare = 1e-12;// to avoid division by zero
        for (node = 0; node < h_nNodes; node++) {
            if (!doesNodeExist(node)) continue;
            if (h_nodeLabels[node] != nodeLabel) continue;
            nodePt[0] = h_x[node];
            nodePt[1] = h_y[node];
            nodePt[2] = h_z[node];
            radius = distanceOfPointFromLine3D(nodePt,momentLinePt1,momentLinePt2,closestPt);
            sumOfRadiiSquare += radius*radius;
        }
        remoteLoadForceConstant = momentMagnitude/sumOfRadiiSquare;
    }


    cornerWt= 0.25;
    edgeWt = 0.5;
    radiusSqrSum = 0;
    eta = (nFaceNodes + edgeWt*nEdgeNodes + cornerWt*nCornerNodes)/nFaceNodes;//correction factor

    if (nFaceNodes < 100){
        cornerWt= 1;
        edgeWt = 1;
        eta = 1.0;
    }
    //writeMessageToParetoLog("label = %d, nNodesWithLabel %d",nodeLabel,h_NumNodesWithLabel[nodeLabel]);
    for (node = 0; node < h_nNodes; node++) {
        if (!doesNodeExist(node)) continue;
        if (h_nodeLabels[node] == nodeLabel) {// node lies on a face with the given face ID or label
            //writeMessageToParetoLog("Node %d",node);
            for (i =0; i < 3; i++) {
                if (BCType[i] == ELASTICITY_DIRICHLET) {
                    h_free[node] -= (int) pow(2.0,i);// initial value of 7, subtract 1 for u component, 2 for v, 4 for w
                    h_dirichlet[3*node+i] = BCValue[i];
                }
                else if (BCType[i] == ELASTICITY_RETAIN) {
                    h_retain[node] = true;// retain this node (in topology optimization)
                }
                else if (BCType[i] == ELASTICITY_NEUMANN){
                    //if (h_hexmesh_verbose) writeMessageToParetoLog("Applying ELASTICITY_NEUMANN on node %d",node);
                    if (isNodeOnCorner(node))
                        h_f[3*node+i] += (double) cornerWt*BCValue[i]/h_NumNodesWithLabel[nodeLabel];
                    else if (isNodeOnEdge(node))
                        h_f[3*node+i] += (double) edgeWt*BCValue[i]/h_NumNodesWithLabel[nodeLabel];
                    else
                        h_f[3*node+i] += (double) eta*BCValue[i]/h_NumNodesWithLabel[nodeLabel];

                }
                else if (BCType[i] == ELASTICITY_PRESSURE){
                    // For planar faces, the normal is stored along with pressure & area [dir_x dir_y dir_z pressure area 0]
                    // For cylinder faces, a pt on axis is stored along with pressure & area as [pt_x pt_y pt_z pressure area 0]
                    //    the normal can be computed from this information
                    // For other faces, the first 3 values are not relevant [* * * pressure area 0]
                    //   the normal is computed approximately from the voxel mesh
                    totalForce = BCValue[3]*BCValue[4];
                    if (BCValue[5] < 0) {// direction is known, planar surface
                        if (isNodeOnCorner(node))
                            h_f[3*node+i] += (double) cornerWt*totalForce*BCValue[i]/h_NumNodesWithLabel[nodeLabel];
                        else if (isNodeOnEdge(node))
                            h_f[3*node+i] += (double) edgeWt*totalForce*BCValue[i]/h_NumNodesWithLabel[nodeLabel];
                        else
                            h_f[3*node+i] += (double) eta*totalForce*BCValue[i]/h_NumNodesWithLabel[nodeLabel];
                    }
                    else if (BCValue[5] > 0) {//cylindrical surface
                        double nodeNormal[3];

                        axisPoint[0] = BCValue[0];
                        axisPoint[1] = BCValue[1];
                        axisPoint[2] = BCValue[2];
                        if (BCValue[5] == 1){// x direction axis
                            nodeNormal[0] = 0;
                            nodeNormal[1] = axisPoint[1] - h_y[node];
                            nodeNormal[2] = axisPoint[2] - h_z[node];
                        }
                        else if(BCValue[5] == 2){// y direction axis
                            nodeNormal[0] = axisPoint[0] - h_x[node];
                            nodeNormal[1] = 0;
                            nodeNormal[2] = axisPoint[2] - h_z[node];
                        }
                        else{
                            nodeNormal[0] = axisPoint[0] - h_x[node];
                            nodeNormal[1] = axisPoint[1] - h_y[node];
                            nodeNormal[2] = 0;
                        }
                        nrm = NORM3D(nodeNormal);
                        nodeNormal[0] /=nrm;
                        nodeNormal[1] /=nrm;
                        nodeNormal[2] /=nrm;

                        h_f[3*node+i] -= (double) totalForce*nodeNormal[i]/h_NumNodesWithLabel[nodeLabel];
                    }
                    else {//other surface
                        double nodeNormal[3];
                        getNormalAtNode(node,nodeNormal);// not very accurate
                        h_f[3*node+i] -= (double) totalForce*nodeNormal[i]/h_NumNodesWithLabel[nodeLabel];
                    }
                }
                else if (BCType[i] == ELASTICITY_OUTPUT){
                    h_output[3*node+i] = (double) BCValue[i]/h_NumNodesWithLabel[nodeLabel];
                }
                else if ((BCType[i] == ELASTICITY_TORQUE)){
                    if (i !=0) continue;// all three BCs are applied simultaneously
                    // torque/axis direction is given
                    axisDir[0] = BCValue[0];
                    axisDir[1] = BCValue[1];
                    axisDir[2] = BCValue[2];
                    nrm = NORM3D(axisDir);

                    axisDir[0]  /= nrm;
                    axisDir[1]  /= nrm;
                    axisDir[2]  /= nrm;
                    axisPoint[0] = BCValue[3];
                    axisPoint[1] = BCValue[4];
                    axisPoint[2] = BCValue[5];

                    vec[0] = h_x[node] - axisPoint[0];
                    vec[1] = h_y[node] - axisPoint[1];
                    vec[2] = h_z[node] - axisPoint[2];

                    //force is in the direction of cross product of vec and axis center
                    forceDir[0] = vec[1]*axisDir[2] - vec[2]*axisDir[1];
                    forceDir[1] = vec[2]*axisDir[0] - vec[0]*axisDir[2];
                    forceDir[2] = vec[0]*axisDir[1] - vec[1]*axisDir[0];

                    nrm = NORM3D(forceDir);
                    if (nrm < 1e-10) continue;
                    forceDir[0]  /= nrm;
                    forceDir[1]  /= nrm;
                    forceDir[2]  /= nrm;

                    dtprod = DOTPROD3D(vec,axisDir);
                    vec[0] -= dtprod*axisDir[0];
                    vec[1] -= dtprod*axisDir[1];
                    vec[2] -= dtprod*axisDir[2];
                    radius = NORM3D(vec);

                    radiusSqrSum += radius*radius;

                    // sum of force*radius must equal to totalTorque
                    // the forces must be scaled accordingly ...
                    h_f[3*node] += (forceDir[0]*radius);
                    h_f[3*node+1] += (forceDir[1]*radius);
                    h_f[3*node+2] +=  (forceDir[2]*radius);

                }
                else if ((BCType[i] == ELASTICITY_SLIDING)){
                    if (i !=0) continue;// all three BCs are applied simultaneously
                    // cylinder axis direction is given
                    axisDir[0] = BCValue[0];
                    axisDir[1] = BCValue[1];
                    axisDir[2] = BCValue[2];
                    nrm = NORM3D(axisDir);

                    axisDir[0]  /= nrm;
                    axisDir[1]  /= nrm;
                    axisDir[2]  /= nrm;
                }
                else if ((BCType[i] == ELASTICITY_BEARING_LOAD)){
                    double nodeNormal[3],scaling,force[3],forceNrm,a;

                    if (BCValue[3] == 1){// x direction axis
                        nodeNormal[0] = 0;
                        nodeNormal[1] = BCValue[4] - h_y[node];
                        nodeNormal[2] = BCValue[5] - h_z[node];
                    }
                    else if(BCValue[3] == 2){// y direction axis
                        nodeNormal[0] = BCValue[4] - h_x[node];
                        nodeNormal[1] = 0;
                        nodeNormal[2] = BCValue[5] - h_z[node];
                    }
                    else{// z axis
                        nodeNormal[0] = BCValue[4] - h_x[node];
                        nodeNormal[1] = BCValue[5] - h_y[node];
                        nodeNormal[2] = 0;
                    }
                    nrm = NORM3D(nodeNormal);
                    nodeNormal[0] /=nrm;
                    nodeNormal[1] /=nrm;
                    nodeNormal[2] /=nrm;

                    force[0] = BCValue[0];
                    force[1] = BCValue[1];
                    force[2] = BCValue[2];
                    forceNrm = NORM3D(force);

                    a = DOTPROD3D(force,nodeNormal)/forceNrm;
                    if (a >0) scaling = 0;// to retain surface, make this small
                    else scaling =  -3.14*a;//scaling

                    if (isNodeOnCorner(node))
                        h_f[3*node+i] += (double) scaling*cornerWt*BCValue[i]/h_NumNodesWithLabel[nodeLabel];
                    else if (isNodeOnEdge(node))
                        h_f[3*node+i] += (double) scaling*edgeWt*BCValue[i]/h_NumNodesWithLabel[nodeLabel];
                    else
                        h_f[3*node+i] += (double) scaling*eta*BCValue[i]/h_NumNodesWithLabel[nodeLabel];
                }
                else if ((BCType[i] == ELASTICITY_REMOTE_LOAD)){
                    if (i !=0) continue;// all three BCs are applied simultaneously
                    // The node forces are a combination of the direct force and moment
                    h_f[3*node] += BCValue[0]/h_NumNodesWithLabel[nodeLabel];
                    h_f[3*node+1] += BCValue[1]/h_NumNodesWithLabel[nodeLabel];
                    h_f[3*node+2] += BCValue[2]/h_NumNodesWithLabel[nodeLabel];

                    nodePt[0] = h_x[node];// needed for remote loading
                    nodePt[1] = h_y[node];
                    nodePt[2] = h_z[node];

                    radius = distanceOfPointFromLine3D(nodePt,momentLinePt1,momentLinePt2,closestPt);
                    double radiusVec[3],tangentVec[3],nrm;
                    radiusVec[0] = nodePt[0] - closestPt[0];
                    radiusVec[1] = nodePt[1] - closestPt[1];
                    radiusVec[2] = nodePt[2] - closestPt[2];
                    tangentVec[0] = radiusVec[2]*momentDirection[1] - radiusVec[1]*momentDirection[2];
                    tangentVec[1] = radiusVec[0]*momentDirection[2] - radiusVec[2]*momentDirection[0];
                    tangentVec[2] = radiusVec[1]*momentDirection[0] - radiusVec[0]*momentDirection[1];

                    nrm = NORM3D(tangentVec);
                    tangentVec[0] /= nrm;
                    tangentVec[1] /= nrm;
                    tangentVec[2] /= nrm;

                    h_f[3*node] += tangentVec[0]*radius*remoteLoadForceConstant;
                    h_f[3*node+1] += tangentVec[1]*radius*remoteLoadForceConstant;
                    h_f[3*node+2] += tangentVec[2]*radius*remoteLoadForceConstant;

                }
                else {
                    writeMessageToParetoLog("AFElasticity: Unknown BC %d",BCType[i]);
                }
            }
            double forceNode[3];
            forceNode[0] = h_f[3*node];
            forceNode[1] = h_f[3*node+1];
            forceNode[2] = h_f[3*node+2];

            if (NORM3D(forceNode) > 0)
                h_retain[node] = true;
        }
    }
    // for torque problems, we need to scale the forces
    if (radiusSqrSum > 0) { // torque BC
        totalTorque = NORM3D(BCValue);
        double K, C;
        K = totalTorque/radiusSqrSum;
        for (node = 0; node < h_nNodes; node++) {
            if (!doesNodeExist(node)) continue;
            if (h_nodeLabels[node] == nodeLabel) {
                C = K;
                if (isNodeOnCorner(node))
                    C = cornerWt*K;
                else if (isNodeOnEdge(node))
                    C = edgeWt*K;
                else
                    C = eta*K;
                h_f[3*node] *= C;
                h_f[3*node+1] *= C;
                h_f[3*node+2] *= C;
            }
        }
    }
    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: forceNorm = %e",getForceNorm());
}
/**********************************************************************/
void AFElasticity::setElasticityAcceleration(double acceleration[4])
{
    // combination of linear and radial acceleration
    int elem,node,m;
    double vol,fx,fy,fz,density,radialAcceleration,center[3],radius,boundingBox[3][2],xc,yc;

    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Calling setElasticityAcceleration");

    double radiansPerSec = acceleration[3];
    h_isThereAcceleration = false;
    if ( (NORM3D(acceleration) <TOL) && (fabs(radiansPerSec) < TOL))
        return;

    h_isThereAcceleration = true;

    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticitiy: Norm of force (before) = %e ",Norm(h_f,3*h_nNodes));
    getBoundingBox(boundingBox);
    xc = (boundingBox[0][0] + boundingBox[0][1])/2;
    yc = (boundingBox[1][0] + boundingBox[1][1])/2;

    double meshSize = getMeshElementSize();
    for ( elem =0; elem < h_nElems; elem++) {
        density = getDensityOfElem(elem);
        getElemCenter(elem,center);
        center[0] -=xc;
        center[1] -=yc;
        radius = MAX(sqrt(center[0]*center[0] + center[1]*center[1]),meshSize/2);//avoids division by zero
        radialAcceleration = radiansPerSec*radiansPerSec*radius;

        //note that the vector component of radial acceleratrion is (x/r,y/r)
        h_bodyForce[3*elem] = density*acceleration[0] + density*radialAcceleration*center[0]/radius;// store this for topological sensitivity
        h_bodyForce[3*elem+1] = density*acceleration[1] + density*radialAcceleration*center[1]/radius;
        h_bodyForce[3*elem+2] = density*acceleration[2];

        if (h_pseudoDensity[elem] < h_pseudoDensityCutoff) continue;
        vol = getElemVolume(elem);
        fx = h_bodyForce[3*elem]*vol/8;// shared by 8 nodes
        fy = h_bodyForce[3*elem+1]*vol/8;// shared by 8 nodes
        fz = h_bodyForce[3*elem+2]*vol/8;// shared by 8 nodes

        //cout << elem << " " << density << " " << vol << " " << fy << endl;

        for (m =0; m < 8; m++) {
            node = h_elems[(h_nElems)*m + elem];
            if (!isNodeFree(node)) continue;
            h_f[3*node] += fx;
            h_f[3*node+1] += fy;
            h_f[3*node+2] += fz;
        }

    }
    if (h_hexmesh_verbose) cout << "AFElasticitiy: Norm of force (after) " << Norm(h_f,3*h_nNodes) << endl;
}

/**********************************************************************/
int AFElasticity::dumpVoxelFile(char *fileName)
{
    /*
    Print the following (after discarding zero density voxels)
    % 1. #Grid
    % 2. nelx nely nelz
    % 3. #Origin
    % 4. X0 Y0 Z0
    % 5. #Step
    % 6. dx dy dz
    % 7. #Nodes
    % 8. h_nNodes
    % 9. (i,j,k,l) of all nodes (i ranges from 0 to nelx, etc), l is the label of node
    % 10. #Elems
    % 11. h_nElems
    % 12. (n1,n2,...,n8) of all elements
    Optionally ...
    % 13. #ElemId
    % 14 id0,id1,id2,.... for each element, the id (typically part #), default is 0
    Optionally ...
    % 15. #PseudoDensity
    % 16. 1,1,0,1,0,....

    CAVEAT:
    We assume a 0-index, i.e., it is assumed that all node numbers, element numbers, and
    templateIDs start from 0.
    Very limited error check
    */
    FILE *fptr;
    int elem, nElems, node, *nodeIn, m,nNodes,nx,ny,nz;
    int *nodeMapping = (int *)malloc(h_nNodes*sizeof(int));

    fptr = fopen(fileName,"w");

    fprintf(fptr,"#Grid\n");
    fprintf(fptr,"%d %d %d \n\n",h_nelx,h_nely,h_nelz);

    int yOffset = (h_nelx+1); // difference in 2 nodes that are next to each other in y
    int zOffset = (h_nelx+1)*(h_nely+1); // difference in 2 nodes that are next to each other in z
    int nodeIndex[8] = {0,1,yOffset+1,yOffset,zOffset,zOffset+1,zOffset+yOffset+1,zOffset+yOffset};

    fprintf(fptr,"#Origin\n");
    fprintf(fptr,"%e %e %e \n\n",h_xMin,h_yMin,h_zMin);

    fprintf(fptr,"#Step\n");
    fprintf(fptr,"%e %e %e \n\n",h_dx,h_dy,h_dz);

    // Identify all the nodes that are in
    nodeIn = (int *)malloc(h_nNodes*sizeof(int));
    memset(nodeIn,0,h_nNodes*sizeof(int));// all nodes are out by default

    nElems = 0;
    for (elem = 0; elem < h_nElems;elem++) {
        if (h_pseudoDensity[elem] > h_pseudoDensityCutoff) {// only dump non-zero elements
            nElems++;
            for (m = 0; m < 8; m++) {
                node = h_elems[(h_nElems)*m + elem];
                nodeIn[node] = 1;
            }
        }
    }
    nNodes = 0;
    for (node = 0; node < h_nNodes; node++) {
        if (nodeIn[node]) {
            nodeMapping[node] = nNodes;
            nNodes++;
        }
    }

    fprintf(fptr,"#Nodes\n");
    fprintf(fptr,"%d\n\n",nNodes);

    for (node = 0; node < nNodes; node++) {
        if (nodeIn[node]) {
            nx = (int) NEARESTINT((h_x[node]-h_xMin)/h_dx);
            ny = (int) NEARESTINT((h_y[node]-h_yMin)/h_dy);
            nz = (int) NEARESTINT((h_z[node]-h_zMin)/h_dz);
            fprintf(fptr,"%d %d %d %d\n",nx,ny,nz,h_nodeLabels[node]);
        }

    }

    fprintf(fptr,"#Elems\n");
    fprintf(fptr,"%d\n\n",nElems);
    for (elem = 0; elem < h_nElems;elem++) {
        if (h_pseudoDensity[elem] > h_pseudoDensityCutoff) {// only dump non-zero elements
            for (m = 0; m < 8; m++) {
                node = h_elems[(h_nElems)*m + elem];
                fprintf(fptr,"%d ",nodeMapping[node]);
            }
            fprintf(fptr,"\n");
        }
    }
    fprintf(fptr,"#PseudoDensity\n");
    for (elem = 0; elem < h_nElems;elem++) {
        if (h_pseudoDensity[elem] > h_pseudoDensityCutoff) {// only dump non-zero elements
            fprintf(fptr,"1 ");
        }
    }
    fprintf(fptr,"\n");
    free(nodeIn);
    free(nodeMapping);


    fclose(fptr);
    return 1;
}
/**********************************************************************/
int AFElasticity::dumpMeshAsAbaqusInpFile(char *fileName)
{
    /*
    Heading
    ** Job name:
    ** Generated by: ...
    *Preprint, echo=NO, model=NO, history=NO, contact=NO
    **
    ** PARTS
    **
    *Part, name=
    *Node
    1,         -7.5,          25.,          20.
    2,         -7.5,    21.041666,          20.
    3,         -7.5,    17.083334,          20.
    4,         -7.5,       13.125,          20.
    5,         -7.5,   9.16666698,          20.
    6,         -7.5,   5.20833349,          20.
    7,         -7.5,         1.25,          20.
    ...

    *Element, type=C3D8R
    1,  43,  44,  51,  50,   1,   2,   9,   8
    2,  44,  45,  52,  51,   2,   3,  10,   9
    3,  45,  46,  53,  52,   3,   4,  11,  10
    4,  46,  47,  54,  53,   4,   5,  12,  11
    5,  47,  48,  55,  54,   5,   6,  13,  12
    6,  48,  49,  56,  55,   6,   7,  14,  13
    7,  50,  51,  58,  57,   8,   9,  16,  15
    8,  51,  52,  59,  58,   9,  10,  17,  16
    ...

    *BOUNDARY

    *CLOAD

    */
    FILE *fptr;
    int node,elem,dof,j;

    fptr = fopen(fileName,"w");

    fprintf(fptr,"*Heading\n");
    fprintf(fptr,"** Job name: Unknown \n");
    fprintf(fptr,"** Generated by: Unknown \n");
    fprintf(fptr,"*Preprint, echo=NO, model=NO, history=NO, contact=NO\n");
    fprintf(fptr,"**\n** PARTS\n**\n");
    fprintf(fptr,"*Part, name=unknown\n");
    fprintf(fptr,"*Node\n");

    for ( node = 0; node < h_nNodes;node++)
        fprintf(fptr,"%d,%.4e,%.4e,%.4e\n",node+1,h_x[node],h_y[node],h_z[node]);//starting node is 1

    fprintf(fptr,"*Element, type=C3D8R\n");
    for (elem = 0; elem < h_nElems;elem++) {
        fprintf(fptr,"%d",elem+1);//starting elem is 1
        for (j =0; j < 8; j++)
            fprintf(fptr,", %d",h_elems[j*h_nElems+elem]+1);///starting node is 1
        fprintf(fptr,"\n");
    }
    double E,nu,rho,K,alpha,specificHeat;
    char materialName[256];
    getMaterialOfPart(0,&E, &nu,&rho,&K, &alpha,&specificHeat,materialName);
    // Material
    fprintf(fptr,"*MATERIAL, NAME=Unknown\n");
    fprintf(fptr,"*ELASTIC\n");
    fprintf(fptr,"%.4e, %.3f\n",E,nu);

    // Dirichlet boundary conditions
    fprintf(fptr,"*BOUNDARY\n");
    for ( node = 0; node < h_nNodes;node++) {
        switch (h_free[node]){
        case 0:
            fprintf(fptr,"%d, 1\n",node+1);// fixed in u
            fprintf(fptr,"%d, 2\n",node+1);// fixed in v
            fprintf(fptr,"%d, 3\n",node+1);// fixed in w
            break;
        case 1:
            fprintf(fptr,"%d, 2\n",node+1);// fixed in v
            fprintf(fptr,"%d, 3\n",node+1);// fixed in w
            break;
        case 2:
            fprintf(fptr,"%d, 1\n",node+1);// fixed in u
            fprintf(fptr,"%d, 3\n",node+1);// fixed in w
            break;
        case 3:
            fprintf(fptr,"%d, 3\n",node+1);// fixed in w
            break;
        case 4:
            fprintf(fptr,"%d, 1\n",node+1);// fixed in u
            fprintf(fptr,"%d, 2\n",node+1);// fixed in v
            break;
        case 5:
            fprintf(fptr,"%d, 2\n",node+1);// fixed in v
            break;
        case 6:
            fprintf(fptr,"%d, 1\n",node+1);// fixed in u
            break;
        case 7:
            continue;// nothing
            break;
        }
    }
    // Dirichlet boundary conditions
    fprintf(fptr,"*CLOAD\n");
    for ( node = 0; node < h_nNodes;node++) {
        for (dof = 0; dof < 3; dof++) {
            if (fabs(h_f[3*node + dof]) > 0)
                fprintf(fptr,"%d, %d, %.4e\n",node+1,dof+1,h_f[3*node + dof]);
        }
    }
    fclose(fptr);
    return 1;
}
/**********************************************************************/
void AFElasticity::dumpParetoMesh(const char *fileName)
{
    /*
    nNodes
    0         -7.5          25.          20.
    1         -7.5    21.041666          20.
    2         -7.5    17.083334          20.
    3         -7.5       13.125          20.
    4         -7.5   9.16666698          20.
    5         -7.5   5.20833349          20.
    6         -7.5         1.25          20.
    ...

    nElements
    0  43  44  51  50   0   2   9   8
    1  44  45  52  51   2   3  10   9
    2  45  46  53  52   3   4  11  10
    3  46  47  54  53   4   5  12  11

    ...
    #NodeLabel (for each node, label for BC)
    0 0 1 0 2 1 0
    ...

    #PseudoDensity (for each element, in or out)
    0.0 1.0 0.0 0.0 1.0 1 0 1 1 1 1 ...

    #ElemId (for each element
    0 0 1 1 0 2 ....
    */
    FILE *fptr;
    int node,elem,j;

    fptr = fopen(fileName,"w");

    fprintf(fptr,"%d\n",h_nNodes);
    for ( node = 0; node < h_nNodes;node++)
        fprintf(fptr,"%d %.8e %.8e %.8e\n",node,h_x[node],h_y[node],h_z[node]);//starting node is 0

    fprintf(fptr,"%d\n",h_nElems);
    for (elem = 0; elem < h_nElems;elem++) {
        fprintf(fptr,"%d",elem);//starting elem is 0
        for (j =0; j < 8; j++)
            fprintf(fptr," %d",h_elems[h_nElems*j+elem]);///starting node is 0
        fprintf(fptr,"\n");
    }
    fprintf(fptr,"#NodeLabel\n");
    for (node = 0; node < h_nNodes;node++) {
        fprintf(fptr,"%d ",h_nodeLabels[node]);
    }
    fprintf(fptr,"\n#PseudoDensity\n");
    for (elem = 0; elem < h_nElems;elem++) {
        fprintf(fptr,"%.1f ",h_pseudoDensity[elem]);
    }
    fprintf(fptr,"\n#ElemId\n");
    for (elem = 0; elem < h_nElems;elem++) {
        fprintf(fptr,"%d ",h_partIdOfElem[elem]);
    }

    fclose(fptr);
}

/**********************************************************************/
int AFElasticity::getMaxNodeLabel(void)
{
    return h_maxLabel;
}
/**********************************************************************/
void AFElasticity::setUseEigenProjection(bool useEigenState)
{
    h_useEigenProjection = useEigenState;
}
/**********************************************************************/
bool AFElasticity::doesNodeExist(int node)
{
    if ((node < 0) || (node >= h_nNodes)) return false;
    return h_nodeExists[node];
}
/**********************************************************************/
bool AFElasticity::isMeshVoxelized(void)
{
    if (h_voxelgrid)
        return true;
    else
        return false;
}
/**********************************************************************/
void AFElasticity::offsetMeshBy(double offset[3])
{
    for (int i =0; i < h_nNodes;i++){
        h_x[i] -= offset[0];
        h_y[i] -= offset[1];
        h_z[i] -= offset[2];
    }
}
/**********************************************************************/
int AFElasticity::readVoxelFile(const char *fileName)
{
    /*
    Read the following (generated via Voxel object)
    % 1. #Grid
    % 2. nelx nely nelz
    % 3. #Origin
    % 4. X0 Y0 Z0
    % 5. #Step
    % 6. dx dy dz
    % 7. #Nodes
    % 8. h_nNodes
    % 9. (i,j,k,l) of all nodes (i ranges from 0 to nelx, etc), l is the label of node
    % 10. #Elems
    % 11. h_nElems
    % 12. (n1,n2,...,n8) of all elements
    Optionally ...
    % 13. #PartId ...  to identify presence or absence of multiple material ids
    % 14 id0 id1 id2 ....) for each element, the id (typically part #), default is 0
    Optionally ...
    % 15. #PseudoDensity ..
    % 16. 1 1 0.7 1 0 ....

    CAVEAT:
    We assume a 0-index, i.e., it is assumed that all node numbers, element numbers, and
    templateIDs start from 0.
    Very limited error checks
    */

    int i,j,elem,label;
    double xMin,xMax,yMin,yMax,zMin,zMax,dx,dy,dz;
    int nelx,nely,nelz,nx,ny,nz;
    FILE *fptr;

    if (h_hexmesh_verbose) cout << "Entering readVoxelFile " << fileName << endl;
    InitializeAllAFElasticityVariables();
    ReleaseWorkSpace();// if assigned

    h_nTemplateElements = 1;// assume all voxels are geometrically identical and have the same material!!
    h_maxNeighboringElements = 8;// for regular grid
    h_voxelgrid = true; // all voxels are geometrically identical, must also set h_dx,d_dy and d_dz (see below)

    // writeMessageToParetoLog("Hexmesh: reading voxel data from %s",fileName);

    fptr = fopen(fileName,"r");

    if (fptr == NULL) {
        writeMessageToParetoLog("AFElasticity: Unable to find input file %s ",fileName);
        return -1;
    }

    fpos_t startPosition;
    fgetpos (fptr, &startPosition);

    if(!find_word(fptr,"#Grid")){
        writeMessageToParetoLog("AFElasticity: Searching for #Grid; invalid format ");
        fclose(fptr);
        return -1;
    }
    fscanf(fptr,"%d %d %d",&nelx,&nely,&nelz);
    h_nelx = nelx; h_nely = nely; h_nelz = nelz;

    if(!find_word(fptr,"#Origin")){
        writeMessageToParetoLog("AFElasticity: Searching for #Origin; invalid format ");
        fclose(fptr);
        return -1;
    }
    fscanf(fptr,"%lf %lf %lf",&xMin,&yMin,&zMin);
    h_xMin = xMin;
    h_yMin = yMin;
    h_zMin = zMin;

    if(!find_word(fptr,"#Step")){
        writeMessageToParetoLog("AFElasticity: Searching for #Step; invalid format");
        fclose(fptr);
        return -1;
    }
    fscanf(fptr,"%lf %lf %lf",&dx,&dy,&dz);

    h_voxelgrid = true; // uniform grid
    h_dx = dx;
    h_dy = dy;
    h_dz = dz;
    h_maxNeighboringElements = 8;// for regular grid

    if(!find_word(fptr,"#Nodes")){
        writeMessageToParetoLog("AFElasticity: Searching for #Nodes; invalid format");
        fclose(fptr);
        return -1;
    }

    fscanf(fptr,"%d ",&h_nNodes);
    if (h_nNodes < 0) {
        writeMessageToParetoLog("AFElasticity: Invalid h_nNodes %d ",h_nNodes);
        fclose(fptr);
        return -1;
    }
    if (allocateNodeMemory() != 1){
        fclose(fptr);
        return -1;
    }
    // also allocate for grid node mapping
    safeFree(h_gridNodeToRealNode);
    int nGridNodes = (nelx+1)*(nely+1)*(nelz+1);
    h_gridNodeToRealNode =(int *)malloc(nGridNodes*sizeof(int));
    memset(h_gridNodeToRealNode,-1,nGridNodes*sizeof(int));//set to -1


    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: h_nNodes = %d",h_nNodes);

    // Read the node indices
    h_modelScale = 0;
    xMax = -1e20;yMax = -1e20;zMax = -1e20;
    for (i = 0; i < HEXMESH_MAX_FACE_LABELS; i++)
        h_NumNodesWithLabel[i] = 0;

    h_maxLabel = 0;
    int yOffset = (nelx+1); // difference in 2 nodes that are next to each other in y
    int zOffset = (nelx+1)*(nely+1); // difference in 2 nodes that are next to each other in z
    int gridnode;

    for (i = 0; i < h_nNodes; i++){
        fscanf(fptr,"%d %d %d %d\n",&nx,&ny,&nz,&label);
        gridnode = nz*(nely+1)*(nelx+1) + ny*(nelx+1) + nx;
        h_gridNodeToRealNode[gridnode] = i;// set the grid node to map to this node number

        h_x[i] = nx*dx + xMin;
        h_y[i] = ny*dy + yMin;
        h_z[i] = nz*dz + zMin;
        h_nodeLabels[i] = label;
        h_NumNodesWithLabel[label]++;// used in force averaging
        h_maxLabel = MAX(h_maxLabel,label);
        xMax = (h_x[i] > xMax)? h_x[i]:xMax;
        yMax = (h_y[i] > yMax)? h_y[i]:yMax;
        zMax = (h_z[i] > zMax)? h_z[i]:zMax;
    }
    h_modelScale = 2*(MAX((xMax-xMin),MAX((yMax-yMin),(zMax-zMin))));

    writeMessageToParetoLog("AFElasticity: modelScale = %f",h_modelScale);
    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: modelScale = %f",h_modelScale);
    if(!find_word(fptr,"#Elems")){
        writeMessageToParetoLog("AFElasticity: Searching for #Elems; invalid format ");
        fclose(fptr);
        return -1;
    }
    fscanf(fptr,"%d ",&h_nElems);
    if (h_nElems < 0) {
        writeMessageToParetoLog("AFElasticity: Invalid h_nElems %d ",h_nElems);
        fclose(fptr);
        return -1;
    }
    if (h_hexmesh_verbose)
        writeMessageToParetoLog("AFElasticity: h_nElems = %d",h_nElems);

    if (allocateElemMemory() != 1){
        fclose(fptr);
        return -1;
    }
    //check to see if all nodes have been used
    int *nodesMarked = (int *)malloc(h_nNodes*sizeof(int));
    int node;
    memset(nodesMarked,0,h_nNodes*sizeof(int));
    // Read the mesh description
    for (i = 0; i < h_nElems; i++) {
        h_pseudoDensity[i] = 1.0;//all elements are in by default
        for (j =0; j <8; j++){// store the first nodes of all elements, then second nodes, etc
            fscanf(fptr,"%d ",&(node));
            h_elems[(h_nElems)*j + i] = node;
            nodesMarked[node] = 1;
        }
    }
    for (i =0; i < h_nNodes;i++)
        if (!nodesMarked[i]) writeMessageToParetoLog("AFElasticity: Warning, node %d not used ",i);

    free(nodesMarked);
    memset(h_materialIdOfElem,0,h_nElems*sizeof(int));
    memset(h_partIdOfElem,0,h_nElems*sizeof(int));

    if(!find_word(fptr,"#PartId")){
        ; // do nothing
    }
    else {
        int partId;
        for (elem = 0; elem < h_nElems; elem++){
            fscanf(fptr,"%d ",&(partId));
            if (partId >= h_nParts) {
                if (h_hexmesh_verbose)  writeMessageToParetoLog("AFElasticity: Element %d maps to unknown part %d; setting partId to 0 ",elem,partId);
                partId = 0;
            }
            h_partIdOfElem[elem] = partId;
            h_materialIdOfElem[elem] = h_partToMaterialMap[partId];
            h_templateID[elem] = h_materialIdOfElem[elem]; // they are the same for voxels
            h_nTemplateElements = MAX(h_nTemplateElements,h_templateID[elem]+1);
        }
    }
    fsetpos (fptr, &startPosition);// return back to beginning

    if(!find_word(fptr,"#PseudoDensity")){
        // writeMessageToParetoLog("AFElasticity: Could not find keyword PseudoDensity; assigning uniform value of 1");
        for (elem = 0; elem < h_nElems; elem++)
            h_pseudoDensity[elem] = 1.0; // default
    }
    else {
        double pMin=HUGE_VAL,pMax=1-HUGE_VAL;
        for (elem = 0; elem < h_nElems; elem++){
            fscanf(fptr,"%lf ",&(h_pseudoDensity[elem]));
            pMax = max(pMax,h_pseudoDensity[elem]);
            pMin = min(pMin,h_pseudoDensity[elem]);
        }
    }

    fclose(fptr);
    ts_currentIsoCounter = -1; // no previous history of topology optimization

    findNeighboringElemsOfNodes();
    findNeighboringNodesOfNodes();
    findAllNeighboringElems();// find neighbors of elements
#ifdef COMPILE_GPUCODE
    releaseHexmeshGPUMemory(&h_gpuData);
    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Attempting to create GPU memory for %d nodes ",h_nNodes);
    createAFElasticityGPUMemory( h_nNodes,h_nElems,h_maxNeighboringElements,h_nTemplateElements,&h_gpuData);
#endif
    return 1;
}
//*********************************************
bool AFElasticity::refineAndDumpVoxelFileBinary(const char *fileName)
// Split every element into 8 pieces and dump the resulting hexmesh
// It is assumed that all elements and nodes are valid
{
    /*
    Print the following in binary format
    % 1. nelx nely nelz
    % 2. X0 Y0 Z0
    % 3. dx dy dz
    % 4. h_nNodes
    % 5. (i,j,k,f) of all nodes (i ranges from 0 to nelx, etc), f is the facegroup
    % 6. h_nElems
    % 7. (n1,n2,...,n8) of all elements
    % 8 (m0,m1,m2,....) for each element, the material id, default is 0
    % 9. 1,0.9,0.2,1,0,.... for each element, the pseudo density, default is 1.0

    CAVEAT:
    We assume a 0-index, i.e., it is assumed that all gridnode numbers, element numbers, and
    templateIDs start from 0.
    */
    int tempIntArray[8],neighboringElems[27],neighbor,nFaces,*facePair,nEdges;
    double tempDoubleArray[3];
    int node,elem1,elem2,nNodes,nElems,elemNodes[8];
    double xNode,yNode,zNode,center1[3],center2[3],dx,dy,dz;

    // It is assumed that all elements and nodes are valid
    // But check this
    for (int elem = 0; elem < h_nElems; elem++) {
        if (h_pseudoDensity[elem] < h_pseudoDensityCutoff){
            writeMessageToParetoLog("AFElasticity: To use refineAndDumpVoxelFileBinary, first dump and read voxel mesh to eliminate void elements ");
            return false;
        }
    }

    // When each element is split into 8 elements, there is one extra node per face, and one extra node per element
    // Therefore, the total number of nodes is given by
    // h_nNodes + nFaces + nEdges + h_nElements;

    facePair = (int *)malloc(2*6*h_nElems*sizeof(int));// max possible pair indices
    memset(facePair,0,2*6*h_nElems*sizeof(int));
    // count the number of faces and find the corresponding pair of elements
    nFaces = 0;
    for (int elem = 0; elem < h_nElems; elem++) {
        getAllNeighboringElementsOfElem(elem,neighboringElems);
        for (int m = 1; m <= 6; m++) {//skip 0 (self), and consider the 6 fces
            neighbor = neighboringElems[m];
            if (neighbor == -1) {// boundary element
                facePair[2*nFaces] = elem;
                facePair[2*nFaces+1] = -m;// store the index of the face for later
                nFaces++;
            }
            else if (neighbor > elem) {// avoid double counting
                facePair[2*nFaces] = elem;
                facePair[2*nFaces+1] = neighbor;
                nFaces++;
            }
        }
    }
    // count the number of edges and find the corresponding pair of elements
    nEdges = 0;
    for (int elem = 0; elem < h_nElems; elem++) {
        getAllNeighboringElementsOfElem(elem,neighboringElems);
        for (int m = 7; m <= 14; m++) {//consider the 8 edges
            neighbor = neighboringElems[m];
            if (neighbor == -1) {// edge element
                facePair[2*nFaces] = elem;
                facePair[2*nFaces+1] = -m;// store the index of the edge for later
                nEdges++;
            }
            else if (neighbor > elem) {// avoid double counting
                facePair[2*nFaces] = elem;
                facePair[2*nFaces+1] = neighbor;
                nEdges++;
            }
        }
    }

    FILE *fptr = fopen(fileName,"wb");

    if (fptr == NULL){
        writeMessageToParetoLog("Could not open file %s ",fileName);
        return false;
    }

    tempIntArray[0] = 2*h_nelx;
    tempIntArray[1] = 2*h_nely;
    tempIntArray[2] = 2*h_nelz;
    fwrite(tempIntArray,sizeof(tempIntArray[0]),3,fptr);

    tempDoubleArray[0] = h_xMin;
    tempDoubleArray[1] = h_yMin;
    tempDoubleArray[2] = h_zMin;
    fwrite(tempDoubleArray,sizeof(tempDoubleArray[0]),3,fptr);

    tempDoubleArray[0] = h_dx/2;
    tempDoubleArray[1] = h_dy/2;
    tempDoubleArray[2] = h_dz/2;
    fwrite(tempDoubleArray,sizeof(tempDoubleArray[0]),3,fptr);

    dx = h_dx/2;
    dy = h_dy/2;
    dz = h_dz/2;
    nNodes = h_nNodes + nFaces + h_nElems;
    fwrite(&nNodes,sizeof(int),1,fptr);

    // write the indices of each of the original nodes
    for (int node = 0; node < h_nNodes; node++) {
        tempIntArray[0] = (int) NEARESTINT((h_x[node]-h_xMin)/dx);
        tempIntArray[1] = (int) NEARESTINT((h_y[node]-h_yMin)/dy);
        tempIntArray[2] = (int) NEARESTINT((h_z[node]-h_zMin)/dz);
        tempIntArray[3] = h_nodeLabels[node];
        fwrite(&tempIntArray,sizeof(int),4,fptr);
    }
    //next write the indicies of each of the face nodes

    for (int face = 0; face < nFaces; face++) {
        node = h_nNodes + face;
        elem1 = facePair[2*face];
        elem2 = facePair[2*face+1];
        if (elem2 >= 0) {//both are valid,the node is the center
            getElemCenter(elem1,center1);
            getElemCenter(elem2,center2);

            xNode = (center1[0] + center2[0])/2.0;
            yNode = (center1[1] + center2[1])/2.0;
            zNode = (center1[2] + center2[2])/2.0;

        }
        else {//the node is on the face
            //find the face index
            int index = -elem2;
            getElemCenter(elem1,center1);
            switch (index) {
            case 1:
                xNode = center1[0] - h_dx/2;
                yNode = center1[1];
                zNode = center1[2];
                break;
            case 2:
                xNode = center1[0];
                yNode = center1[1] - h_dy/2;
                zNode = center1[2];
                break;
            case 3:
                xNode = center1[0];
                yNode = center1[1];
                zNode = center1[2] - h_dz/2;
                break;
            case 4:
                xNode = center1[0] + h_dx/2;
                yNode = center1[1];
                zNode = center1[2];
                break;
            case 5:
                xNode = center1[0];
                yNode = center1[1] + h_dy/2;
                zNode = center1[2];
                break;
            case 6:
                xNode = center1[0] ;
                yNode = center1[1] ;
                zNode = center1[2] + h_dz/2;
                break;
            }
        }
        tempIntArray[0] = (int) NEARESTINT((xNode-h_xMin)/dx);
        tempIntArray[1] = (int) NEARESTINT((yNode-h_yMin)/dy);
        tempIntArray[2] = (int) NEARESTINT((zNode-h_zMin)/dz);
        tempIntArray[3] = 0;//??
        fwrite(&tempIntArray,sizeof(int),4,fptr);
    }
    //finally write the indices of the nodes at the center of each element
    for (int elem = 0; elem < h_nElems; elem++) {
        node = h_nNodes + nFaces + elem;

        getElemCenter(elem,center1);
        xNode = center1[0];
        yNode = center1[1];
        zNode = center1[2];

        tempIntArray[0] = (int) NEARESTINT((xNode-h_xMin)/dx);
        tempIntArray[1] = (int) NEARESTINT((yNode-h_yMin)/dy);
        tempIntArray[2] = (int) NEARESTINT((zNode-h_zMin)/dz);
        tempIntArray[3] = 0;//??
        fwrite(&tempIntArray,sizeof(int),4,fptr);
    }

    nElems = 8*h_nElems;//every element is divided into 8 elements
    fwrite(&nElems,sizeof(int),1,fptr);
    for (int elem = 0; elem < h_nElems;elem++) {
        for (int m = 0; m < 8; m++) //first gather all 8 nodes
            elemNodes[m] = h_elems[(h_nElems)*m + elem];

        // now construct all the the 8 elements
        tempIntArray[0] = elemNodes[0];
        tempIntArray[1] = elemNodes[0];
        tempIntArray[2] = elemNodes[0];
        tempIntArray[3] = elemNodes[0];
        tempIntArray[4] = elemNodes[0];
        tempIntArray[5] = elemNodes[0];
        tempIntArray[6] = elemNodes[0];
        tempIntArray[7] = elemNodes[0];

        fwrite(&tempIntArray,sizeof(int),8,fptr);
    }

    free(facePair);
    return true;
}
//*********************************************
bool AFElasticity::dumpMeshBinary(const char *fileName)
{
    /*
    Print the following in binary format
    % 1. nelx nely nelz
    % 2. X0 Y0 Z0
    % 3. dx dy dz
    % 4. h_nNodes
    % 5. (i,j,k,f) of all nodes (i ranges from 0 to nelx, etc), f is the facegroup
    % 6. h_nElems
    % 7. (n1,n2,...,n8) of all elements
    % 8 (m0,m1,m2,....) for each element, the material id, default is 0
    % 9. 1,0.9,0.2,1,0,.... for each element, the pseudo density, default is 1.0

    CAVEAT:
    We assume a 0-index, i.e., it is assumed that all gridnode numbers, element numbers, and
    templateIDs start from 0.
    */
    int tempIntArray[8];
    double tempDoubleArray[3];


    FILE *fptr = fopen(fileName,"wb");

    if (fptr == NULL){
        writeMessageToParetoLog("Could not open file %s ",fileName);
        return false;
    }

    tempIntArray[0] = h_nelx;
    tempIntArray[1] = h_nely;
    tempIntArray[2] = h_nelz;
    fwrite(tempIntArray,sizeof(tempIntArray[0]),3,fptr);

    tempDoubleArray[0] = h_xMin;
    tempDoubleArray[1] = h_yMin;
    tempDoubleArray[2] = h_zMin;
    fwrite(tempDoubleArray,sizeof(tempDoubleArray[0]),3,fptr);

    tempDoubleArray[0] = h_dx;
    tempDoubleArray[1] = h_dy;
    tempDoubleArray[2] = h_dz;
    fwrite(tempDoubleArray,sizeof(tempDoubleArray[0]),3,fptr);

    fwrite(&h_nNodes,sizeof(int),1,fptr);
    for (int node = 0; node < h_nNodes; node++) {
        tempIntArray[0] = (int) NEARESTINT((h_x[node]-h_xMin)/h_dx);
        tempIntArray[1] = (int) NEARESTINT((h_y[node]-h_yMin)/h_dy);
        tempIntArray[2] = (int) NEARESTINT((h_z[node]-h_zMin)/h_dz);
        tempIntArray[3] = h_nodeLabels[node];
        fwrite(&tempIntArray,sizeof(int),4,fptr);
    }

    fwrite(&h_nElems,sizeof(int),1,fptr);

    for (int elem = 0; elem < h_nElems;elem++) {
        for (int m = 0; m < 8; m++)
            tempIntArray[m] = h_elems[(h_nElems)*m + elem];
        fwrite(&tempIntArray,sizeof(int),8,fptr);
    }
    for (int elem = 0; elem < h_nElems;elem++)
        fwrite(&(h_partIdOfElem[elem]),sizeof(int),1,fptr);

    for (int elem = 0; elem < h_nElems;elem++)
        fwrite(&(h_pseudoDensity[elem]),sizeof(double),1,fptr);

    fclose(fptr);
    return true;
}
//*********************************************
bool AFElasticity::generateCuboidMeshWithMapping(int nElemsDesired, double boundingBox[3][2])
{
    // Initialize the following data
    /*
    % 1. Number of nodes
    % 2. Number of elements
    % 3. The max number of template elements (1 for a regular isotropic mesh)
    % 4. Max number of elements connected to any node (8 for a regular grid)
    % 5. For every element, its 8 nodes (mesh description)
    % 6. For every node, its neighboring elements, padded with zeros if necessary
    % 7. The number of Dirichlet dof
    % 8. All the Dirichlet dof
    % 9. The number of forced dof
    % 10. All the forced dof
    % 11. The forces at these dof
    % 12. For every element, its KElement ID (ranging from 1 to M)
    % 13. For each of the M distinct KElementID, 24*24 values

    */
    int node,elem,i,j,k,m,startNode,nels[3];
    int nelx,nely,nelz;
    double dx,dy,dz,Lx,Ly,Lz,volume,h,eta[3],maxAspectRatio,dsize[3];


    maxAspectRatio = 1.;

    Lx = (boundingBox[0][1]-boundingBox[0][0]);
    Ly = (boundingBox[1][1]-boundingBox[1][0]);
    Lz = (boundingBox[2][1]-boundingBox[2][0]);
    volume = Lx*Ly*Lz;
    h = pow(volume/nElemsDesired,1./3.0);// cube-root of ..


    if ((Lx > Ly) && (Lx > Lz)) {
        eta[0] = 1.0;
        eta[1] = MAX(Ly/Lx,1./maxAspectRatio);// between 0 and 1
        eta[2] = MAX(Lz/Lx,1./maxAspectRatio);

        dsize[0] = pow(volume/nElemsDesired/(eta[0]*eta[1]*eta[2]),1./3.0);// cube-root of
        dsize[1] = dsize[0]*eta[1];
        dsize[2] = dsize[0]*eta[2];
    }
    else if ((Ly > Lx) && (Ly > Lz)) {
        eta[1] = 1.0;
        eta[0] = MAX(Lx/Ly,1./maxAspectRatio);// between 0 and 1
        eta[2] = MAX(Lz/Ly,1./maxAspectRatio);

        dsize[1] = pow(volume/nElemsDesired/(eta[0]*eta[1]*eta[2]),1./3.0);// cube-root of
        dsize[0] = dsize[1]*eta[0];
        dsize[2] = dsize[1]*eta[2];
    }
    else if ((Lz > Lx) && (Lz > Lx)) {
        eta[2] = 1.0;
        eta[0] = MAX(Lx/Lz,1./maxAspectRatio);// between 0 and 1
        eta[1] = MAX(Ly/Lz,1./maxAspectRatio);

        dsize[2] = pow(volume/nElemsDesired/(eta[0]*eta[1]*eta[2]),1./3.0);// cube-root of
        dsize[0] = dsize[2]*eta[0];
        dsize[1] = dsize[2]*eta[1];
    }
    else {
        dsize[0]  =h;
        dsize[1] = h;
        dsize[2] = h;
    }
    nels[0] = (int) MAX(NEARESTINT(Lx/dsize[0]),2);
    nels[1] = (int) MAX(NEARESTINT(Ly/dsize[1]),2);
    nels[2] = (int) MAX(NEARESTINT(Lz/dsize[2]),2);
    dsize[0] = Lx/nels[0];
    dsize[1] = Ly/nels[1];
    dsize[2] = Lz/nels[2];


    writeMessageToParetoLog("generateCuboidMesh: %d %d %d ",nels[0],nels[1],nels[2]);

    writeMessageToParetoLog("generateCuboidMesh: %f %f %f ",dsize[0],dsize[1],dsize[2]);

    nelx = nels[0];
    nely = nels[1];
    nelz = nels[2];
    h_nelx = nelx;
    h_nely = nely;
    h_nelz = nelz;

    dx = dsize[0];
    dy = dsize[1];
    dz = dsize[2];
    h_voxelgrid = true; // uniform grid
    h_nMaterials = 0;// no material assigned
    h_dx = dx;
    h_dy = dy;
    h_dz = dz;

    releaseCPUMemory();// if there is memory assigned

    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: creating a grid mesh");

    h_nNodes = (nelx)*(nely)*(nelz);// this is because of mapping
    h_nElems = (nelx)*(nely)*(nelz);
    h_nTemplateElements = 1;
    h_maxNeighboringElements = 8;// for regular grid

    if (h_hexmesh_verbose)  writeMessageToParetoLog("AFElasticity: nDOF   = \t%d ",3*h_nNodes);

    if (!allocateNodeMemory())
        return false;
    if (!allocateElemMemory())
        return false;

    writeMessageToParetoLog("generateCuboidMesh: Elems = %d, Nodes = %d ",h_nElems,h_nNodes);
    // also allocate for grid node mapping
    safeFree(h_gridNodeToRealNode);
    int nGridNodes = h_nNodes;// all grid nodes are in by construction
    h_gridNodeToRealNode =(int *)malloc(nGridNodes*sizeof(int));
    // and they map to the corresponding node
    for (i = 0; i < nGridNodes; i++)
        h_gridNodeToRealNode[i] = i;

    h_neighborElems =(int *)malloc((h_nNodes)*h_maxNeighboringElements*sizeof(int));//8 for a regular grid

    //x,y,z location, nodes are numbered first along x, then along y and then along z
    int nodeNum;
    // due to cyclic BC, the numbering is one less per row
    int yOffset = (nelx+1); // difference in 2 nodes that are next to each other in y
    int zOffset = (nelx+1)*(nely+1); // difference in 2 nodes that are next to each other in z
    // Global and local node numbering: first along x, then along y and then along z
    nodeNum  = 0;
    h_modelScale = nelx*dx;
    h_modelScale = (nely*dy > h_modelScale)? nely*dy:h_modelScale;
    h_modelScale = (nelz*dz > h_modelScale)? nelz*dz:h_modelScale;

    h_xMin = -nelx*dx/2;
    h_yMin = -nely*dy/2;
    h_zMin = -nelz*dz/2;
    for (k = 0; k < nelz; k++) {//slowest
        for (j = 0; j < nely; j++)  {//next
            for (i = 0; i < nelx; i++)  {//fastest change
                h_x[nodeNum] = i*dx + h_xMin;
                h_y[nodeNum] = j*dy + h_yMin;
                h_z[nodeNum] = k*dz + h_zMin;
                nodeNum++;
            }
        }
    }
    int newNode,i1,j1,k1;
    int *nodeMapping = (int*)malloc((nelx+1)*(nely+1)*(nelz+1)*sizeof(int));
    for(k=0;k<=nelz;k++){
        for(j=0;j<=nely;j++){
            for(i = 0;i<=nelx;i++){
                node = i+(j+k*(nely+1))*(nelx+1);
                i1 = (i==nelx)?0:i;
                j1 = (j==nely)?0:j;
                k1 = (k==nelz)?0:k;
                newNode = i1+(j1+k1*nely)*nelx;
                nodeMapping[node] = newNode;
            }
        }
    }

    // Linear hex: 8 nodes per hex
    elem = 0;
    int nodeIndex[8] = {0,1,yOffset+1,yOffset,zOffset,zOffset+1,zOffset+yOffset+1,zOffset+yOffset};
    for (k = 0; k < nelz; k++) {//slowest
        for (j = 0; j < nely; j++)  {//next
            for (i = 0; i < nelx; i++)  {//fastest change
                startNode = i + j*yOffset + k*zOffset; // start node number for a given hex
                for (m = 0; m < 8; m++)
                    h_elems[(h_nElems)*m + elem] = nodeMapping[startNode + nodeIndex[m]];

                elem = elem+1;
            }
        }
    }
    safeFree(nodeMapping);
    //Initialize template IDs and density
    memset(h_materialIdOfElem,0,h_nElems*sizeof(int));
    memset(h_partIdOfElem,0,h_nElems*sizeof(int));
    memset(h_templateID,0,h_nElems*sizeof(int));

    //  neighboring elems,initialize the arrays
    for (node = 0; node < h_nNodes; node++) {
        h_nNeighboringElems[node] = 0;// no neighboring elems
        for (m = 0; m < 8; m++)
            h_neighborElems[(h_nNodes)*m + node] = -1;
    }
    for (elem =0; elem < h_nElems; elem++)
        h_pseudoDensity[elem] = 1.0;

    findNeighboringElemsOfNodes();
    findNeighboringNodesOfNodes();

#ifdef COMPILE_GPUCODE
    releaseHexmeshGPUMemory(&h_gpuData);
    createAFElasticityGPUMemory( h_nNodes,h_nElems,h_maxNeighboringElements,h_nTemplateElements,&h_gpuData);
#endif

    return true;
}


//*********************************************
bool AFElasticity::dumpMeshBinaryNonVoidElements(const char *fileName)
{
    // only save non-void elements, and associated nodes
    /*
    Print the following in binary format
    % 1. nelx nely nelz
    % 2. X0 Y0 Z0
    % 3. dx dy dz
    % 4. nValidNodes
    % 5. (i,j,k,f) of all valid nodes (i ranges from 0 to nelx, etc), f is the facegroup
    % 6. nNonVoidElements
    % 7. (n1,n2,...,n8) of all non-void elements
    % 8 (m0,m1,m2,....) for each non-void element, the material id, default is 0
    % 9. 1,0.9,0.2,1,0,.... the pseudo-density for each non-void element, the pseudo density, default is 1.0

    CAVEAT:
    We assume a 0-index, i.e., it is assumed that all gridnode numbers, element numbers, and
    templateIDs start from 0.
    */
    int tempIntArray[8],*nodeMapping;
    double tempDoubleArray[3];


    FILE *fptr = fopen(fileName,"wb");

    if (fptr == NULL){
        writeMessageToParetoLog("Could not open file %s ",fileName);
        return false;
    }

    nodeMapping = (int *)malloc(h_nNodes*sizeof(int));
    memset(nodeMapping,0,h_nNodes*sizeof(int));

    tempIntArray[0] = h_nelx;
    tempIntArray[1] = h_nely;
    tempIntArray[2] = h_nelz;
    fwrite(tempIntArray,sizeof(tempIntArray[0]),3,fptr);

    tempDoubleArray[0] = h_xMin;
    tempDoubleArray[1] = h_yMin;
    tempDoubleArray[2] = h_zMin;
    fwrite(tempDoubleArray,sizeof(tempDoubleArray[0]),3,fptr);

    tempDoubleArray[0] = h_dx;
    tempDoubleArray[1] = h_dy;
    tempDoubleArray[2] = h_dz;
    fwrite(tempDoubleArray,sizeof(tempDoubleArray[0]),3,fptr);


    // Count the number of valid nodes
    int nValidNodes = 0;
    for (int node = 0; node < h_nNodes; node++) {
        if (doesNodeExist(node)){
            nodeMapping[node] = nValidNodes;
            nValidNodes++;
        }
    }

    fwrite(&nValidNodes,sizeof(int),1,fptr);
    for (int node = 0; node < h_nNodes; node++) {
        if (doesNodeExist(node)) {
            tempIntArray[0] = (int) NEARESTINT((h_x[node]-h_xMin)/h_dx);
            tempIntArray[1] = (int) NEARESTINT((h_y[node]-h_yMin)/h_dy);
            tempIntArray[2] = (int) NEARESTINT((h_z[node]-h_zMin)/h_dz);
            tempIntArray[3] = h_nodeLabels[node];
            fwrite(&tempIntArray,sizeof(int),4,fptr);
        }
    }

    int nValidElems;

    nValidElems = 0;
    for (int elem = 0; elem < h_nElems;elem++) {
        if (h_pseudoDensity[elem] > h_pseudoDensityCutoff) // only dump non-zero elements
            nValidElems++;
    }

    fwrite(&nValidElems,sizeof(int),1,fptr);
    for (int elem = 0; elem < h_nElems;elem++) {
        if (h_pseudoDensity[elem] > h_pseudoDensityCutoff) {// only dump non-zero elements
            for (int m = 0; m < 8; m++) {
                int node = h_elems[(h_nElems)*m + elem];
                tempIntArray[m] = nodeMapping[node];
            }
            fwrite(&tempIntArray,sizeof(int),8,fptr);
        }
    }
    for (int elem = 0; elem < h_nElems;elem++) {
        if (h_pseudoDensity[elem] > h_pseudoDensityCutoff) // only dump non-zero elements
            fwrite(&(h_partIdOfElem[elem]),sizeof(int),1,fptr);
    }
    for (int elem = 0; elem < h_nElems;elem++) {
        if (h_pseudoDensity[elem] > h_pseudoDensityCutoff) // only dump non-zero elements
            fwrite(&(h_pseudoDensity[elem]),sizeof(double),1,fptr);
    }

    free(nodeMapping);
    fclose(fptr);
    return true;
}
/******************************************************************/
bool AFElasticity::dumpIsoSurfaceFromMesh(const char *fileName)
{
    int elem,neighboringElem,neighboringElemsOfElem[27];
    double x[8],y[8],z[8];
    int quads[6][4] = {{0,4,7,3},{0,1,5,4},{0,3,2,1},{1,2,6,5},{2,3,7,6},{4,5,6,7}};
    float fbuf[12];
    unsigned short att = 0;
    unsigned int nTriangles;
    bool neighboringElemsExists[7];



    FILE *fptr = fopen(fileName,"wb");
    if (fptr == NULL) {
        writeMessageToParetoLog("Unable to open STL file: %s ",fileName);
        return false;
    }
    char header[80];
    memset(header,'0', 80*sizeof( char));// dummy header
    fwrite(header,80,1, fptr);
    nTriangles = 0; // dummy, will overwrite later on
    fwrite(&nTriangles, sizeof(unsigned int), 1, fptr);

    nTriangles = 0;
    for (int partId =0; partId < getNumberOfParts(); partId++) {
        if (!shouldPartBeOptimized(partId)) continue;
        for (elem = 0; elem < getNumElems(); elem++) {
            if (h_pseudoDensity[elem] < h_pseudoDensityCutoff) continue;
            if (getPartIdOfElem(elem) != partId) continue;

            getAllNeighboringElementsOfElem(elem,neighboringElemsOfElem);
            // 0 is self, 1 is x-, 2 is y-,3 is z-, 4 is x+,5 is y+, 6 is z+
            neighboringElemsExists[0] = true;//self
            for (int m = 1; m < 7; m++) {// start with 1 for neighbors
                neighboringElemsExists[m] = false;// means we need to generate the quad surface with this neighbor
                neighboringElem = neighboringElemsOfElem[m];
                if (neighboringElem == -1) continue;

                if (h_pseudoDensity[neighboringElem] < h_pseudoDensityCutoff) continue;
                if (!shouldPartBeOptimized(getPartIdOfElem(neighboringElem))) continue;
                if ((getNumberOfParts() > 1) && (getPartIdOfElem(neighboringElem) != partId)) continue;
                neighboringElemsExists[m] = true;// this means we don't need to generate the quad on this boundary
            }
            getElemNodeLocation(elem,x,y,z);
            for (int m = 0; m < 6;m++) {// consider the six quads
                // make sure all 4 nodes are on boundary
                if (neighboringElemsExists[m+1]) continue;//offset by 1, don't plot boundary if neighbor exists
                // we don't care about normal
                fbuf[0] = 1.0f;
                fbuf[1] = 0.0f;
                fbuf[2] = 0.0f;

                // first traingle
                fbuf[3]  = (float) x[quads[m][0]];
                fbuf[4]  = (float) y[quads[m][0]];
                fbuf[5]  = (float) z[quads[m][0]];

                fbuf[6]  = (float) x[quads[m][1]];
                fbuf[7]  = (float) y[quads[m][1]];
                fbuf[8]  = (float) z[quads[m][1]];

                fbuf[9]  = (float) x[quads[m][2]];
                fbuf[10]  = (float) y[quads[m][2]];
                fbuf[11]  = (float) z[quads[m][2]];

                fwrite(fbuf, 12*sizeof(float), 1, fptr);
                fwrite(&att,sizeof(unsigned short),1,fptr);

                // second triangle

                fbuf[3]  = (float) x[quads[m][0]];
                fbuf[4]  = (float) y[quads[m][0]];
                fbuf[5]  = (float) z[quads[m][0]];

                fbuf[6]  = (float) x[quads[m][2]];
                fbuf[7]  = (float) y[quads[m][2]];
                fbuf[8]  = (float) z[quads[m][2]];

                fbuf[9]  = (float) x[quads[m][3]];
                fbuf[10]  = (float) y[quads[m][3]];
                fbuf[11]  = (float) z[quads[m][3]];

                fwrite(fbuf, 12*sizeof(float), 1, fptr);
                fwrite(&att,sizeof(unsigned short),1,fptr);

                nTriangles +=2;
            }
        }
    }
    fseek(fptr,80,SEEK_SET);
    // write the number of triangles
    fwrite(&nTriangles, sizeof(unsigned int), 1, fptr);
    fclose(fptr);
    return true;
}
/**********************************************************************/
bool AFElasticity::readVoxelFileBinary(const char *fileName,bool disregardPseudoDensity)
{
    /*
    Read the following (generated via Voxel object)
    % 1. nelx nely nelz (#number of elements in x, y and z)
    % 2. X0 Y0 Z0 (origin)
    % 3. dx dy dz (deltax, deltay, deltaz)
    % 4. h_nNodes
    % 5. (i,j,k,l) of all nodes (i ranges from 0 to nelx, etc), l is the label of node
    % 6. h_nElems
    % 7. (n1,n2,...,n8) of all elements
    % 8. m0 m1 m2 ....) for each element, the id (typically part #), default is 0
    % 9. 1 1 0.7 1 0 ....

    CAVEAT:
    We assume a 0-index, i.e., it is assumed that all node numbers, element numbers, and
    templateIDs start from 0.
    Very limited error checks
    */

    int i,j,elem,label,partId,nx,ny,nz,tempIntArray[10];
    double xMax,yMax,zMax,tempDoubleArray[3];
    FILE *fptr;

    if (h_hexmesh_verbose) cout << "Entering readVoxelFileBinary " << fileName << endl;
    InitializeAllAFElasticityVariables();
    ReleaseWorkSpace();// if assigned

    h_nTemplateElements = 1;// all voxels are geometrically identical and have the same material!!
    h_maxNeighboringElements = 8;// for regular grid
    h_voxelgrid = true; // all voxels are geometrically identical, must also set h_dx,d_dy and d_dz (see below)

    fptr = fopen(fileName,"rb");
    if (fptr == NULL) {
        writeMessageToParetoLog("AFElasticity: Unable to find input file %s", fileName);
        return false;
    }


    fread(tempIntArray,sizeof(tempIntArray[0]),3,fptr);
    h_nelx = tempIntArray[0]; h_nely = tempIntArray[1]; h_nelz = tempIntArray[2];

    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: mesh (%d,%d,%d) ",h_nelx,h_nely,h_nelz);
    fread(tempDoubleArray,sizeof(tempDoubleArray[0]),3,fptr);

    h_xMin = tempDoubleArray[0];
    h_yMin = tempDoubleArray[1];
    h_zMin = tempDoubleArray[2];

    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: min (%g,%g,%g) ",h_xMin,h_yMin,h_zMin);

    fread(tempDoubleArray,sizeof(tempDoubleArray[0]),3,fptr);
    h_dx = tempDoubleArray[0];
    h_dy = tempDoubleArray[1];
    h_dz = tempDoubleArray[2];

    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: delta (%g,%g,%g) ",h_dx,h_dy,h_dz);

    h_maxNeighboringElements = 8;// for regular grid
    fread(&h_nNodes,sizeof(int),1,fptr);
    if (h_nNodes < 0) {
       writeMessageToParetoLog("AFElasticity: Invalid h_nNodes %d ",h_nNodes);
        fclose(fptr);
        return false;
    }
    if (!allocateNodeMemory()){
        fclose(fptr);
        return false;
    }
    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: h_nNodes = %d ",h_nNodes);

    // also allocate for grid node mapping
    safeFree(h_gridNodeToRealNode);
    int nGridNodes = (h_nelx+1)*(h_nely+1)*(h_nelz+1);
    h_gridNodeToRealNode =(int *)malloc(nGridNodes*sizeof(int));
    memset(h_gridNodeToRealNode,-1,nGridNodes*sizeof(int));//set to -1

    // Read the node indices
    h_modelScale = 0;
    xMax = -HUGE_VAL;yMax = -HUGE_VAL;zMax = -HUGE_VAL;
    for (i = 0; i < HEXMESH_MAX_FACE_LABELS; i++)
        h_NumNodesWithLabel[i] = 0;

    h_maxLabel = 0;
    int gridnode;

    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: computing modelscale ");
    for (i = 0; i < h_nNodes; i++){
        fread(tempIntArray,sizeof(tempIntArray[0]),4,fptr);
        nx = tempIntArray[0];ny = tempIntArray[1];nz = tempIntArray[2];
        label = tempIntArray[3];
        gridnode = nz*(h_nely+1)*(h_nelx+1) + ny*(h_nelx+1) + nx;
        h_gridNodeToRealNode[gridnode] = i;// set the grid node to map to this node number

        h_x[i] = nx*h_dx + h_xMin;
        h_y[i] = ny*h_dy + h_yMin;
        h_z[i] = nz*h_dz + h_zMin;
        h_nodeLabels[i] = label;
        // a check is needed in case no labels have been assigned
        if (label >=0) h_NumNodesWithLabel[label]++;// used in force averaging
        h_maxLabel = MAX(h_maxLabel,label);
        xMax = (h_x[i] > xMax)? h_x[i]:xMax;
        yMax = (h_y[i] > yMax)? h_y[i]:yMax;
        zMax = (h_z[i] > zMax)? h_z[i]:zMax;
    }
    h_modelScale = 2*(MAX((xMax-h_xMin),MAX((yMax-h_yMin),(zMax-h_zMin))));
    writeMessageToParetoLog("AFElasticity: modelScale = %e", h_modelScale);

    fread(&h_nElems,sizeof(int),1,fptr);
    if (h_nElems < 0) {
        writeMessageToParetoLog("AFElasticity: Invalid h_nElems %d ",h_nElems);
        fclose(fptr);
        return false;
    }
    if (h_hexmesh_verbose)cout << "AFElasticity: h_nElems = " << h_nElems << endl;
    if (!allocateElemMemory()){
        fclose(fptr);
        return false;
    }
    //check to see if all nodes have been used
    bool *nodesMarked = (bool *)malloc(h_nNodes*sizeof(bool));
    int node;
    memset(nodesMarked,false,h_nNodes*sizeof(bool));
    // Read the mesh description
    for (i = 0; i < h_nElems; i++) {
        h_pseudoDensity[i] = 1.0;//all elements are in by default
        for (j =0; j <8; j++){// store the first nodes of all elements, then second nodes, etc
            fread(&node,sizeof(int),1,fptr);
            h_elems[(h_nElems)*j + i] = node;
            nodesMarked[node] = true;
        }
    }
    bool tempBool = false;

    for (i =0; i < h_nNodes;i++)
        if ((!nodesMarked[i]) && (!tempBool)) {
            writeMessageToParetoLog("AFElasticity: Warning, at least one node %d is not used ", i);
            tempBool = true;
        }
    free(nodesMarked);

    memset(h_materialIdOfElem,0,h_nElems*sizeof(int));
    for (elem = 0; elem < h_nElems; elem++){
        fread(&partId,sizeof(int),1,fptr);
        if (partId >= h_nParts) {
            //writeMessageToParetoLog("AFElasticity: Element %d maps to unknown part %d; setting partId to 0 ",elem,partId);
            partId = 0;
        }
        h_partIdOfElem[elem] = partId;
        h_materialIdOfElem[elem] = h_partToMaterialMap[partId];
        h_templateID[elem] = h_materialIdOfElem[elem]; // they are the same for voxels
        h_nTemplateElements = MAX(h_nTemplateElements,h_templateID[elem]+1);
    }

    fread(h_pseudoDensity,sizeof(double),h_nElems,fptr);
    if (disregardPseudoDensity){
        for (elem = 0; elem < h_nElems; elem++)
            h_pseudoDensity[elem] = 1.0;
    }

    // determine if SIMP mode; this will allow soft elements and not trigger disconnected elements
    for (elem = 0; elem < h_nElems; elem++){
        if ( (h_pseudoDensity[elem] > 0) && (h_pseudoDensity[elem] <1) ){
             h_simpMode = true;
             break;
        }
    }
    if (h_simpMode)
        writeMessageToParetoLog("AFElasticity: SIMP mode ");
    else
        writeMessageToParetoLog("AFElasticity: Non-SIMP mode ");
    fclose(fptr);
    ts_currentIsoCounter = -1; // no previous history of topology optimization

    findNeighboringElemsOfNodes();
    findNeighboringNodesOfNodes();
    findAllNeighboringElems();// find neighbors of elements
#ifdef COMPILE_GPUCODE
    releaseHexmeshGPUMemory(&h_gpuData);
    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Attempting to create GPU memory for %d nodes ",h_nNodes);
    createAFElasticityGPUMemory( h_nNodes,h_nElems,h_maxNeighboringElements,h_nTemplateElements,&h_gpuData);
#endif
    writeMessageToParetoLog("AFElasticity: Mesh read ");
    return true;
}
//*********************************************
bool AFElasticity::createQuadraticMesh(void)
// create 27 nodes for each element
// the locations of the 27 nodes is NOT created
// only the global numbering is recorded
{
    int nElems;

    nElems = getNumElems();
    if (nElems == 0){
        writeMessageToParetoLog ("Primary mesh does not exist; cannot create quadratic mesh");
        return false;
    }

    // release previous memory
    if (h_elem27Nodes != NULL){
          for (int elem = 0; elem < nElems; elem++)
              safeFree(h_elem27Nodes[elem]);
          safeFree(h_elem27Nodes);
    }

    // every element has 27 nodes
    h_elem27Nodes = (int **)malloc(nElems*sizeof(int *));
    for (int elem = 0; elem < nElems; elem++){
        h_elem27Nodes[elem] = (int *)malloc(27*sizeof(int));
        for (int i = 0; i < 27; i++)
            h_elem27Nodes[elem][i] = -1;// default
    }

    // Global numbering for 27 node elements are as follows
    // First the corner nodes
    // Next the face nodes
    // Next the edge nodes
    // Finally the center nodes

    // Enter the corner nodes
    int cornerNodeIndex[] = {0,2,8,6,18,20,26,24};
    int linearNodes[8];
    for (int elem = 0; elem < nElems; elem++){
        getElemNodes(elem,linearNodes);
        for (int i = 0; i < 8; i++){
            h_elem27Nodes[elem][cornerNodeIndex[i]] = linearNodes[i];
        }
    }


    // create face nodes
    int faceNodeIndex[] = {12,10,4,14,16,22};// this order matches h_StructuringElems ... see powerpoint slides
    int matchingFaceNodeIndex[] = {14,16,22,12,10,4};// helps extract the face node from neighbor
    int globalNodeNumber,previousGlobalNode;
    int nFaceNodes;
    nFaceNodes = 0;
    globalNodeNumber = getNumNodes();// we start from here
    for (int elem = 0; elem < nElems; elem++){
        int neighborElem;
        for (int i = 1; i < 7; i++){//6 faces
            neighborElem = h_StructuringElems[h_StructuringSize*elem+i];
            // we consider 3 cases
            if (neighborElem == -1) {// there is no other element next to this face
                h_elem27Nodes[elem][faceNodeIndex[i]] = globalNodeNumber;
                globalNodeNumber++;//create a new global node
                nFaceNodes++;
            }
            else if (elem < neighborElem) {// there is an adjacent elem and this has NOT been visited
                h_elem27Nodes[elem][faceNodeIndex[i]] = globalNodeNumber;
                globalNodeNumber++;//create a new global node
                nFaceNodes++;
            }
            else {// there is an adjacent elem but this HAS been visited. So don't double count.
                previousGlobalNode = h_elem27Nodes[neighborElem][matchingFaceNodeIndex[i]];
                h_elem27Nodes[elem][faceNodeIndex[i]] = previousGlobalNode;
            }
        }
    }
    writeMessageToParetoLog ("nFaceNodes: %d", nFaceNodes);


    //create edge nodes
    int localIndex[] = {7,8,9,11,12,13,15,16,17,18,19,20};
    int edgeNodeIndex[] = {9,3,1,17,23,25,15,21,19,11,5,7};// this order matches h_StructuringElems ... see powerpoint slides
    int matchingEdgeNodeIndex[] = {17,23,25,9,3,1,11,5,7,15,21,19};// helps extract the face node from neighbor
    int nEdgeNodes;
    nEdgeNodes = 0;
    for (int elem = 0; elem < nElems; elem++){
        int neighborElem;
        for (int i = 1; i <12 ; i++){//12 edges
            neighborElem = h_StructuringElems[h_StructuringSize*elem+localIndex[i]];
            // we consider 3 cases
            if (neighborElem == -1) {// there is no other element next to this edge
                h_elem27Nodes[elem][edgeNodeIndex[i]] = globalNodeNumber;
                globalNodeNumber++;//create a new global node
                nEdgeNodes++;
            }
            else if (elem < neighborElem) {// there is an adjacent elem and this has NOT been visited
                h_elem27Nodes[elem][edgeNodeIndex[i]] = globalNodeNumber;
                globalNodeNumber++;//create a new global node
                nEdgeNodes++;
            }
            else {// there is an adjacent elem but this HAS been visited. So don't double count.
                previousGlobalNode = h_elem27Nodes[neighborElem][matchingEdgeNodeIndex[i]];
                h_elem27Nodes[elem][edgeNodeIndex[i]] = previousGlobalNode;
            }
        }
    }
    writeMessageToParetoLog ("nEdgeNodes: %d", nEdgeNodes);
    //create center nodes
    for (int elem = 0; elem < nElems; elem++){
        h_elem27Nodes[elem][13] = globalNodeNumber;
        globalNodeNumber++;
    }
    h_nQuadraticNodes = globalNodeNumber;
    writeMessageToParetoLog ("nQuadraticNodes: %d", h_nQuadraticNodes);
    return true;
}
/***********************************************************/
bool AFElasticity::getElemQuadraticNodes(int elem,int elemNodes[27])
{
    if (h_nQuadraticNodes == 0)
        return false;

    if ((elem < 0) || (elem >= getNumElems()))
        return false;

    for (int i = 0; i < 27; i++)
        elemNodes[i] = h_elem27Nodes[elem][i];
    return false;
}

/**********************************************************************/
bool AFElasticity::laplaceSmoothVoxelMesh(double eta)
{
    if (!h_voxelgrid){
        writeMessageToParetoLog("AFElasticity: laplaceSmoothVoxelMesh only works on voxel data ");
        return false;
    }
    int neighborNodes[27],nNeighbors,neighbor;
    double x,y,z;
    for (int node = 0; node < h_nNodes; node++) {
        nNeighbors = getNeighborNodesOfNode(node,neighborNodes);
        x = y = z = 0;
        for (int i = 0; i < nNeighbors; i++) {
            neighbor = neighborNodes[i];
            x += h_x[neighbor];
            y += h_y[neighbor];
            z += h_z[neighbor];
        }
        h_x[node] = eta*h_x[node] + (1-eta)*x/nNeighbors;
        h_y[node] = eta*h_y[node] + (1-eta)*y/nNeighbors;
        h_z[node] = eta*h_z[node] + (1-eta)*z/nNeighbors;
    }
    return true;
}
/**********************************************************************/
int AFElasticity::readParetoMeshFile(const char *fileName)
{
    /*
    nNodes
    0         -7.5          25.          20.
    1         -7.5    21.041666          20.
    2         -7.5    17.083334          20.
    3         -7.5       13.125          20.
    4         -7.5   9.16666698          20.
    5         -7.5   5.20833349          20.
    6         -7.5         1.25          20.
    ...
    nElements
    0  43  44  51  50   0   2   9   8
    1  44  45  52  51   2   3  10   9
    2  45  46  53  52   3   4  11  10
    3  46  47  54  53   4   5  12  11

    ...
    #NodeLabel (optional, for each node)
    0 1 0 1 0 0 2 0 ...
    #PseudoDensity (for each element, in or out)
    0.0 1.0 0.0 0.0 1.0 1 0 1 1 1 1 ...

    */


    int i,j,elem,node;
    double xMin,xMax,yMin,yMax,zMin,zMax,x,y,z;
    FILE *fptr;

    InitializeAllAFElasticityVariables();
    ReleaseWorkSpace();// if assigned
    releaseCPUMemory();// if there is memory assigned

    h_voxelgrid = false; // all voxels are geometrically identical, must also set h_dx,d_dy and d_dz (see below)

    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: reading mesh data from %s",fileName);
    fptr = fopen(fileName,"r");
    if (fptr == NULL) {
        writeMessageToParetoLog("AFElasticity: Unable to find input file %s ",fileName);
        return -1;
    }

    fscanf(fptr,"%d ",&h_nNodes);
    if (h_nNodes < 0) {
        writeMessageToParetoLog("AFElasticity: Invalid h_nNodes %d ",h_nNodes);
        h_nNodes= 0;
        fclose(fptr);
        return -1;
    }
    if (allocateNodeMemory() != 1){
        fclose(fptr);
        return -1;
    }

    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: h_nNodes = %d",h_nNodes);

    // Read the node indices
    h_modelScale = 0;
    xMin = 1e20;yMin = 1e20;zMin = 1e20;
    xMax = -1e20;yMax = -1e20;zMax = -1e20;
    for (i = 0; i < h_nNodes; i++){
        fscanf(fptr,"%d %lf %lf %lf\n",&node,&x,&y,&z);

        h_x[node] = x;
        h_y[node] = y;
        h_z[node] = z;

        xMin = (h_x[node] < xMin)? h_x[node]:xMin;
        yMin = (h_y[node] < yMin)? h_y[node]:yMin;
        zMin = (h_z[node] < zMin)? h_z[node]:zMin;

        xMax = (h_x[node] > xMax)? h_x[node]:xMax;
        yMax = (h_y[node] > yMax)? h_y[node]:yMax;
        zMax = (h_z[node] > zMax)? h_z[node]:zMax;
    }

    h_modelScale = (0.5*MIN((xMax-xMin),MIN((yMax-yMin),(zMax-zMin))) +0.5* MAX((xMax-xMin),MAX((yMax-yMin),(zMax-zMin))));

    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: modelScale = %f",h_modelScale);

    fscanf(fptr,"%d ",&h_nElems);
    if (h_nElems < 0) {
        writeMessageToParetoLog("AFElasticity: Invalid h_nElems %d ",h_nElems);
        h_nElems = 0;
        fclose(fptr);
        return -1;
    }
    if (h_hexmesh_verbose)	 writeMessageToParetoLog("AFElasticity: h_nElems = %d",h_nElems);

    if (allocateElemMemory() != 1){
        fclose(fptr);
        return -1;
    }
    // Read the mesh description
    for (i = 0; i < h_nElems; i++) {
        fscanf(fptr,"%d ",&(elem));
        for (j =0; j <8; j++){// store the first nodes of all elements, then second nodes, etc
            fscanf(fptr,"%d ",&(node));
            if ((node <0 ) || (node >= h_nNodes)){
                writeMessageToParetoLog("AFElasticity: Invalid node %d for elem %d ",node, i);
                h_nElems = 0;
                fclose(fptr);
                return -1;
            }
            h_elems[j*h_nElems + elem] = node;
        }
    }
    memset(h_materialIdOfElem,0,h_nElems*sizeof(int));
    memset(h_partIdOfElem,0,h_nElems*sizeof(int));

    fseek(fptr,0,SEEK_SET);// go to the beginning
    if(!find_word(fptr,"#NodeLabel")){
        for (node = 0; node < h_nNodes; node++)
            h_nodeLabels[node] = 0; // default
    }
    else{
        int label;
        for (node = 0; node < h_nNodes; node++){
            fscanf(fptr,"%d ",&(label));
            h_nodeLabels[node] = label;
            h_NumNodesWithLabel[label]++;// used in force averaging
        }
    }
    fseek(fptr,0,SEEK_SET);// go to the beginning
    if(!find_word(fptr,"#PseudoDensity")){
        for (elem = 0; elem < h_nElems; elem++)
            h_pseudoDensity[elem] = 1.0; // default
    }
    else {
        for (elem = 0; elem < h_nElems; elem++)
            fscanf(fptr,"%lf ",&(h_pseudoDensity[elem]));
    }

    fclose(fptr);
    ts_currentIsoCounter = -1; // no previous history of topology optimization
    discardTemplates();// all elements are distinct by default

    findNeighboringElemsOfNodes();
    //findNeighboringNodesOfNodes();// not valid for arbitrary hex mesh
    //findAllNeighboringElems();// not valid for arbitrary hex mesh
#ifdef COMPILE_GPUCODE
    releaseHexmeshGPUMemory(&h_gpuData);
    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Attempting to create GPU memory for %d nodes ",h_nNodes);
    createAFElasticityGPUMemory( h_nNodes,h_nElems,h_maxNeighboringElements,h_nTemplateElements,&h_gpuData);
#endif
    return 1;
}
/**********************************************************************/
int AFElasticity::findNodesAlongDirection(int nx,int ny,int nz,int dir,int *nodes)
// Given a start tuple (nx,ny,nz), a direction (+/- 1 for x, +/-2 for y, +/- 3 for z),
// find all the nodes along that path
// It is assumed that the memory for nodes has been allocated
{

    if (!h_voxelgrid){
        writeMessageToParetoLog("AFElasticity: findNodesAlongDirection only works on voxel data ");
        return 0;
    }
    int nNodesFound = 0;
    int gridnode,node;

    if ((dir == 1) || (dir == -1)) {// x
        if (dir >0){
            for (nx = nx; nx <= h_nelx; nx += 1) {
                gridnode = nz*(h_nely+1)*(h_nelx+1) + ny*(h_nelx+1) + nx;
                node = h_gridNodeToRealNode[gridnode];
                if (node >= 0) // real node
                    nodes[nNodesFound++] = node;
            }
        }
        if (dir <0){
            for (nx = nx; nx >= 0; nx -= 1) {
                gridnode = nz*(h_nely+1)*(h_nelx+1) + ny*(h_nelx+1) + nx;
                node = h_gridNodeToRealNode[gridnode];
                if (node >= 0) // real node
                    nodes[nNodesFound++] = node;
            }
        }
    }
    else if ((dir == 2) || (dir == -2)) {// y
        if (dir >0){
            for (ny = ny; ny <= h_nely; ny += 1) {
                gridnode = nz*(h_nely+1)*(h_nelx+1) + ny*(h_nelx+1) + nx;
                node = h_gridNodeToRealNode[gridnode];
                if (node >= 0) // real node
                    nodes[nNodesFound++] = node;
            }
        }
        if (dir <0){
            for (ny = ny; ny >= 0; ny -= 1) {
                gridnode = nz*(h_nely+1)*(h_nelx+1) + ny*(h_nelx+1) + nx;
                node = h_gridNodeToRealNode[gridnode];
                if (node >= 0) // real node
                    nodes[nNodesFound++] = node;
            }
        }

    }
    else if ((dir == 3) || (dir == -3)) {// z
        if (dir >0){
            for (nz = nz; nz <= h_nelz; nz += 1) {
                gridnode = nz*(h_nely+1)*(h_nelx+1) + ny*(h_nelx+1) + nx;
                node = h_gridNodeToRealNode[gridnode];
                if (node >= 0) // real node
                    nodes[nNodesFound++] = node;
            }
        }
        if (dir <0){
            for (nz = nz; nz >= 0; nz -= 1) {
                gridnode = nz*(h_nely+1)*(h_nelx+1) + ny*(h_nelx+1) + nx;
                node = h_gridNodeToRealNode[gridnode];
                if (node >= 0) // real node
                    nodes[nNodesFound++] = node;
            }
        }
    }

    return nNodesFound;
}
/**********************************************************************/
int AFElasticity::findElementsAlongDirection(int nx,int ny,int nz,int dir,int *elements)
// Given a start tuple (nx,ny,nz), a direction ( 1 for x, 2 for y, 3 for z),
// find all the nodes along that path
// It is assumed that the memory for elements has been allocated
{

    if (!h_voxelgrid){
        writeMessageToParetoLog("AFElasticity: findNodesAlongDirection only works on voxel data ");
        return 0;
    }
    if  ((dir < 1) || (dir >3)) return 0;
    int nElementsFound = 0,elem;
    double elemCenter[3],relativeTol;


    relativeTol = 0.5;
    if (dir == 1) {// x
        for (nx = nx; nx < h_nelx; nx += 1) {
            elemCenter[0] = h_xMin + (nx+0.5)*h_dx;
            elemCenter[1] = h_yMin + (ny+0.5)*h_dy;
            elemCenter[2] = h_zMin + (nz+0.5)*h_dz;
            elem = findElemWithCenter(elemCenter[0], elemCenter[1], elemCenter[2], relativeTol );
            if (elem >= 0) // real element
                elements[nElementsFound++] = elem;
        }

    }
    else if (dir == 2) {// y
        for (ny = ny; ny < h_nely; ny += 1) {
            elemCenter[0] = h_xMin + (nx+0.5)*h_dx;
            elemCenter[1] = h_yMin + (ny+0.5)*h_dy;
            elemCenter[2] = h_zMin + (nz+0.5)*h_dz;
            elem = findElemWithCenter(elemCenter[0], elemCenter[1], elemCenter[2], relativeTol );
            if (elem >= 0) // real element
                elements[nElementsFound++] = elem;
        }
    }
    else if (dir == 3) {// z
        for (nz = nz; nz < h_nelz; nz += 1) {
            elemCenter[0] = h_xMin + (nx+0.5)*h_dx;
            elemCenter[1] = h_yMin + (ny+0.5)*h_dy;
            elemCenter[2] = h_zMin + (nz+0.5)*h_dz;
            elem = findElemWithCenter(elemCenter[0], elemCenter[1], elemCenter[2], relativeTol );
            if (elem >= 0) // real element
                elements[nElementsFound++] = elem;
        }
    }

    return nElementsFound;
}
