bool AFElasticity::doesEveryPartHaveAnElement(void)
{
    bool partOK[MAX_PARTS];

    for (int i = 0; i < h_nParts; i++)
        partOK[i] = false;

    for (int elem = 0; elem < h_nElems; elem++)
        partOK[h_partIdOfElem[elem]] = true;

    for (int i = 0; i < h_nParts; i++)
        if (!partOK[i]) return false;

    return true;
}
