/**********************************************************************/
void AFElasticity::getDMatrix(int matlIndex,double D[36])
{
    int dStart;
    if (matlIndex >= h_nMaterials) {
        writeMessageToParetoLog("AFElasticity: matlIndex %d exceeds number of materials %d", matlIndex,h_nMaterials);
        return;
    }
    dStart = 36*matlIndex;
    for (int i =0; i < 36; i++)
        D[i] = h_DMatrices[dStart+i];
}
/**********************************************************************/
bool AFElasticity::setDMatrix(int matlIndex,double D[36])
{
    int dStart;

    isStaticResultValid = false;
    if (matlIndex >= h_nMaterials) {
        writeMessageToParetoLog("AFElasticity: Please set isotropic material first and then load matlIndex = %d",matlIndex);
        return false;
    }
    dStart = 36*matlIndex;
    for (int i =0; i < 36; i++)
        h_DMatrices[dStart+i] = D[i];

    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity:h_nMaterials = %d ... disabling nodalSpMV",h_nMaterials);
    disableNodalSpMV(); // node-based SpMV not allowed for generic D Matrix
    return true;
}
/**********************************************************************/
void AFElasticity::computeIsotropicDMatrix(int matlIndex,double E, double nu)
{
    int dStart;

    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: In computeIsotropicDMatrix; matlIndex = %d",matlIndex);

    dStart = 36*matlIndex;

    for (int i =0; i < 36; i++)
        h_DMatrices[dStart+i] = 0.0;

    h_DMatrices[dStart+0] = 1-nu; h_DMatrices[dStart+1] = nu; h_DMatrices[dStart+2] = nu;
    h_DMatrices[dStart+6] = nu; h_DMatrices[dStart+7] = 1-nu; h_DMatrices[dStart+8] = nu;
    h_DMatrices[dStart+12] = nu; h_DMatrices[dStart+13] = nu; h_DMatrices[dStart+14] = 1-nu;
    h_DMatrices[dStart+21] =(1-2*nu)/2;
    h_DMatrices[dStart+28] =(1-2*nu)/2;
    h_DMatrices[dStart+35] =(1-2*nu)/2;
    double temp = E/((1+nu)*(1-2*nu));
    for (int i =0; i < 36; i++)
        h_DMatrices[dStart+i] *= temp;

}
