/**********************************************************************/
void AFElasticity::getMaterialPropertiesOfPart(int part,double materialProperties[7],char materialName[])
{
    int materialID;

    for (int i = 0; i < 7; i++)
        materialProperties[i] = 0;
    if (part >= h_nParts){
        return;
    }
    materialID = h_partToMaterialMap[part];
    if (materialID == -1) {
        return;
    }
    materialProperties[0] = h_E[materialID];
    materialProperties[1] = h_nu[materialID];
    materialProperties[2] = h_Y[materialID];
    materialProperties[3] = h_rho[materialID];
    materialProperties[4] = h_conductivity[materialID];
    materialProperties[5] = h_alpha[materialID];
    materialProperties[6] = h_specificHeat[materialID];
    strcpy(materialName,h_materialName[materialID]);
}
/**********************************************************************/
void AFElasticity::getMaterialOfPart(int part,double *E, double *nu,double *rho, double *K, double *alpha, double *specificHeat,char materialName[])
{
    int materialID;
    if (part >= h_nParts){
        writeMessageToParetoLog("Unknown part %d ",part);
        return;
    }
    materialID = h_partToMaterialMap[part];
    if (materialID == -1) {
        writeMessageToParetoLog("Material not assigned to part %d ",part);
        return;
    }
    *E = h_E[materialID];
    *nu = h_nu[materialID];
    *rho = h_rho[materialID];
    *K = h_conductivity[materialID];
    *alpha = h_alpha[materialID];
    *specificHeat = h_specificHeat[materialID];
    strcpy(materialName,h_materialName[materialID]);
}
/**********************************************************************/
void AFElasticity::createElementMatricesTemplates(bool useBubbleFunctions)
{

    safeFree(h_KETemplates);h_KETemplates = NULL;
    safeFree(h_METemplates);h_METemplates = NULL;

    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Creating Ke and Me templates");
    computeKeOfTemplates(useBubbleFunctions);
    computeMeOfTemplates(useBubbleFunctions);
    if ((h_voxelgrid) &&  (isSpMVMethodNodeBased()))
        computeKeAndMeNodal(useBubbleFunctions);// if appropriate

#ifdef COMPILE_GPUCODE
    transferAFElasticityToGPU();
#endif
}
/**********************************************************************/
void AFElasticity::snapElementToTemplate(int elem,double templateXYZ[8][3],double allowedNodeMovement)
{
    int nodes[8],i;
    double center[3];

    //snap the nodes of an element to that of the template of the movement is small
    getElemNodes(elem,nodes);
    center[0] = 0; center[1] = 0; center[2] = 0;

    for (i = 0; i < 8;i++) {
        center[0] += h_x[nodes[i]];
        center[1] += h_y[nodes[i]];
        center[2] += h_z[nodes[i]];
    }
    for (i = 0; i < 3;i++)  center[i] /= 8.0;

    // Make the center the origin
    for (i = 0; i < 8;i++) {
        h_x[nodes[i]] = center[0]+templateXYZ[i][0];
        h_y[nodes[i]] = center[1]+templateXYZ[i][1];
        h_z[nodes[i]] = center[2]+templateXYZ[i][2];
    }
}
/**********************************************************************/
void AFElasticity::improveCongruence(double allowedNodeMovement,int nPasses)
{
    improveCongruenceSweep(allowedNodeMovement,nPasses);
}
/**********************************************************************/
void AFElasticity::improveCongruenceSnapToTemplate(double allowedNodeMovement,int nPasses)
{
    int elem;
    double  templateXYZ[8][3],allowedMovement;
    int nodes[8],i;
    double center[3];

    allowedMovement = 1e-9;
    for (i = 0; i < 8;i++) {
        templateXYZ[i][0] = 0;
        templateXYZ[i][1] = 0;
        templateXYZ[i][2] = 0;
    }
    for (elem = 0; elem < h_nElems; elem++) {
        getElemNodes(elem,nodes);
        center[0] = 0; center[1] = 0; center[2] = 0;

        for (i = 0; i < 8;i++) {
            center[0] += h_x[nodes[i]];
            center[1] += h_y[nodes[i]];
            center[2] += h_z[nodes[i]];
        }
        for (i = 0; i < 3;i++)  center[i] /= 8.0;

        for (i = 0; i < 8;i++) {
            templateXYZ[i][0] += (h_x[nodes[i]] - center[0]);
            templateXYZ[i][1] += (h_y[nodes[i]] - center[1]);
            templateXYZ[i][2] += (h_z[nodes[i]] - center[2]);
        }
        snapElementToTemplate(elem,templateXYZ,allowedMovement);
    }
}
/**********************************************************************/
void AFElasticity::improveCongruenceSweep(double allowedNodeMovement,int nPasses)
{
    // every node is made to be the average of all its connected nodes
    // walk thru all elements, for pair of connected nodes, enter the data
    int elem,nodes[8],i,node1,node2,j,startLoc,pass;
    int edgePairs[12][2] = {{0,1},{1,2},{2,3},{3,0},{0,4},{1,5},{2,6},{3,7},{4,5},{5,6},{6,7},{7,4}};
    int MAXNODES = 14;//arbitrary number
    int *nodesConnected = (int *)malloc(MAXNODES*h_nNodes*sizeof(int));

    memset(nodesConnected,-1,MAXNODES*h_nNodes*sizeof(int));
    for (elem = 0; elem < h_nElems; elem++) {
        getElemNodes(elem,nodes);
        for (i=0; i < 12;i++) {// all 12 edges of the hex
            node1 = nodes[edgePairs[i][0]];
            node2 = nodes[edgePairs[i][1]];

            startLoc = MAXNODES*node1;
            for (j = 0; j < MAXNODES; j++) {
                if (nodesConnected[startLoc+j] == node2)//connectivity exists
                    break;
                if (nodesConnected[startLoc+j] == -1){// does not exist
                    nodesConnected[startLoc+j] = node2;
                    break;
                }
            }
            startLoc = MAXNODES*node2;
            for (j = 0; j < MAXNODES; j++) {
                if (nodesConnected[startLoc+j] == node1)//connectivity exists
                    break;
                if (nodesConnected[startLoc+j] == -1){// does not exist
                    nodesConnected[startLoc+j] = node1;
                    break;
                }
            }
        }
    }
    double typicalElemSize = pow(getMeshVolume()/h_nElems,0.333);
    // writeMessageToParetoLog("typicalElemSize = %.6e ",typicalElemSize);
    // now move nodes if appropriate
    for (pass = 0; pass < nPasses; pass++) {
        // writeMessageToParetoLog("---------------------------------------");
        // writeMessageToParetoLog("Pass %d ",pass);
        for (node1 = 0; node1 < h_nNodes; node1++) {
            startLoc = MAXNODES*node1;// in the linear array
            for (j = 0; j < MAXNODES; j++) {
                node2 = nodesConnected[startLoc+j];
                if (node2 <= node1) continue;
                if (node2 == -1) break;
                if (fabs(h_x[node1]-h_x[node2]) < allowedNodeMovement*typicalElemSize){
                    // writeMessageToParetoLog("moving node %d ",node2);
                    h_x[node2] = h_x[node1];
                }
                if (fabs(h_y[node1]-h_y[node2]) < allowedNodeMovement*typicalElemSize){
                    h_y[node2] = h_y[node1];
                }
                if (fabs(h_z[node1]-h_z[node2]) < allowedNodeMovement*typicalElemSize){
                    h_z[node2] = h_z[node1];
                }
            }
        }
    }
    free(nodesConnected);
}
/**********************************************************************/
void AFElasticity::improveCongruenceAveraging(double allowedNodeMovement,int nPasses)
{
    // every node is made to be the average of all its connected nodes
    // walk thru all elements, for pair of connected nodes, enter the data
    int elem,nodes[8],i,node1,node2,j,startLoc,nNodesConnected,pass;
    int edgePairs[12][2] = {{0,1},{1,2},{2,3},{3,0},{0,4},{1,5},{2,6},{3,7},{4,5},{5,6},{6,7},{7,4}};
    double meanLoc[3];
    int MAXNODES = 14;//arbitrary number
    int *nodesConnected = (int *)malloc(MAXNODES*h_nNodes*sizeof(int));

    memset(nodesConnected,-1,MAXNODES*h_nNodes*sizeof(int));
    for (elem = 0; elem < h_nElems; elem++) {
        getElemNodes(elem,nodes);
        for (i=0; i < 12;i++) {// all 12 edges of the hex
            node1 = nodes[edgePairs[i][0]];
            node2 = nodes[edgePairs[i][1]];

            startLoc = MAXNODES*node1;
            for (j = 0; j < MAXNODES; j++) {
                if (nodesConnected[startLoc+j] == node2)//connectivity exists
                    break;
                if (nodesConnected[startLoc+j] == -1){// does not exist
                    nodesConnected[startLoc+j] = node2;
                    break;
                }
            }
            startLoc = MAXNODES*node2;
            for (j = 0; j < MAXNODES; j++) {
                if (nodesConnected[startLoc+j] == node1)//connectivity exists
                    break;
                if (nodesConnected[startLoc+j] == -1){// does not exist
                    nodesConnected[startLoc+j] = node1;
                    break;
                }
            }
        }
    }

    // now move nodes if appropriate

    for (pass = 0; pass < nPasses; pass++) {
        // writeMessageToParetoLog("---------------------------------------");
        // writeMessageToParetoLog("Pass %d ",pass);
        for (node1 = 0; node1 < h_nNodes; node1++) {
            startLoc = MAXNODES*node1;
            meanLoc[0] = 0; meanLoc[1] = 0; meanLoc[2] = 0;
            nNodesConnected = 0;
            for (j = 0; j < MAXNODES; j++) {
                node2 = nodesConnected[startLoc+j];
                if (node2 == -1) break;
                nNodesConnected++;
                meanLoc[0] += h_x[node2];
                meanLoc[1] += h_y[node2];
                meanLoc[2] += h_z[node2];
            }
            // writeMessageToParetoLog("%d: %d ",node1,nNodesConnected);
            //if (nNodesConnected != 6) continue;
            meanLoc[0] /= nNodesConnected;
            meanLoc[1] /= nNodesConnected;
            meanLoc[2] /= nNodesConnected;

            if (fabs(h_x[node1]-meanLoc[0]) < allowedNodeMovement*h_modelScale)
                h_x[node1] = meanLoc[0];

            if (fabs(h_y[node1]-meanLoc[1]) < allowedNodeMovement*h_modelScale)
                h_y[node1] = meanLoc[1];

            if (fabs(h_z[node1]-meanLoc[2]) < allowedNodeMovement*h_modelScale)
                h_z[node1] = meanLoc[2];
        }
    }
    free(nodesConnected);

}
/**********************************************************************/
double AFElasticity::getMeshElementSize(void)
{
    return MAX(h_dx,MAX(h_dy,h_dz));
}
/**********************************************************************/
double AFElasticity::getMeshVolume(void)
{
    double vol = 0;
    for (int elem = 0; elem < h_nElems; elem++)
        vol +=getElemVolume(elem);

    return vol;
}
