bool AFElasticity::getKeOfTemplateElem(int templateElem,double Ke[24][24])
{
    int k;

    if ((templateElem < 0) || (templateElem >= h_nTemplateElements))
        return false;
    k = 0;
    for (int i =0; i < 24; i++) {
        for(int j = 0; j < 24;j++) {
            Ke[i][j] = h_KETemplates[h_nTemplateElements*k + templateElem];
            k++;
        }
    }
    return true;
}
