/**********************************************************************/
void AFElasticity::computeMeOfTemplates(int useBubbleFunctions)
{
    int i,j,k,templateElem,elem,matID;
    double Me[24][24],rho;
    bool foundElem;

    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Computing Me of Templates");

    safeFree(h_METemplates);h_METemplates = NULL;

    if (h_nTemplateElements <= 0){
        writeMessageToParetoLog("AFElasticity: unable to compute computeMeOfTemplates; h_nTemplateElements = %d ",h_nTemplateElements);
        return;
    }

    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: #TemplateElements = %d ",h_nTemplateElements);
    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: #Materials = %d ",h_nMaterials);
    h_METemplates =	(double *)malloc((h_nTemplateElements)*24*24*sizeof(double));
    for (templateElem = 0; templateElem < h_nTemplateElements;templateElem++) {
        if (h_nTemplateElements == h_nElems)
            elem = templateElem;
        else{
            foundElem = false;
            for (elem = 0; elem < h_nElems; elem++) {// find an elem with that ID, BAD ALGORITHM!!!
                if (h_templateID[elem] == templateElem){
                    foundElem = true;
                    break;
                }
            }
        }
        if (!foundElem) continue; // no elem with this template
        matID = h_materialIdOfElem[elem];
        rho = h_rho[matID];
        if (h_voxelgrid) {
            if (!useBubbleFunctions)
                isotropicElementMass(h_dx,h_dy,h_dz,rho,Me);
            else {
                isotropicElementMass(h_dx,h_dy,h_dz,rho,Me);
            }
        }
        else {
            if (templateElem == 0) // print once
                writeMessageToParetoLog("AFElasticity: Computing Me not implemented for non-voxel mesh ");
        }
        k =0;
        for (i =0; i < 24; i++) {
            for( j = 0; j < 24;j++) {
                h_METemplates[k*(h_nTemplateElements) + templateElem] = (double) Me[i][j];
                k++;
            }
        }
    }
    if (h_hexmesh_verbose)
        writeMessageToParetoLog("AFElasticity: Computed Me ");
}
/**********************************************************************/
void AFElasticity::convertTo8Bits(int a,int bits[8])
{
    int i;
    for (i =0; i < 8; i++) {
        if (a%2 == 1)
            bits[i] = 1;
        else
            bits[i] = 0;
        a = a >> 1;
    }
}
