/**********************************************************************/
void AFElasticity::computeFieldGradientsAtNode(int node,double uGrad[3], double vGrad[3],double wGrad[3])
{
    int maxElem,i,j,gp,codedElem,nodeIndex,elem,nCols,nRows,row,nGradients;
    double uGradElem[3],vGradElem[3],wGradElem[3],gaussPtXYZ[3];
    double x,y,z;
    MatrixXd A,B,Coeff;
    double a = 1.0/sqrt(3.0);
    double xi[8] = {-a,a,a,-a,-a,a,a,-a};
    double eta[8] = {-a,-a,a,a,-a,-a,a,a};
    double mu[8] = {-a,-a,-a,-a,a,a,a,a};


    for (j = 0; j < 3;j++) {
        uGrad[j] = 0;
        vGrad[j] = 0;
        wGrad[j] = 0;
    }
    // find the neighboring elements and index
    maxElem = h_nNeighboringElems[node];// how many elements connected to node
    if (maxElem == 0) return;

    // how about using neighborsof neighbors???

    // We must extrapolate from element Gauss point to node; we will ne
    // writeMessageToParetoLog("%d ",maxElem);ed to invert a matrix
    // Assume that the gradient can be expressed linearly
    nCols = 4;// Linear
    nRows = 8*maxElem;
    nGradients = 9;// (ux,vx,wx,uy,...)

    A.resize(nRows,nCols);
    B.resize(nRows,nGradients);
    row = 0;
    for (j =0; j < maxElem; j++) {//
        codedElem = h_neighborElems[(h_nNodes)*j + node];// process elem-j neighbor
        nodeIndex = codedElem/MAXELEMS;//ranges from 0 to 7, position of this node within this elem
        elem = codedElem - nodeIndex*MAXELEMS;
        for (gp = 0; gp < 8; gp++) {
            computePointInElem(elem,gp,gaussPtXYZ);
            computeFieldGradientsInElem(elem,gp,uGradElem,vGradElem,wGradElem);
            A(row,0) = 1.0;
            A(row,1) = gaussPtXYZ[0];
            A(row,2) = gaussPtXYZ[1];
            A(row,3) = gaussPtXYZ[2];
            for (i =0; i < 3; i++){
                B(row,3*i) = uGradElem[i];
                B(row,3*i+1) = vGradElem[i];
                B(row,3*i+2) = wGradElem[i];
            }
            // writeMessageToParetoLog("e: %f %f %f ",gaussPtXYZ[0],gaussPtXYZ[1],gaussPtXYZ[2]);
            // writeMessageToParetoLog("x: %f %f %f \n",vGradElem[0],vGradElem[1],vGradElem[2]);
            row++;
        }
    }
    Coeff.resize(nCols,nGradients);
    JacobiSVD<MatrixXd> svd(A, (ComputeThinU | ComputeThinV));
    Coeff = svd.solve(B);
    x = h_x[node];
    y = h_y[node];
    z = h_z[node];
    for (i =0; i < 3; i++){
        // writeMessageToParetoLog("(%f,%f,%f)\n",Coeff(1,3*i+0),Coeff(2,3*i+0),Coeff(3,3*i+0));
        uGrad[i] = Coeff(0,3*i+0) + x*Coeff(1,3*i+0) + y*Coeff(2,3*i+0) + z*Coeff(3,3*i+0);
        vGrad[i] = Coeff(0,3*i+1) + x*Coeff(1,3*i+1) + y*Coeff(2,3*i+1) + z*Coeff(3,3*i+1);
        wGrad[i] = Coeff(0,3*i+2) + x*Coeff(1,3*i+2) + y*Coeff(2,3*i+2) + z*Coeff(3,3*i+2);
    }
}
/**********************************************************************/
void AFElasticity::extrapolateFieldAtPoint(double pt[3],int closestElem, double uvw[3])
{
    // Use the field at the closest element, and its neighbors to estimate field at point
    int i,j,k,nCols,nRows,row,nUnknownFields;
    int nodes[8],nearbyNodes[250],nNearbyNodes,node,primaryNode;
    bool found;
    double x,y,z;
    MatrixXd A,B,C;

    for (j = 0; j < 3;j++)
        uvw[j] = 0;

    getElemNodes(closestElem,nodes);
    for (i = 0; i < 8; i++)
        nearbyNodes[i] = nodes[i];

    nNearbyNodes = 8;
    for (k =0; k < 8; k++) {
        primaryNode = nodes[k];
        for (j =0; j < 27; j++) {
            node = h_neighborNodes[j*h_nNodes + primaryNode];
            if ((node < 0) || (node >= h_nNodes)) continue;
            found = false;
            for (i = 0; i < nNearbyNodes; i++) {
                if (nearbyNodes[i] == node) {
                    found = true;
                    break;
                }
            }
            if (!found){//  no duplicate, add to list
                nearbyNodes[nNearbyNodes] = node;
                nNearbyNodes++;
            }
        }
    }

    // writeMessageToParetoLog("nNearbyNodes = %d ",nNearbyNodes);
    // Assume that the field can be expressed via a quadratic
    nCols = 10;// Quadratic
    nRows = nNearbyNodes;
    nUnknownFields = 3;// (u,v,w)

    A.resize(nRows,nCols);
    B.resize(nRows,nUnknownFields);
    row = 0;


    //for (i = 0; i < nNearbyNodes; i++) writeMessageToParetoLog("%d: %d ",i,nearbyNodes[i]);getchar();

    for (i = 0; i < nRows; i++) {
        node = nearbyNodes[i];
        x = h_x[node];
        y = h_y[node];
        z = h_z[node];

        A(row,0) = 1.0;
        A(row,1) = x;
        A(row,2) = y;
        A(row,3) = z;
        A(row,4) = x*x;
        A(row,5) = y*y;
        A(row,6) = z*z;
        A(row,7) = x*y;
        A(row,8) = x*z;
        A(row,9) = y*z;

        B(row,0) = h_sol[3*node];
        B(row,1) = h_sol[3*node+1];
        B(row,2) = h_sol[3*node+2];

        row++;
    }

    C.resize(nCols,nUnknownFields);
    JacobiSVD<MatrixXd> svd(A, (ComputeThinU | ComputeThinV));
    C = svd.solve(B);
    x = pt[0];
    y = pt[1];
    z = pt[2];
    /* writeMessageToParetoLog("------");
     writeMessageToParetoLog("%f %f %f %f %f %f %f %f %f %f\n",C(0,0),C(1,0),C(2,0),C(3,0),C(4,0),C(5,0),C(6,0),C(7,0),C(8,0),C(9,0));
     writeMessageToParetoLog("%f %f %f %f \n",C(0,1),C(1,1),C(2,1),C(3,1));
     writeMessageToParetoLog("%f %f %f %f \n",C(0,2),C(1,2),C(2,2),C(3,2));*/
    for (i = 0; i < 3;i++)
        uvw[i] = C(0,i)+x*C(1,i)+y*C(2,i)+z*C(3,i)+x*x*C(4,i)+y*y*C(5,i)+z*z*C(6,i)+x*y*C(7,i)+x*z*C(8,i)+y*z*C(9,i);

    //for (i = 0; i < 3;i++)
    //	uvw[i] = C(0,i)+x*C(1,i)+y*C(2,i)+z*C(3,i);
}
/**********************************************************************/
void AFElasticity::computeFieldGradientsAtNodeWithBubble(int node,double uGrad[3], double vGrad[3],double wGrad[3])
{
    int maxElem,i,j,codedElem,nodeIndex,elem,nCols,nRows;
    double uGradElem[3],vGradElem[3],wGradElem[3];
    double a = 1.0/sqrt(3.0);
    double xi[8] = {-a,-a,a,a,-a,-a,a,a};
    double eta[8] = {-a,a,-a,a,-a,a,-a,a};
    double mu[8] = {-a,-a,-a,-a,a,a,a,a};
    MatrixXd Au,Av,Aw;// from Eigen package
    VectorXd bu,bv,bw;

    for (j = 0; j < 3;j++) {
        uGrad[j] = 0;
        vGrad[j] = 0;
        wGrad[j] = 0;
    }
    // find the neighboring elements and index
    maxElem = h_nNeighboringElems[node];// how many elements connected to node
    if (maxElem == 0) return;
    // We must extrapolate from element Gauss point to node; we will need to invert a matrix
    // Assume that the gradient can be expressed either as a linear or quadratic function depending on
    // the number of elements attached
    if (maxElem == 1){
        nCols = 4;// Linear
        nRows = 8;
    }
    else{
        nCols = 10;// quadratic
        nRows = 8*maxElem;
    }
    /*
    Au.resize(nRows,nCols);
    Av.resize(nRows,nCols);
    Aw.resize(nRows,nCols);

    bu.resize(nRows);
    bv.resize(nRows);
    bw.resize(nRows);
    */

    for (j =0; j < maxElem; j++) {//
        codedElem = h_neighborElems[(h_nNodes)*j + node];// process elem-j neighbor
        nodeIndex = codedElem/MAXELEMS;//ranges from 0 to 7, position of this node within this elem
        elem = codedElem - nodeIndex*MAXELEMS;
        //for (gp = 0; gp < 8; gp++) {
        //computeFieldGradientsInElemWithBubble(elem,xi[nodeIndex],eta[nodeIndex],mu[nodeIndex], uGradElem,vGradElem,wGradElem );
        computeFieldGradientsInElemWithBubble(elem,nodeIndex,uGradElem,vGradElem,wGradElem );
        writeMessageToParetoLog("Elem: %f %f %f ",uGradElem[0],uGradElem[1],uGradElem[2]);
        for (i = 0; i < 3;i++) {
            uGrad[i] += uGradElem[i];
            vGrad[i] += vGradElem[i];
            wGrad[i] += wGradElem[i];
        }
        //}
    }
    for (j = 0; j < 3;j++) {
        uGrad[j] /=maxElem;
        vGrad[j] /=maxElem;
        wGrad[j] /=maxElem;
    }
}
/**********************************************************************/
void AFElasticity::computeFieldGradientsInElemWithBubble(int elem, int GP, double uGrad[3], double vGrad[3],double wGrad[3])
{
    int i;
    double u[8],v[8],w[8],Lu[3],Lv[3],Lw[3],xi,eta,mu;
    double gradNxi[8],gradNeta[8],gradNmu[8],gradBxi[3],gradBeta[3],gradBmu[3],T1,T2,T3;

    double a = 1.0/sqrt(3.0);
    double xiGP[8] = {-a,-a,a,a,-a,-a,a,a};
    double etaGP[8] = {-a,a,-a,a,-a,a,-a,a};
    double muGP[8] = {-a,-a,-a,-a,a,a,a,a};


    xi = xiGP[GP];
    eta = etaGP[GP];
    mu = muGP[GP];

    TCLMatrix J(3,3,0.0);
    getElemNodeDeformation(elem,u,v,w);
    bubbleVariables(u,v,w,Lu,Lv,Lw);// get the bubble variables

    for (i = 0; i < 3; i++) {
        uGrad[i] =0;
        vGrad[i] =0;
        wGrad[i] =0;
    }

    // if the mesh is of uniform grid, can reduce computation

    if (h_voxelgrid) {
        computeGrad_H8(xi,eta,mu,gradNxi,gradNeta,gradNmu);
        computeGrad_Bubble(xi,eta,mu,gradBxi,gradBeta,gradBmu);
        J[0][0] = 2./h_dx;//Jinv
        J[1][1] = 2./h_dy;
        J[2][2] = 2./h_dz;
        for (i = 0; i < 8; i++) {// contribution from all 8 nodes
            T1 = J[0][0]*gradNxi[i];
            T2 = J[1][1]*gradNeta[i] ;
            T3 = J[2][2]*gradNmu[i];
            uGrad[0] += T1*u[i];// ux
            uGrad[1] += T2*u[i];// uy
            uGrad[2] += T3*u[i];// uz

            vGrad[0] += T1*v[i];// vx
            vGrad[1] += T2*v[i];// vy
            vGrad[2] += T3*v[i];// vz

            wGrad[0] += T1*w[i];// wx
            wGrad[1] += T2*w[i];// wy
            wGrad[2] += T3*w[i];// wz

        }
        for (i = 0; i < 3; i++) {// contribution from all 3 bubble variables
            T1 = J[0][0]*gradBxi[i];
            T2 = J[1][1]*gradBeta[i] ;
            T3 = J[2][2]*gradBmu[i];

            uGrad[0] += T1*Lu[i];// ux
            uGrad[1] += T2*Lu[i];// uy
            uGrad[2] += T3*Lu[i];// uz

            vGrad[0] += T1*Lv[i];// vx
            vGrad[1] += T2*Lv[i];// vy
            vGrad[2] += T3*Lv[i];// vz

            wGrad[0] += T1*Lw[i];// wx
            wGrad[1] += T2*Lw[i];// wy
            wGrad[2] += T3*Lw[i];// wz
        }
    }
    else
        writeMessageToParetoLog("AFElasticity: Error ... computeFieldGradientsInElemWithBubble only works for voxel mesh");
}
/**********************************************************************/
void AFElasticity::computeFieldGradientsInElem(int elem, int GP, double uGrad[3], double vGrad[3],double wGrad[3])
// At a specific gauss point
{
    int i;
    double u[8],v[8],w[8],J00,J11,J22;
    double T1,T2,T3;

    getElemNodeDeformation(elem,u,v,w);
    for (i = 0; i < 3; i++) {
        uGrad[i] =0;
        vGrad[i] =0;
        wGrad[i] =0;
    }
    // if the mesh is of uniform grid, can reduce computation
    if (h_voxelgrid) {
        J00 = 2./h_dx;//Jinv
        J11 = 2./h_dy;
        J22 = 2./h_dz;
        for (i = 0; i < 8; i++) {// contribution from all 8 nodes
            T1 = J00*h_gradNxi[GP][i];
            T2 = J11*h_gradNeta[GP][i] ;
            T3 = J22*h_gradNmu[GP][i];
            uGrad[0] += T1*u[i];// ux
            uGrad[1] += T2*u[i];// uy
            uGrad[2] += T3*u[i];// uz

            vGrad[0] += T1*v[i];// vx
            vGrad[1] += T2*v[i];// vy
            vGrad[2] += T3*v[i];// vz

            wGrad[0] += T1*w[i];// wx
            wGrad[1] += T2*w[i];// wy
            wGrad[2] += T3*w[i];// wz
        }
    }
    else
        writeMessageToParetoLog("AFElasticity: Error ... computeFieldGradientsInElem only works for voxel mesh");
}
/**********************************************************************/
void AFElasticity::computeFieldHessianInElem(int elem, double uHessian[3][3], double vHessian[3][3],double wHessian[3][3])
{
    int i,j,nodes[8];
    double uGrad[3],vGrad[3],wGrad[3];
    double T1,T2,T3;
    double J00,J11,J22,gradNxi0[8],gradNeta0[8],gradNmu0[8];

    for (i = 0; i < 3; i++) {
        for (j = 0; j < 3; j++) {
            uHessian[i][j] =0;
            vHessian[i][j] =0;
            wHessian[i][j] =0;
        }
    }
    if (h_voxelgrid) {
        computeGrad_H8(0,0,0, gradNxi0, gradNeta0, gradNmu0);
        // for each node find the gradient;
        getElemNodes(elem,nodes);
        J00 = 2./h_dx;//Jinv
        J11 = 2./h_dy;
        J22 = 2./h_dz;
        for (i = 0; i < 8; i++) {// contribution from all 8 nodes
            computeFieldGradientsAtNode(nodes[i],uGrad,vGrad,wGrad);
            T1 = J00*gradNxi0[i];
            T2 = J11*gradNeta0[i] ;
            T3 = J22*gradNmu0[i];
            uHessian[0][0] += T1*uGrad[0];// uxx
            uHessian[0][1] += T2*uGrad[0];// uxy
            uHessian[0][2] += T3*uGrad[0];// uxz
            uHessian[1][1] += T2*uGrad[1];// uyy
            uHessian[1][2] += T3*uGrad[1];// uyz
            uHessian[2][2] += T3*uGrad[2];// uzz

            vHessian[0][0] += T1*vGrad[0];// vxx
            vHessian[0][1] += T2*vGrad[0];// vxy
            vHessian[0][2] += T3*vGrad[0];// vxz
            vHessian[1][1] += T2*vGrad[1];// vyy
            vHessian[1][2] += T3*vGrad[1];// vyz
            vHessian[2][2] += T3*vGrad[2];// vzz

            wHessian[0][0] += T1*wGrad[0];// uxx
            wHessian[0][1] += T2*wGrad[0];// uxy
            wHessian[0][2] += T3*wGrad[0];// uxz
            wHessian[1][1] += T2*wGrad[1];// uyy
            wHessian[1][2] += T3*wGrad[1];// uyz
            wHessian[2][2] += T3*wGrad[2];// uzz
        }
        uHessian[1][0] = uHessian[0][1];
        uHessian[2][0] = uHessian[0][2];
        uHessian[2][1] = uHessian[1][2];

        vHessian[1][0] = vHessian[0][1];
        vHessian[2][0] = vHessian[0][2];
        vHessian[2][1] = vHessian[1][2];

        wHessian[1][0] = wHessian[0][1];
        wHessian[2][0] = wHessian[0][2];
        wHessian[2][1] = wHessian[1][2];
    }
    else
        writeMessageToParetoLog("AFElasticity: Error ... computeFieldHessianInElem only works for voxel mesh");
}

/**********************************************************************/
void AFElasticity::computeElemForces(int elem, double elemForce[24])
{
    int i,j,k;
    double sol[24];


    if (h_KETemplates == NULL) {
        writeMessageToParetoLog("Ke Templates not initialized");
        return;
    }
    getElemSolution(elem,sol);

    k = 0;
    for (i =0; i < 24; i++) {
        elemForce[i] = 0;
        for( j = 0; j < 24;j++) {
            elemForce[i] += h_KETemplates[k]*sol[j];
            k++;
        }
    }
}
/**********************************************************************/
void AFElasticity::getBMatrixVoxelAtCenter(double B[6][24])
{
    int i,j;
    double gradNxi[8],gradNeta[8],gradNmu[8],T1,T2,T3;
    TCLMatrix J(3,3,0.0);

    computeGrad_H8(0,0,0,gradNxi,gradNeta,gradNmu);
    J[0][0] = 2./h_dx;//Jinv
    J[1][1] = 2./h_dy;
    J[2][2] = 2./h_dz;
    for (i = 0; i < 6; i++)
        for (j = 0; j < 24; j++)
            B[i][j] = 0.0;

    for (i = 0; i < 8; i++) {// contribution from all 8 nodes
        T1 = J[0][0]*gradNxi[i];
        T2 = J[1][1]*gradNeta[i] ;
        T3 = J[2][2]*gradNmu[i];
        B[0][3*i] = T1;
        B[1][3*i+1] = T2;
        B[2][3*i+2] = T3;

        B[3][3*i] = T2;
        B[3][3*i+1] = T1;

        B[4][3*i] = T3;
        B[4][3*i+2] = T1;

        B[5][3*i+1] = T3;
        B[5][3*i+2] = T2;
    }
}
/**********************************************************************/
void AFElasticity::computeStrain(int elem, double xi, double eta, double mu, double strains[6])
{
    int i;
    double x[8],y[8],z[8],u[8],v[8],w[8];
    double gradNxi[8],gradNeta[8],gradNmu[8],T1,T2,T3;
    TCLMatrix J(3,3,0.0);
    getElemNodeDeformation(elem,u,v,w);

    if (strains == NULL)
        for (i = 0; i < 6; i++)
            h_elemstrains[i][elem] = 0;
    else
        for (i = 0; i < 6; i++)
            strains[i] = 0;

    // if the mesh is of uniform grid, can reduce computation
    computeGrad_H8(xi,eta,mu,gradNxi,gradNeta,gradNmu);
    if (h_voxelgrid) {
        J[0][0] = 2./h_dx;//Jinv
        J[1][1] = 2./h_dy;
        J[2][2] = 2./h_dz;
        for (i = 0; i < 8; i++) {// contribution from all 8 nodes
            T1 = J[0][0]*gradNxi[i];
            T2 = J[1][1]*gradNeta[i] ;
            T3 = J[2][2]*gradNmu[i];
            if (strains == NULL) {
                h_elemstrains[0][elem] += T1*u[i];// ux
                h_elemstrains[1][elem] += T2*v[i];// vy
                h_elemstrains[2][elem] += T3*w[i];// wz
                h_elemstrains[3][elem] += (T2*u[i] + T1*v[i]);// uy + vx
                h_elemstrains[4][elem] += (T3*u[i] + T1*w[i]);// uz + wx
                h_elemstrains[5][elem] += (T3*v[i] + T2*w[i]);// vz + wy
            }
            else {
                strains[0] += T1*u[i];// ux
                strains[1] += T2*v[i];// vy
                strains[2] += T3*w[i];// wz
                strains[3] += (T2*u[i] + T1*v[i]);// uy + vx
                strains[4] += (T3*u[i] + T1*w[i]);// uz + wx
                strains[5] += (T3*v[i] + T2*w[i]);// vz + wy
            }
        }
    }
    else {

        J = 0;
        getElemNodeLocation(elem,x,y,z);
        for (i =0; i < 8; i++) {
            J[0][0] += gradNxi[i]*x[i];
            J[0][1] += gradNxi[i]*y[i];
            J[0][2] += gradNxi[i]*z[i];

            J[1][0] += gradNeta[i]*x[i];
            J[1][1] += gradNeta[i]*y[i];
            J[1][2] += gradNeta[i]*z[i];

            J[2][0] += gradNmu[i]*x[i];
            J[2][1] += gradNmu[i]*y[i];
            J[2][2] += gradNmu[i]*z[i];
        }
        J.inv();
        for (i = 0; i < 8; i++) {// contribution from all 8 nodes
            T1 = J[0][0]*gradNxi[i] + J[0][1]*gradNeta[i] + J[0][2]*gradNmu[i];
            T2 = J[1][0]*gradNxi[i] + J[1][1]*gradNeta[i] + J[1][2]*gradNmu[i];
            T3 = J[2][0]*gradNxi[i] + J[2][1]*gradNeta[i] + J[2][2]*gradNmu[i];
            if (strains == NULL) {
                h_elemstrains[0][elem] += T1*u[i];// ux
                h_elemstrains[1][elem] += T2*v[i];// vy
                h_elemstrains[2][elem] += T3*w[i];// wz
                h_elemstrains[3][elem] += (T2*u[i] + T1*v[i]);// uy + vx
                h_elemstrains[4][elem] += (T3*u[i] + T1*w[i]);// uz + wx
                h_elemstrains[5][elem] += (T3*v[i] + T2*w[i]);// vz + wy
            }
            else {
                strains[0] += T1*u[i];// ux
                strains[1] += T2*v[i];// vy
                strains[2] += T3*w[i];// wz
                strains[3] += (T2*u[i] + T1*v[i]);// uy + vx
                strains[4] += (T3*u[i] + T1*w[i]);// uz + wx
                strains[5] += (T3*v[i] + T2*w[i]);// vz + wy
            }
        }
    }
}
/**********************************************************************/
void AFElasticity::assemblePeriodicForce(int fVector)
{
    memset(h_f,0,3*h_nNodes*sizeof(double));
    int elem,node,nodes[8];
    double densityOfElem,Fe[24][6];
    double a = h_dx;
    double x[8] = {0,a,a,0,0,a,a,0};
    double y[8] = {0,0,a,a,0,0,a,a};
    double z[8] = {0,0,0,0,a,a,a,a};

    displacementFE(x,y,z,h_DMatrices,Fe);

    for(elem = 0;elem<h_nElems;elem++){
        getElemNodes(elem,nodes);
        densityOfElem = h_pseudoDensity[elem];
        for(node = 0;node<8;node++){
            h_f[3*nodes[node]]   += pow(densityOfElem,h_Eexponent)*Fe[node][fVector];
            h_f[3*nodes[node]+1]   += pow(densityOfElem,h_Eexponent)*Fe[node+8][fVector];
            h_f[3*nodes[node]+2]   += pow(densityOfElem,h_Eexponent)*Fe[node+16][fVector];
        }
    }
    enforceDirichlet0(h_f);
}
/**********************************************************************/
void AFElasticity::computeEquivalentD(double x[8],double y[8],double z[8],double *dmatrix,double *disp,double *equivDmatrix,double *gradDelem)
{
    int gp,i,j,k,elem,nodes[8];
    double a = 1.0/sqrt(3.0);
    double boundingBox[3][2];
    double xi[8] = {-a,-a,a,a,-a,-a,a,a};
    double eta[8] = {-a,a,-a,a,-a,a,-a,a};
    double mu[8] = {-a,-a,-a,-a,a,a,a,a};
    double gradNxi[8],gradNeta[8],gradNmu[8],dJ,T1,T2,T3;

    TCLMatrix J(3,3,0.0);
    TCLMatrix B(6,24,0.0);
    TCLMatrix Dequiv(6,6,0.0);
    TCLMatrix gradD(6,6,0.0);
    TCLMatrix D(6,6,0.0);
    TCLMatrix I(6,6,0.0);
    TCLMatrix Ue(24,6,0.0);

    getBoundingBox(boundingBox);
    double boundingBoxVol = (boundingBox[0][1]-boundingBox[0][0])*(boundingBox[1][1]-boundingBox[1][0])*(boundingBox[2][1]-boundingBox[2][0]);

    k = 0;
    for (i =0; i < 6; i++){
        I[i][i] = 1.0;
        for (j =0; j <6; j++)
            D[i][j] = dmatrix[k++];
    }
  // #pragma omp parallel for private(gp,xi,eta,mu,gradNxi,gradNeta,gradNmu,T1,T2,T3,J,B,Dequiv,gradD,Ue,dJ,nodes,elem,i,j)
    for (gp = 0; gp < 8; gp++) {
        computeGrad_H8(xi[gp],eta[gp],mu[gp],gradNxi,gradNeta,gradNmu);

        J = 0;
        for (i =0; i < 8; i++) {
            J[0][0] += gradNxi[i]*x[i];
            J[0][1] += gradNxi[i]*y[i];
            J[0][2] += gradNxi[i]*z[i];

            J[1][0] += gradNeta[i]*x[i];
            J[1][1] += gradNeta[i]*y[i];
            J[1][2] += gradNeta[i]*z[i];

            J[2][0] += gradNmu[i]*x[i];
            J[2][1] += gradNmu[i]*y[i];
            J[2][2] += gradNmu[i]*z[i];
        }
        dJ = J.det();
        J.inv();
        for (i = 0; i < 8; i++) {
            T1 = J[0][0]*gradNxi[i] + J[0][1]*gradNeta[i] + J[0][2]*gradNmu[i];
            T2 = J[1][0]*gradNxi[i] + J[1][1]*gradNeta[i] + J[1][2]*gradNmu[i];
            T3 = J[2][0]*gradNxi[i] + J[2][1]*gradNeta[i] + J[2][2]*gradNmu[i];
            B[0][i] = T1;
            B[1][8+i] = T2;
            B[2][16+i] = T3;
            B[3][i] = T2;
            B[3][8+i] = T1;
            B[4][i] = T3;
            B[4][16+i] = T1;
            B[5][8+i] = T3;
            B[5][16+i] = T2;
        }
        for(elem = 0;elem<h_nElems;elem++){
            getElemNodes(elem,nodes);
            for(j = 0;j<6;j++){
                for (i = 0; i < 8; i++) {
                    Ue[i][j] = disp[3*nodes[i]+j*3*h_nNodes];
                    Ue[i+8][j] = disp[3*nodes[i]+1+j*3*h_nNodes];
                    Ue[i+16][j] = disp[3*nodes[i]+2+j*3*h_nNodes];
                }
            }

            Dequiv += pow(h_pseudoDensity[elem],h_Eexponent)*dJ*(~(I-B*Ue))*D*(I-B*Ue);
            gradD = h_Eexponent*pow(h_pseudoDensity[elem],h_Eexponent-1)*dJ*(~(I-B*Ue))*D*(I-B*Ue);
            for (i=0; i <6; i++){
                for (j=0; j <6; j++){
                    #pragma omp critical
                    gradDelem[i*6+j+elem*36] += gradD[i][j]/boundingBoxVol;
                }
            }
        }
    }

    Dequiv = Dequiv/boundingBoxVol;
    #pragma omp parallel for private(i,j)
    for (i=0; i <6; i++)
        for (j=0; j <6; j++)
            equivDmatrix[i*6+j] = Dequiv[i][j];

}
/**********************************************************************/
void AFElasticity::displacementFE(double x[8],double y[8],double z[8],double *dmatrix,double Fe[24][6])
{
    int gp,i,j,k;
    double a = 1.0/sqrt(3.0);
    double xi[8] = {-a,-a,a,a,-a,-a,a,a};
    double eta[8] = {-a,a,-a,a,-a,a,-a,a};
    double mu[8] = {-a,-a,-a,-a,a,a,a,a};
    double gradNxi[8],gradNeta[8],gradNmu[8],dJ,T1,T2,T3;

    TCLMatrix J(3,3,0.0);
    TCLMatrix B(6,24,0.0);
    TCLMatrix BT(24,6,0.0);
    TCLMatrix FElement(24,6,0.0);
    TCLMatrix D(6,6,0.0);

    k = 0;
    for (i =0; i < 6; i++)
        for (j =0; j <6; j++)
            D[i][j] = dmatrix[k++];
    for (gp = 0; gp < 8; gp++) {
        computeGrad_H8(xi[gp],eta[gp],mu[gp],gradNxi,gradNeta,gradNmu);

        J = 0;
        for (i =0; i < 8; i++) {
            J[0][0] += gradNxi[i]*x[i];
            J[0][1] += gradNxi[i]*y[i];
            J[0][2] += gradNxi[i]*z[i];

            J[1][0] += gradNeta[i]*x[i];
            J[1][1] += gradNeta[i]*y[i];
            J[1][2] += gradNeta[i]*z[i];

            J[2][0] += gradNmu[i]*x[i];
            J[2][1] += gradNmu[i]*y[i];
            J[2][2] += gradNmu[i]*z[i];
        }
        dJ = J.det();
        J.inv();
        for (i = 0; i < 8; i++) {
            T1 = J[0][0]*gradNxi[i] + J[0][1]*gradNeta[i] + J[0][2]*gradNmu[i];
            T2 = J[1][0]*gradNxi[i] + J[1][1]*gradNeta[i] + J[1][2]*gradNmu[i];
            T3 = J[2][0]*gradNxi[i] + J[2][1]*gradNeta[i] + J[2][2]*gradNmu[i];
            B[0][i] = T1;
            B[1][8+i] = T2;
            B[2][16+i] = T3;
            B[3][i] = T2;
            B[3][8+i] = T1;
            B[4][i] = T3;
            B[4][16+i] = T1;
            B[5][8+i] = T3;
            B[5][16+i] = T2;
        }
        BT = ~B;
        FElement += dJ*BT*D;
    }

    for (i=0; i <24; i++)
        for (j=0; j <6; j++)
            Fe[i][j] = FElement[i][j];
}

/**********************************************************************/
void AFElasticity::displacementKE(double x[8],double y[8],double z[8],double *dmatrix,double Ke[24][24])
{
    int gp,i,j,k;
    double a = 1.0/sqrt(3.0);
    double xi[8] = {-a,-a,a,a,-a,-a,a,a};
    double eta[8] = {-a,a,-a,a,-a,a,-a,a};
    double mu[8] = {-a,-a,-a,-a,a,a,a,a};
    double gradNxi[8],gradNeta[8],gradNmu[8],dJ,T1,T2,T3;

    TCLMatrix J(3,3,0.0);
    TCLMatrix B(6,24,0.0);
    TCLMatrix BT(24,6,0.0);
    TCLMatrix KElement(24,24,0.0);
    TCLMatrix D(6,6,0.0);

    k = 0;
    for (i =0; i < 6; i++)
        for (j =0; j <6; j++)
            D[i][j] = dmatrix[k++];
    for (gp = 0; gp < 8; gp++) {
        computeGrad_H8(xi[gp],eta[gp],mu[gp],gradNxi,gradNeta,gradNmu);

        J = 0;
        for (i =0; i < 8; i++) {
            J[0][0] += gradNxi[i]*x[i];
            J[0][1] += gradNxi[i]*y[i];
            J[0][2] += gradNxi[i]*z[i];

            J[1][0] += gradNeta[i]*x[i];
            J[1][1] += gradNeta[i]*y[i];
            J[1][2] += gradNeta[i]*z[i];

            J[2][0] += gradNmu[i]*x[i];
            J[2][1] += gradNmu[i]*y[i];
            J[2][2] += gradNmu[i]*z[i];
        }
        dJ = J.det();
        J.inv();
        for (i = 0; i < 8; i++) {
            T1 = J[0][0]*gradNxi[i] + J[0][1]*gradNeta[i] + J[0][2]*gradNmu[i];
            T2 = J[1][0]*gradNxi[i] + J[1][1]*gradNeta[i] + J[1][2]*gradNmu[i];
            T3 = J[2][0]*gradNxi[i] + J[2][1]*gradNeta[i] + J[2][2]*gradNmu[i];
            B[0][i] = T1;
            B[1][8+i] = T2;
            B[2][16+i] = T3;
            B[3][i] = T2;
            B[3][8+i] = T1;
            B[4][i] = T3;
            B[4][16+i] = T1;
            B[5][8+i] = T3;
            B[5][16+i] = T2;
        }
        BT = ~B;
        KElement += dJ*BT*D*B;
    }
    int order[24] = {0,8,16,1,9,17,2,10,18,3,11,19,4,12,20,5,13,21,6,14,22,7,15,23};

    for (i=0; i <24; i++)
        for (j=0; j <24; j++)
            Ke[i][j] = KElement[order[i]][order[j]];
}
/**********************************************************************/
void AFElasticity::wilsonKE(double x[8],double y[8],double z[8],double *dmatrix,double Ke[24][24])
// Use of bubble functions to improve performance
{
    int gp,i,j,k;
    double a = 1.0/sqrt(3.0);
    double xi[8] = {-a,-a,a,a,-a,-a,a,a};
    double eta[8] = {-a,a,-a,a,-a,a,-a,a};
    double mu[8] = {-a,-a,-a,-a,a,a,a,a};
    double gradNxi[8],gradNeta[8],gradNmu[8],dJ,T1,T2,T3,gradNLxi[3],gradNLeta[3],gradNLmu[3];

    TCLMatrix J(3,3,0.0);
    TCLMatrix B(6,24,0.0);
    TCLMatrix BT(24,6,0.0);

    TCLMatrix BL(6,9,0.0);
    TCLMatrix BLT(9,6,0.0);

    TCLMatrix KQQ(24,24,0.0);
    TCLMatrix KLL(9,9,0.0);
    TCLMatrix KLQ(9,24,0.0);
    TCLMatrix KQL(24,9,0.0);
    TCLMatrix KElement(24,24,0.0);
    TCLMatrix D(6,6,0.0);

    k = 0;
    for (i =0; i < 3; i++){
        gradNLxi[i] =0;
        gradNLeta[i] =0;
        gradNLmu[i] =0;

    }
    for (i =0; i < 6; i++)
        for (j =0; j <6; j++)
            D[i][j] = dmatrix[k++];
    for (gp = 0; gp < 8; gp++) {
        computeGrad_H8(xi[gp],eta[gp],mu[gp],gradNxi,gradNeta,gradNmu);

        J = 0;
        for (i =0; i < 8; i++) {
            J[0][0] += gradNxi[i]*x[i];
            J[0][1] += gradNxi[i]*y[i];
            J[0][2] += gradNxi[i]*z[i];

            J[1][0] += gradNeta[i]*x[i];
            J[1][1] += gradNeta[i]*y[i];
            J[1][2] += gradNeta[i]*z[i];

            J[2][0] += gradNmu[i]*x[i];
            J[2][1] += gradNmu[i]*y[i];
            J[2][2] += gradNmu[i]*z[i];
        }
        dJ = J.det();
        J.inv();
        for (i = 0; i < 8; i++) {
            T1 = J[0][0]*gradNxi[i] + J[0][1]*gradNeta[i] + J[0][2]*gradNmu[i];
            T2 = J[1][0]*gradNxi[i] + J[1][1]*gradNeta[i] + J[1][2]*gradNmu[i];
            T3 = J[2][0]*gradNxi[i] + J[2][1]*gradNeta[i] + J[2][2]*gradNmu[i];
            B[0][i] = T1;
            B[1][8+i] = T2;
            B[2][16+i] = T3;
            B[3][i] = T2;
            B[3][8+i] = T1;
            B[4][i] = T3;
            B[4][16+i] = T1;
            B[5][8+i] = T3;
            B[5][16+i] = T2;
        }
        BT = ~B;
        // Bubble functions
        computeGrad_Bubble(xi[gp],eta[gp],mu[gp],gradNLxi,gradNLeta,gradNLmu);

        for (i = 0; i < 3; i++) {
            T1 = J[0][0]*gradNLxi[i] + J[0][1]*gradNLeta[i] + J[0][2]*gradNLmu[i];// NLx(i)
            T2 = J[1][0]*gradNLxi[i] + J[1][1]*gradNLeta[i] + J[1][2]*gradNLmu[i];// NLy(i)
            T3 = J[2][0]*gradNLxi[i] + J[2][1]*gradNLeta[i] + J[2][2]*gradNLmu[i];// NLz(i)
            BL[0][i] = T1;
            BL[1][3+i] = T2;
            BL[2][6+i] = T3;
            BL[3][i] = T2;
            BL[3][3+i] = T1;
            BL[4][i] = T3;
            BL[4][6+i] = T1;
            BL[5][3+i] = T3;
            BL[5][6+i] = T2;
        }
        BLT = ~BL;
        KQQ += dJ*BT*D*B;
        KLL += dJ*BLT*D*BL;
        KLQ += dJ*BLT*D*B;
    }

    double scale = (double) KLL.max();
    KLL = KLL/scale;//scaling ensures robust inverse

    if (!KLL.inv()) writeMessageToParetoLog("AFElasticity: Error inverting KLL matrix");
    KQL = ~KLQ;// transpose
    KElement = KQQ - KQL*KLL*KLQ/scale;


    int order[24] = {0,8,16,1,9,17,2,10,18,3,11,19,4,12,20,5,13,21,6,14,22,7,15,23};

    for (i=0; i <24; i++)
        for (j=0; j <24; j++)
            Ke[i][j] = KElement[order[i]][order[j]];
}
/**********************************************************************/
bool AFElasticity::taylorKE(double x[8],double y[8],double z[8],double *dmatrix,double Ke[24][24])
// Use of bubble functions to improve performance, with modification proposed by Taylor
{
    int gp,i,j,k;
    double a = 1.0/sqrt(3.0);
    double xi[8] = {-a,-a,a,a,-a,-a,a,a};
    double eta[8] = {-a,a,-a,a,-a,a,-a,a};
    double mu[8] = {-a,-a,-a,-a,a,a,a,a};
    double gradNxi[8],gradNeta[8],gradNmu[8],dJ,dJ0,T1,T2,T3,gradNLxi[3],gradNLeta[3],gradNLmu[3];

    TCLMatrix J(3,3,0.0);
    TCLMatrix J0(3,3,0.0);//at center
    TCLMatrix B(6,24,0.0);
    TCLMatrix BT(24,6,0.0);

    TCLMatrix BL(6,9,0.0);
    TCLMatrix BLT(9,6,0.0);

    TCLMatrix KQQ(24,24,0.0);
    TCLMatrix KLL(9,9,0.0);
    TCLMatrix KLQ(9,24,0.0);
    TCLMatrix KQL(24,9,0.0);
    TCLMatrix KElement(24,24,0.0);
    TCLMatrix D(6,6,0.0);

    k = 0;
    for (i =0; i < 3; i++){
        gradNLxi[i] =0;
        gradNLeta[i] =0;
        gradNLmu[i] =0;

    }
    for (i =0; i < 6; i++)
        for (j =0; j <6; j++)
            D[i][j] = dmatrix[k++];

    computeGrad_H8(0.0,0.0,0.0,gradNxi,gradNeta,gradNmu);

    J0 = 0.0;
    for (i =0; i < 8; i++) {
        J0[0][0] += gradNxi[i]*x[i];
        J0[0][1] += gradNxi[i]*y[i];
        J0[0][2] += gradNxi[i]*z[i];

        J0[1][0] += gradNeta[i]*x[i];
        J0[1][1] += gradNeta[i]*y[i];
        J0[1][2] += gradNeta[i]*z[i];

        J0[2][0] += gradNmu[i]*x[i];
        J0[2][1] += gradNmu[i]*y[i];
        J0[2][2] += gradNmu[i]*z[i];
    }
    dJ0 = (double) fabs(J0.det());
    J0.inv();

    bool success = false;

    for (gp = 0; gp < 8; gp++) {
        computeGrad_H8(xi[gp],eta[gp],mu[gp],gradNxi,gradNeta,gradNmu);
        J = 0;
        for (i =0; i < 8; i++) {
            J[0][0] += gradNxi[i]*x[i];
            J[0][1] += gradNxi[i]*y[i];
            J[0][2] += gradNxi[i]*z[i];

            J[1][0] += gradNeta[i]*x[i];
            J[1][1] += gradNeta[i]*y[i];
            J[1][2] += gradNeta[i]*z[i];

            J[2][0] += gradNmu[i]*x[i];
            J[2][1] += gradNmu[i]*y[i];
            J[2][2] += gradNmu[i]*z[i];
        }
        dJ = fabs(J.det());
        if (!J.inv()){
            writeMessageToParetoLog("AFElasticity: Could not invert Jacobian in TaylorKE \n");
            continue;
        }
        success = true;
        for (i = 0; i < 8; i++) {
            T1 = J[0][0]*gradNxi[i] + J[0][1]*gradNeta[i] + J[0][2]*gradNmu[i];
            T2 = J[1][0]*gradNxi[i] + J[1][1]*gradNeta[i] + J[1][2]*gradNmu[i];
            T3 = J[2][0]*gradNxi[i] + J[2][1]*gradNeta[i] + J[2][2]*gradNmu[i];
            B[0][i] = T1;
            B[1][8+i] = T2;
            B[2][16+i] = T3;
            B[3][i] = T2;
            B[3][8+i] = T1;
            B[4][i] = T3;
            B[4][16+i] = T1;
            B[5][8+i] = T3;
            B[5][16+i] = T2;
        }
        BT = ~B;
        // Bubble functions
        computeGrad_Bubble(xi[gp],eta[gp],mu[gp],gradNLxi,gradNLeta,gradNLmu);

        for (i = 0; i < 3; i++) {
            //Below is the Taylor modified version
            T1 = J0[0][0]*gradNLxi[i] + J0[0][1]*gradNLeta[i] + J0[0][2]*gradNLmu[i];// NLx(i)
            T2 = J0[1][0]*gradNLxi[i] + J0[1][1]*gradNLeta[i] + J0[1][2]*gradNLmu[i];// NLy(i)
            T3 = J0[2][0]*gradNLxi[i] + J0[2][1]*gradNLeta[i] + J0[2][2]*gradNLmu[i];// NLz(i)

            /*T1 = J[0][0]*gradNLxi[i] + J[0][1]*gradNLeta[i] + J[0][2]*gradNLmu[i];// NLx(i)
            T2 = J[1][0]*gradNLxi[i] + J[1][1]*gradNLeta[i] + J[1][2]*gradNLmu[i];// NLy(i)
            T3 = J[2][0]*gradNLxi[i] + J[2][1]*gradNLeta[i] + J[2][2]*gradNLmu[i];// NLz(i)*/


            BL[0][i] = T1;
            BL[1][3+i] = T2;
            BL[2][6+i] = T3;
            BL[3][i] = T2;
            BL[3][3+i] = T1;
            BL[4][i] = T3;
            BL[4][6+i] = T1;
            BL[5][3+i] = T3;
            BL[5][6+i] = T2;
        }
        BL *= (dJ0);
        BLT = ~BL;
        KQQ += dJ*BT*D*B;
        KLL += dJ*BLT*D*BL;
        KLQ += dJ*BLT*D*B;
    }

    if (!success) {
        writeMessageToParetoLog("AFElasticity: Could not invert compute Ke\n");
        for (i=0; i <24; i++)
            for (j=0; j <24; j++)
                Ke[i][j] = 0;
        return false;
    }

    double scale = (double) KLL.max();
    KLL = KLL/scale;//scaling ensures robust inverse

    if (!KLL.inv()){
        writeMessageToParetoLog("AFElasticity: Error inverting KLL matrix\n");
        KElement = KQQ;
    }
    else {
        KQL = ~KLQ;// transpose
        KElement = KQQ - KQL*KLL*KLQ/scale;
    }
    int order[24] = {0,8,16,1,9,17,2,10,18,3,11,19,4,12,20,5,13,21,6,14,22,7,15,23};

    for (i=0; i <24; i++)
        for (j=0; j <24; j++)
            Ke[i][j] = KElement[order[i]][order[j]];

    return true;
}
