    Ke[0][7] = (Y*dz*(1.0/2.4E1))/((nu*2.0-1.0)*(nu+1.0))+(Y*dz*(nu*nu)*(1.0/4.8E1))/((nu*2.0-1.0)*(nu-1.0)*(nu+1.0));
    Ke[0][8] = (Y*dy*(-5.0/1.44E2))/(nu+1.0)-(Y*dy*(1.0/7.2E1))/(nu*2.0-1.0)+(Y*dy*(nu*nu)*(1.0/4.8E1))/((nu*2.0-1.0)*(nu-1.0)*(nu+1.0));
    Ke[0][9] = -(Y*((dx*dx)*(dy*dy)-(dx*dx)*(dz*dz)*2.0+(dy*dy)*(dz*dz)*2.0)*(1.0/3.6E1)-Y*nu*((dx*dx)*(dy*dy)*2.0-(dx*dx)*(dz*dz)*4.0+(dy*dy)*(dz*dz)*2.0)*(1.0/3.6E1))/(dx*dy*dz*(nu+(nu*nu)*2.0-1.0))-(Y*dx*dy*(1.0/9.6E1))/(dz*(nu+1.0))+(Y*dx*dz*(1.0/9.6E1))/(dy*(nu+1.0));
    Ke[0][10] = (Y*dz*(5.0/7.2E1))/(nu+1.0)+(Y*dz*(1.0/3.6E1))/(nu*2.0-1.0)+(Y*dz*(nu*nu)*(1.0/4.8E1))/((nu*2.0-1.0)*(nu-1.0)*(nu+1.0));
    Ke[0][11] = (Y*dy*(-1.0/4.8E1))/((nu*2.0-1.0)*(nu+1.0))+(Y*dy*(nu*nu)*(1.0/4.8E1))/((nu*2.0-1.0)*(nu-1.0)*(nu+1.0));
    Ke[0][12] = -(Y*((dx*dx)*(dy*dy)*-2.0+(dx*dx)*(dz*dz)+(dy*dy)*(dz*dz)*2.0)*(1.0/3.6E1)-Y*nu*((dx*dx)*(dy*dy)*-4.0+(dx*dx)*(dz*dz)*2.0+(dy*dy)*(dz*dz)*2.0)*(1.0/3.6E1))/(dx*dy*dz*(nu+(nu*nu)*2.0-1.0))+(Y*dx*dy*(1.0/9.6E1))/(dz*(nu+1.0))-(Y*dx*dz*(1.0/9.6E1))/(dy*(nu+1.0));
