/**********************************************************************/
void AFElasticity::KuCPU(double *x,double *y)
{
    if ((h_nodeBasedAssembly) && (h_voxelgrid))
        KuCPUNodeBased(x,y);
    else
        KuCPUElemBased(x,y);
}
/**********************************************************************/
void AFElasticity::MuCPU(double *x,double *y)
{
    if ((h_nodeBasedAssembly) && (h_voxelgrid))
        MuCPUNodeBased(x,y);
    else
        MuCPUElemBased(x,y);
}
/**********************************************************************/
void AFElasticity::ReactionForceCPUNodeBased(double *r)
// r = f-K*x // only for fixed nodes
{
    register int freeEncoded,node2,j,node,ufree,vfree,wfree,KEIndex,index;
    register double KE, uResult=0.0,vResult=0.0,wResult=0.0,uVal,vVal,wVal;

#pragma omp parallel for private(freeEncoded,KEIndex,index,node2,j,node,ufree,vfree,wfree,KE,uResult,vResult,wResult,uVal,vVal,wVal)
    for ( node = 0; node < h_nNodes; node++) {
        r[3*node] = 0;
        r[3*node+1] = 0;
        r[3*node+2] = 0;
        freeEncoded = h_free[node];
        wfree = freeEncoded/4;
        vfree = (freeEncoded - wfree*4)/2;
        ufree = (freeEncoded - wfree*4 -vfree*2);
        if ((ufree) && (vfree) && (wfree)) continue;// it is a free node
        uResult=0.0;vResult=0.0;wResult=0.0;
        KEIndex = h_nodeSignature[node];// from 0 to 256
        for (j =0; j < 27; j++) {//
            node2 = h_neighborNodes[j*h_nNodes + node];// process neighbor
            if (node2 == -1)
                continue;
            uVal = h_sol[3*node2];
            vVal = h_sol[3*node2+1];
            wVal = h_sol[3*node2+2];

            index = 81*3*KEIndex + 3*j;

            KE = h_KeNode[index];
            uResult += KE*uVal;
            KE = h_KeNode[index+1];
            uResult += KE*vVal;
            KE = h_KeNode[index+2];
            uResult += KE*wVal;

            KE = h_KeNode[index+81];
            vResult += KE*uVal;
            KE = h_KeNode[index+82];
            vResult += KE*vVal;
            KE = h_KeNode[index+83];
            vResult += KE*wVal;

            KE = h_KeNode[index+162];
            wResult += KE*uVal;
            KE = h_KeNode[index+163];
            wResult += KE*vVal;
            KE = h_KeNode[index+164];
            wResult += KE*wVal;
        }
        // write back the result
        r[3*node] =  uResult -h_f[3*node];// h_f has to be zero at this nodes?
        r[3*node+1] = vResult -h_f[3*node+1];;
        r[3*node+2] = wResult -h_f[3*node+2];
    }
}

/**********************************************************************/
void AFElasticity::ReactionForceCPUElemBased(double *r)
{
    register int freeEncoded,i,j,node,node2,codedElem,elem,KEindex,maxElem,nodeIndex,ufree,vfree,wfree,elemID,row;
    register double KE, uResult=0.0,vResult=0.0,wResult=0.0,uVal,vVal,wVal,rho;

    if (h_KETemplates == NULL) {
        writeMessageToParetoLog("Ke Templates not initialized\n");
        return;
    }
#pragma omp parallel for private(freeEncoded,i,j,node,node2,codedElem,elem,KEindex,maxElem,nodeIndex,ufree,vfree,wfree,elemID,KE, uResult,vResult,wResult,uVal,vVal,wVal,rho,row)
    for ( node = 0; node < h_nNodes; node++) {
        r[3*node] = 0;
        r[3*node+1] = 0;
        r[3*node+2] = 0;
        freeEncoded = h_free[node];
        wfree = freeEncoded >> 2;
        vfree = (freeEncoded - wfree*4)>>1;
        ufree = (freeEncoded - (wfree << 2) -(vfree<<1));
        uResult=0.0;vResult=0.0;wResult=0.0;
        if ((ufree) && (vfree) && (wfree)) continue;// it is a free node
        maxElem = h_nNeighboringElems[node];// how many elements connected to node
        for (j =0; j < maxElem; j++) {//
            codedElem = h_neighborElems[(h_nNodes)*j + node];// process elem-j neighbor
            nodeIndex = codedElem/MAXELEMS;//ranges from 0 to 7, position of this node within this elem
            elem = codedElem - nodeIndex*MAXELEMS;
            rho = h_pseudoDensity[elem];
            if (rho == 0)// element exists but is void (example: during topology optimization)
                continue;
            if  (rho < 1)// if rho is 1, then no change
                rho = pow(rho, E_RHO_PENALTY);
            elemID = h_templateID[elem];
            row = 24*3*nodeIndex;
            for (i = 0; i < 8; i++) {// now accumulate for each of the 8 nodes
                node2 = h_elems[(h_nElems)*i + elem];
                uVal = h_sol[3*node2];
                vVal = h_sol[3*node2+1];
                wVal = h_sol[3*node2+2];

                KEindex = (row + 3*i)*(h_nTemplateElements) + elemID;
                KE = h_KETemplates[KEindex];
                uResult += rho*KE*uVal;

                KEindex = (row + 3*i+1)*(h_nTemplateElements) + elemID;
                KE = h_KETemplates[KEindex];
                uResult +=  rho*KE*vVal;

                KEindex = (row + 3*i+2)*(h_nTemplateElements) + elemID;
                KE = h_KETemplates[KEindex];
                uResult += rho*KE*wVal;

                KEindex = (row + 24+3*i)*(h_nTemplateElements) + elemID;
                KE = h_KETemplates[KEindex];
                vResult += rho*KE*uVal;

                KEindex = (row + 24+3*i+1)*(h_nTemplateElements) + elemID;
                KE = h_KETemplates[KEindex];
                vResult += rho*KE*vVal;

                KEindex = (row + 24+3*i+2)*(h_nTemplateElements) + elemID;
                KE = h_KETemplates[KEindex];
                vResult += rho*KE*wVal;

                KEindex = (row + 48+3*i)*(h_nTemplateElements) + elemID;
                KE = h_KETemplates[KEindex];
                wResult += rho*KE*uVal;

                KEindex = (row + 48 + 3*i+1)*(h_nTemplateElements) + elemID;
                KE = h_KETemplates[KEindex];
                wResult += rho*KE*vVal;

                KEindex = (row + 48 + 3*i+2)*(h_nTemplateElements) + elemID;
                KE = h_KETemplates[KEindex];
                wResult += rho*KE*wVal;
            }
        }
        // write back the result
        r[3*node] =  uResult -h_f[3*node];// h_f has to be zero at this nodes?
        r[3*node+1] = vResult -h_f[3*node+1];;
        r[3*node+2] = wResult -h_f[3*node+2];
    }
}
/**********************************************************************/
void AFElasticity::KuCPUNodeBased(double *x,double *y)
// y = K*x
{
    // Carry out K*x on CPU, also enforce Dirichlet boundary conditions
    register int freeEncoded,node2,j,node,ufree,vfree,wfree,KEIndex,index;
    register double KE, uResult=0.0,vResult=0.0,wResult=0.0,uVal,vVal,wVal;


#pragma omp parallel for private(freeEncoded,KEIndex,index,node2,j,node,ufree,vfree,wfree,KE,uResult,vResult,wResult,uVal,vVal,wVal) schedule(guided,h_nNodes/100)
    for ( node = 0; node < h_nNodes; node++) {
        freeEncoded = h_free[node];
        wfree = freeEncoded/4;
        vfree = (freeEncoded - wfree*4)/2;
        ufree = (freeEncoded - wfree*4 -vfree*2);
        uResult=0.0;vResult=0.0;wResult=0.0;
        if ((h_nodeExists[node]) && (ufree || vfree || wfree)) {// process only if one of the dof  is free
            KEIndex = h_nodeSignature[node];// from 0 to 256
            for (j =0; j < 27; j++) {//
                node2 = h_neighborNodes[j*h_nNodes + node];// process neighbor
                if (node2 == -1)
                    continue;

                uVal = x[3*node2];
                vVal = x[3*node2+1];
                wVal = x[3*node2+2];

                index = 81*3*KEIndex + 3*j;

                KE = h_KeNode[index];
                uResult += KE*uVal;
                KE = h_KeNode[index+1];
                uResult += KE*vVal;
                KE = h_KeNode[index+2];
                uResult += KE*wVal;

                KE = h_KeNode[index+81];
                vResult += KE*uVal;
                KE = h_KeNode[index+82];
                vResult += KE*vVal;
                KE = h_KeNode[index+83];
                vResult += KE*wVal;

                KE = h_KeNode[index+162];
                wResult += KE*uVal;
                KE = h_KeNode[index+163];
                wResult += KE*vVal;
                KE = h_KeNode[index+164];
                wResult += KE*wVal;
            }
        }
        // write back the result
        y[3*node] = ufree*uResult ;// Dirichlet condition is enforced by d_freeu[node]
        y[3*node+1] = vfree*vResult ;
        y[3*node+2] = wfree*wResult ;
    }
}
/**********************************************************************/
void AFElasticity::KuCPUElemBased(double *x,double *y)
// y = K*x
{
    // Carry out K*x on CPU, also enforce Dirichlet boundary conditions
    register int freeEncoded,i,j,node,node2,codedElem,elem,KEindex,maxElem,nodeIndex,ufree,vfree,wfree,elemID,row;
    register double KE, uResult=0.0,vResult=0.0,wResult=0.0,uVal,vVal,wVal,EScale;


    EScale = 1.0;//default
#pragma omp parallel for private(freeEncoded,i,j,node,node2,codedElem,elem,EScale,KEindex,maxElem,nodeIndex,ufree,vfree,wfree,elemID,KE, uResult,vResult,wResult,uVal,vVal,wVal,row)
    for ( node = 0; node < h_nNodes; node++) {
        freeEncoded = h_free[node];
        wfree = freeEncoded >> 2;
        vfree = (freeEncoded - wfree*4)>>1;
        ufree = (freeEncoded - (wfree << 2) -(vfree<<1));
        uResult=0.0;vResult=0.0;wResult=0.0;
        if ((h_nodeExists[node]) &&  (ufree || vfree || wfree)) {// process only if one of the dof  is free
            maxElem = h_nNeighboringElems[node];// how many elements connected to node
            for (j =0; j < maxElem; j++) {//
                codedElem = h_neighborElems[(h_nNodes)*j + node];// process elem-j neighbor
                nodeIndex = codedElem/MAXELEMS;//ranges from 0 to 7, position of this node within this elem
                elem = codedElem - nodeIndex*MAXELEMS;
                EScale = pow(h_pseudoDensity[elem],h_Eexponent);// E = E0*(rho)^n;
                elemID = h_templateID[elem];
                row = 24*3*nodeIndex;
                for (i = 0; i < 8; i++) {// now accumulate for each of the 8 nodes
                    node2 = h_elems[(h_nElems)*i + elem];
                    uVal = x[3*node2];
                    vVal = x[3*node2+1];
                    wVal = x[3*node2+2];

                    KEindex = (row + 3*i)*(h_nTemplateElements) + elemID;
                    KE = EScale*h_KETemplates[KEindex];
                    uResult += KE*uVal;

                    KEindex = (row + 3*i+1)*(h_nTemplateElements) + elemID;
                    KE = EScale*h_KETemplates[KEindex];
                    uResult +=  KE*vVal;

                    KEindex = (row + 3*i+2)*(h_nTemplateElements) + elemID;
                    KE = EScale*h_KETemplates[KEindex];
                    uResult += KE*wVal;

                    KEindex = (row + 24+3*i)*(h_nTemplateElements) + elemID;
                    KE = EScale*h_KETemplates[KEindex];
                    vResult += KE*uVal;

                    KEindex = (row + 24+3*i+1)*(h_nTemplateElements) + elemID;
                    KE = EScale*h_KETemplates[KEindex];
                    vResult += KE*vVal;

                    KEindex = (row + 24+3*i+2)*(h_nTemplateElements) + elemID;
                    KE = EScale*h_KETemplates[KEindex];
                    vResult += KE*wVal;

                    KEindex = (row + 48+3*i)*(h_nTemplateElements) + elemID;
                    KE = EScale*h_KETemplates[KEindex];
                    wResult += KE*uVal;

                    KEindex = (row + 48 + 3*i+1)*(h_nTemplateElements) + elemID;
                    KE = EScale*h_KETemplates[KEindex];
                    wResult += KE*vVal;

                    KEindex = (row + 48 + 3*i+2)*(h_nTemplateElements) + elemID;
                    KE = EScale*h_KETemplates[KEindex];
                    wResult += KE*wVal;
                }
            }
        }
        // write back the result
        y[3*node] = ufree*uResult ;// Dirichlet condition is enforced
        y[3*node+1] = vfree*vResult;
        y[3*node+2] = wfree*wResult;
    }
}
/**********************************************************************/
void AFElasticity::getReactionForces(double *reactionForces)
// for all fixed dof, find the lagrange multipliers (reaction force)
// assume that the solution has been computed
{
    if ((h_nodeBasedAssembly) && (h_voxelgrid))
        ReactionForceCPUNodeBased(reactionForces);
    else
        ReactionForceCPUElemBased(reactionForces);
}
/**********************************************************************/
void AFElasticity::MuCPUNodeBased(double *x,double *y)
// y = M*x
{
    // Carry out M*x on CPU, also enforce Dirichlet boundary conditions
    register int freeEncoded,node2,j,node,ufree,vfree,wfree,MEIndex,index;
    register double ME, uResult=0.0,vResult=0.0,wResult=0.0,uVal,vVal,wVal;

#pragma omp parallel for private(freeEncoded,MEIndex,index,node2,j,node,ufree,vfree,wfree,ME,uResult,vResult,wResult,uVal,vVal,wVal)
    for ( node = 0; node < h_nNodes; node++) {
        freeEncoded = h_free[node];
        wfree = freeEncoded/4;
        vfree = (freeEncoded - wfree*4)/2;
        ufree = (freeEncoded - wfree*4 -vfree*2);
        uResult=0.0;vResult=0.0;wResult=0.0;
        if ((h_nodeExists[node]) && (ufree || vfree || wfree)) {// process only if one of the dof  is free
            MEIndex = h_nodeSignature[node];// from 0 to 256
            for (j =0; j < 27; j++) {//
                node2 = h_neighborNodes[j*h_nNodes + node];// process neighbor
                if (node2 == -1)
                    continue;

                uVal = x[3*node2];
                vVal = x[3*node2+1];
                wVal = x[3*node2+2];

                index = 81*3*MEIndex + 3*j;

                ME = h_MeNode[index];
                uResult += ME*uVal;
                ME = h_MeNode[index+1];
                uResult += ME*vVal;
                ME = h_MeNode[index+2];
                uResult += ME*wVal;

                ME = h_MeNode[index+81];
                vResult += ME*uVal;
                ME = h_MeNode[index+82];
                vResult += ME*vVal;
                ME = h_MeNode[index+83];
                vResult += ME*wVal;

                ME = h_MeNode[index+162];
                wResult += ME*uVal;
                ME = h_MeNode[index+163];
                wResult += ME*vVal;
                ME = h_MeNode[index+164];
                wResult += ME*wVal;
            }
        }
        // write back the result
        y[3*node] = ufree*uResult;// Dirichlet condition is enforced by d_freeu[node]
        y[3*node+1] = vfree*vResult;
        y[3*node+2] = wfree*wResult;
    }
}
/**********************************************************************/
void AFElasticity::MuCPUElemBased(double *x,double *y)
{
    // Carry out M*u on CPU, also enforce Dirichlet boundary conditions
    register int freeEncoded,i,j,node,node2,codedElem,elem,MEindex,maxElem,nodeIndex,ufree,vfree,wfree,elemID;
    register double ME, uResult=0.0,vResult=0.0,wResult=0.0,MScale,uVal,vVal,wVal;

#pragma omp parallel for private(freeEncoded,i,j,node,node2,codedElem,elem,MEindex,MScale,maxElem,nodeIndex,ufree,vfree,wfree,elemID,ME,uResult,vResult,wResult,uVal,vVal,wVal)
    for ( node = 0; node < h_nNodes; node++) {
        freeEncoded = h_free[node];
        wfree = freeEncoded/4;
        vfree = (freeEncoded - wfree*4)/2;
        ufree = (freeEncoded - wfree*4 -vfree*2);

        uResult=0.0;vResult=0.0;wResult=0.0;
        if (ufree || vfree || wfree) {// process only if one of the dof  is free
            maxElem = h_nNeighboringElems[node];// how many elements connected to node
            for (j =0; j < maxElem; j++) {//
                codedElem = h_neighborElems[(h_nNodes)*j + node];// process elem-j neighbor
                nodeIndex = codedElem/MAXELEMS;//ranges from 0 to 7, position of this node within this elem
                elem = codedElem - nodeIndex*MAXELEMS;
                MScale = pow(h_pseudoDensity[elem], h_Mexponent);
                elemID = h_templateID[elem];
                for (i = 0; i < 8; i++) {// now accumulate for each of the 8 nodes
                    node2 = h_elems[(h_nElems)*i + elem];
                    uVal = x[3*node2];
                    vVal = x[3*node2+1];
                    wVal = x[3*node2+2];

                    MEindex = (24*3*nodeIndex + 3*i)*(h_nTemplateElements) + elemID;
                    ME = MScale*h_METemplates[MEindex];
                    uResult += ME*uVal;

                    MEindex = (24*3*nodeIndex + 3*i+1)*(h_nTemplateElements) + elemID;
                    ME = MScale*h_METemplates[MEindex];
                    uResult +=  ME*vVal;

                    MEindex = (24*3*nodeIndex + 3*i+2)*(h_nTemplateElements) + elemID;
                    ME = MScale*h_METemplates[MEindex];
                    uResult += ME*wVal;

                    MEindex = (24*3*nodeIndex + 24+3*i)*(h_nTemplateElements) + elemID;
                    ME = MScale*h_METemplates[MEindex];
                    vResult += ME*uVal;

                    MEindex = (24*3*nodeIndex + 24+3*i+1)*(h_nTemplateElements) + elemID;
                    ME = MScale*h_METemplates[MEindex];
                    vResult += ME*vVal;

                    MEindex = (24*3*nodeIndex + 24+3*i+2)*(h_nTemplateElements) + elemID;
                    ME = MScale*h_METemplates[MEindex];
                    vResult += ME*wVal;

                    MEindex = (24*3*nodeIndex + 48+3*i)*(h_nTemplateElements) + elemID;
                    ME = MScale*h_METemplates[MEindex];
                    wResult += ME*uVal;

                    MEindex = (24*3*nodeIndex + 48 + 3*i+1)*(h_nTemplateElements) + elemID;
                    ME = MScale*h_METemplates[MEindex];
                    wResult += ME*vVal;

                    MEindex = (24*3*nodeIndex + 48 + 3*i+2)*(h_nTemplateElements) + elemID;
                    ME = MScale*h_METemplates[MEindex];
                    wResult += ME*wVal;
                }
            }
        }
        // write back the result
        y[3*node] = ufree*uResult;// Dirichlet condition is enforced by d_freeu[node]
        y[3*node+1] = vfree*vResult;
        y[3*node+2] = wfree*wResult;
    }
}
/**********************************************************************/
void AFElasticity::dumpDeltaSigma(char *fileName, double offset[3])
{
    int nodeDeltaMax, nodeStressMax;
    double deltaMax,vonMisesMax;
    FILE *fptr = fopen(fileName,"w");
    if (fptr == NULL){
        writeMessageToParetoLog("Could not open file %s \n",fileName);
        return;
    }
    deltaMax = getDeformationMax(&nodeDeltaMax);
    vonMisesMax = getMaxVonMisesStress(&nodeStressMax);

    fprintf(fptr,"%d\n",h_nNodes);
    fprintf(fptr,"%.3e %.3e %.3e %.5e\n",h_x[nodeDeltaMax]+offset[0],h_y[nodeDeltaMax]+offset[1],h_z[nodeDeltaMax]+offset[2],deltaMax);
    fprintf(fptr,"%.3e %.3e %.3e %.5e\n",h_x[nodeStressMax]+offset[0],h_y[nodeStressMax]+offset[1],h_z[nodeStressMax]+offset[2],vonMisesMax);

    fclose(fptr);
}
/**********************************************************************/
void AFElasticity::dumpUVW(char *fileName)
{
    int i ;
    FILE *fptr = fopen(fileName,"w");
    if (fptr == NULL){
        writeMessageToParetoLog("Could not open file %s \n",fileName);
        return;
    }
    fprintf(fptr,"%12d\n",h_nNodes);
    for (i =0; i < h_nNodes; i++)
        fprintf(fptr,"%.12e %.12e %.12e \n",h_sol[3*i],h_sol[3*i+1],h_sol[3*i+2]);

    fclose(fptr);
}
/**********************************************************************/
void AFElasticity::printMeshSummary()
{
    writeMessageToParetoLog("---------------- Mesh Summary -----------------------");
    writeMessageToParetoLog("#Nodes = %d ",h_nNodes);
    writeMessageToParetoLog("#Elems = %d ",h_nElems);
    writeMessageToParetoLog("#DOF = %d ",3*h_nNodes);
    writeMessageToParetoLog("-----------------------------------------------------");
}
/**********************************************************************/
void AFElasticity::printSolverOptions()
{
    writeMessageToParetoLog("---------------- Solver Options ----------------------");
    if (h_nodeBasedAssembly) writeMessageToParetoLog("Node Based SpMV: On ");
    else writeMessageToParetoLog("Nodal SpMV: Off ");

    if (usingGPU) writeMessageToParetoLog("GPU: On ");
    else writeMessageToParetoLog("GPU: Off ");

    if (ws_deflationType != DEFLATION_NONE) writeMessageToParetoLog("Deflation: On ");
    else writeMessageToParetoLog("Deflation: Off ");

    writeMessageToParetoLog("-----------------------------------------------------\n");
}
/**********************************************************************/
void AFElasticity::printAnalysisSummary()
{
    writeMessageToParetoLog("----------------- Analysis Summary ------------------\n");
    writeMessageToParetoLog("Max Deformation = %.3e \n",h_deformationMax);
    writeMessageToParetoLog("Max Von Mises Stress = %.3e \n",h_vonmisesMax);
    writeMessageToParetoLog("#CG Iterations = %d \n",getLastCGIteration());
    writeMessageToParetoLog("Time taken(sec) = %f \n",getElapsedTimeInSec());
    writeMessageToParetoLog("-----------------------------------------------------\n");
}
/**********************************************************************/
void AFElasticity::printMaxMinUVW()
{
    int i ;
    double uMax=-1e10,vMax=-1e10,wMax=-1e10,u,v,w;
    double uMin=1e10,vMin=1e10,wMin=1e10;

    for (i =0; i < h_nNodes; i++) {
        u = h_sol[3*i];
        v = h_sol[3*i+1];
        w = h_sol[3*i+2];
        uMax = (u > uMax)? u:uMax;
        vMax = (v > vMax)? v:vMax;
        wMax = (w > wMax)? w:wMax;

        uMin = (u < uMin)? u:uMin;
        vMin = (v < vMin)? v:vMin;
        wMin = (w < wMin)? w:wMin;
    }
    writeMessageToParetoLog("AFElasticity: Max deformation: %.6e\n",h_deformationMax);
    writeMessageToParetoLog("AFElasticity: Max (uvw): %0.4e %0.4e %0.4e \n",uMax,vMax,wMax);
    writeMessageToParetoLog("AFElasticity: Min (uvw): %0.4e %0.4e %0.4e \n",uMin,vMin,wMin);
}

/**********************************************************************/
void  AFElasticity::safeFree(void *ptr)
{
    if (ptr) free(ptr);
}
/**********************************************************************/
void  AFElasticity::releaseCPUMemory(void)
{
    int i;
    if (h_nNodes == 0) return;
    if (h_hexmesh_verbose)	 writeMessageToParetoLog("AFElasticity: releasing CPU memory\n");
    // CPU memory deallocation
    safeFree(h_x);h_x = NULL;
    safeFree(h_y);h_y = NULL;
    safeFree(h_z);h_z = NULL;
    safeFree(h_nodeLabels); h_nodeLabels = NULL;
    safeFree(h_nodeExists); h_nodeExists = NULL;

    safeFree(h_elems);h_elems = NULL;
    safeFree(h_pseudoDensity);h_pseudoDensity = NULL;
    safeFree(h_neighborElems);h_neighborElems = NULL;
    safeFree(h_templateID);h_templateID = NULL;


    safeFree(h_elemComponent); h_elemComponent = NULL;
    safeFree(h_sol);h_sol = NULL;
    safeFree(h_solErr);h_solErr = NULL;
    safeFree(h_residual);h_residual = NULL;
    for (i = 0; i < 6; i++) {
        safeFree(h_elemstrains[i]);h_elemstrains[i] = NULL;
        safeFree(h_elemstresses[i]);h_elemstresses[i] = NULL;
        safeFree(h_nodestrains[i]);h_nodestrains[i] = NULL;
        safeFree(h_nodestresses[i]);h_nodestresses[i] = NULL;
    }
    safeFree(h_nodevonmises);h_nodevonmises = NULL;
    safeFree(h_free);h_free = NULL;
    safeFree(h_dirichlet);h_dirichlet = NULL;
    safeFree(h_retain); h_retain = NULL;
    safeFree(h_f);h_f = NULL;
    safeFree(h_bodyForce);h_bodyForce = NULL;
    safeFree(h_output);h_output = NULL;
    safeFree(h_KETemplates);h_KETemplates = NULL;
    safeFree(h_METemplates);h_METemplates = NULL;
    h_nNodes = 0;
    h_nElems = 0;
    h_nTemplateElements = 0;
    h_maxNeighboringElements = 0;
    safeFree(h_neighborNodes);h_neighborNodes = NULL;
    safeFree(h_nodeSignature);h_nodeSignature = NULL;
    safeFree(h_KeNode);h_KeNode = NULL;

    safeFree(h_StructuringElems); h_StructuringElems = NULL;

    safeFree(h_keepElem);h_keepElem = NULL;

    safeFree(h_tessellationXYZ);h_tessellationXYZ = NULL;
    safeFree(h_tessellationTriangles);h_tessellationTriangles = NULL;
    safeFree(h_tessellationUVW);h_tessellationUVW = NULL;
    safeFree(h_tessellationVonMises);h_tessellationVonMises = NULL;
    safeFree(h_tessellationTemperature);h_tessellationTemperature = NULL;
    safeFree(h_tessellationModalUVW);h_tessellationModalUVW = NULL;

#ifdef COMPILE_GPUCODE 
    releaseHexmeshGPUMemory(&h_gpuData);
#endif

    h_nNodes = 0;
    h_nElems = 0;
}
/**********************************************************/
int AFElasticity::findCommonElements(int n1, int *v1, int n2, int *v2, int *vCommon)
{
    int nCommon = 0,i,k;
    for (i = 0; i < n1; i++) {
        for (k =0; k < n2; k++) {
            if (v1[i] == v2[k]){
                vCommon[nCommon] = v1[i];
                nCommon++;
            }
        }
    }
    return (nCommon);
}
/**********************************************************************/
void AFElasticity::copy(double *x, double *y)
{
#pragma omp parallel for 
    for (int i =0; i < 3*h_nNodes; i++)
        y[i] = x[i];
}
/**********************************************************************/
void AFElasticity::copy(double *x, double *y, int N)
{
#pragma omp parallel for
    for (int i =0; i < N; i++)
        y[i] = x[i];
}
/**********************************************************************/
double AFElasticity::Norm(double *x,int length)
{// Assumes that x is of length
    double alpha =0;
    int i;
#pragma omp parallel for reduction (+: alpha )
    for ( i =0; i < length; i++)
        alpha += pow(x[i],2.0);
#pragma omp barrier 
    return sqrt(alpha);
}

/**********************************************************************/
double AFElasticity::Norm(double *x)
{// Assumes that x is of length 3*h_nNodes
    double alpha =0;
    int i;
#pragma omp parallel for reduction (+: alpha )
    for ( i =0; i < 3*h_nNodes; i++)
        alpha += pow(x[i],2.0);
#pragma omp barrier 
    return sqrt(alpha);
}
/**********************************************************************/
double AFElasticity::dotprod(double *x, double *y)
{// Assumes that x and y are of length h_nNodes
    double alpha =0;
    int i;
    alpha = 0.0;
#pragma omp parallel for reduction (+: alpha )
    for ( i =0; i < 3*h_nNodes; i++)
        alpha += x[i]*y[i];
#pragma omp barrier 
    return alpha;
}
/**********************************************************************/
double AFElasticity::dotprod(double *x, double *y, int N)
{// Assumes that x and y are of length h_nNodes
    double alpha =0;
    int i;
    alpha = 0.0;
#pragma omp parallel for reduction (+: alpha )
    for ( i =0; i < N; i++)
        alpha += x[i]*y[i];
#pragma omp barrier
    return alpha;
}
/**********************************************************************/
double AFElasticity::normalize(double *x, double *y)
{// y = x/||x||
    double nrm;

    nrm = Norm(x);
#pragma omp parallel for
    for (int i =0; i < 3*h_nNodes; i++)
        y[i] = x[i]/nrm;

    return nrm;
}
/**********************************************************************/
void AFElasticity::zeaxpy(double alpha,double beta,double *z,double *x, double *y, int N)
// z = alpha*x + beta*y (vector)
{
#pragma omp parallel for
    for (int i =0; i < N; i++)
        z[i] = alpha*x[i] + beta*y[i];
}
/**********************************************************************/
void AFElasticity::zeaxpy(double alpha,double beta,double *z,double *x, double *y)
// z = alpha*x + beta*y (vector)
{
#pragma omp parallel for
    for (int i =0; i < 3*h_nNodes; i++)
        z[i] = alpha*x[i] + beta*y[i];
}
/**********************************************************************/
void AFElasticity::ScaleByVector(double *z,double *x, double *y)
// z = x./y
{
#pragma omp parallel for
    for (int i =0; i < 3*h_nNodes; i++)
        z[i] = x[i]/y[i];
}
/**********************************************************************/
void AFElasticity::axpy(double alpha, double *x, double *y)
{
    // y = y + alpha*x
#pragma omp parallel for
    for (int i =0; i < 3*h_nNodes; i++)
        y[i] += alpha*x[i];
}
/**********************************************************************/
void AFElasticity::axpy(double alpha, double *x, double *y, int N)
{
    // y = y + alpha*x
#pragma omp parallel for
    for (int i =0; i < N; i++)
        y[i] += alpha*x[i];
}
/**********************************************************************/
void AFElasticity::scale(double alpha, double *x)
{
#pragma omp parallel for
    for (int i =0; i < 3*h_nNodes; i++)
        x[i] *= alpha;
}
/**********************************************************************/
void AFElasticity::ComputeDiagOfK(double *diag)
// Compute the diagonal of the K maitrx
{	
    register int j,node,elem,KEindex,maxElem,nodeIndex,elemID,codedElemNum;
    register double uResult=0.0,vResult=0.0,wResult=0.0;

#pragma omp parallel for private(j,node,elem,KEindex,maxElem,nodeIndex,elemID,codedElemNum,uResult,vResult,wResult)
    for ( node = 0; node < h_nNodes; node++) {
        uResult=0.0;
        vResult=0.0;
        wResult=0.0;
        maxElem = h_nNeighboringElems[node];// how many elements connected to node
        for (j =0; j < maxElem; j++) {//
            codedElemNum = h_neighborElems[(h_nNodes)*j + node];// process elem-j neighbor
            nodeIndex = codedElemNum/MAXELEMS;
            elem =codedElemNum -nodeIndex*MAXELEMS;
            elemID = h_templateID[elem];

            KEindex = (24*3*nodeIndex + 3*nodeIndex)*(h_nTemplateElements) + elemID;
            uResult += h_KETemplates[KEindex];

            KEindex = (24*3*nodeIndex + 24 + 3*nodeIndex + 1)*(h_nTemplateElements) + elemID;
            vResult += h_KETemplates[KEindex];

            KEindex = (24*3*nodeIndex + 48 + 3*nodeIndex + 2)*(h_nTemplateElements) + elemID;
            wResult += h_KETemplates[KEindex];
        }
        // write back the result
        diag[3*node] = uResult;
        diag[3*node+1] = vResult;
        diag[3*node+2] = wResult;
    }
    // update K_diag on GPU

}
/**********************************************************************/
void AFElasticity::computeDeformationMax(void)
{
    double deform,u,v,w ;
    int i;

    isStaticResultValid = false;
    h_deformationMax = 0.0;
    for (i =0; i < 3; i++) {
        h_uvwMin[i] = HUGE_VAL;
        h_uvwMax[i] = -HUGE_VAL;
    }
    for ( i =0; i < h_nNodes;i++) {
        if (!h_nodeExists[i]) continue;
        u = h_sol[3*i];
        v = h_sol[3*i+1];
        w = h_sol[3*i+2];
        h_uvwMin[0] = (u < h_uvwMin[0])? u:h_uvwMin[0];
        h_uvwMin[1] = (v < h_uvwMin[1])? v:h_uvwMin[1];
        h_uvwMin[2] = (w < h_uvwMin[2])? w:h_uvwMin[2];

        h_uvwMax[0] = (u > h_uvwMax[0])? u:h_uvwMax[0];
        h_uvwMax[1] = (v > h_uvwMax[1])? v:h_uvwMax[1];
        h_uvwMax[2] = (w > h_uvwMax[2])? w:h_uvwMax[2];

        deform = sqrt(u*u + v*v + w*w);
        //deform = sqrt(v*v );
        if (deform > h_deformationMax) {
            h_deformationMax = deform;
            h_nodeWithMaxDeformation = i;
        }
    }
    isStaticResultValid = true;
    if (h_hexmesh_verbose) {
        writeMessageToParetoLog("AFElasticity: Max deformation: %.6e",h_deformationMax);
    }
}
/**********************************************************************/
void	AFElasticity::enforceSliding(double *sol )
{
    int i;
    writeMessageToParetoLog("Imposing sliding: special case of x fixed\n");
    for ( i =0; i < h_nNodes;i++) {
        if (h_nodeLabels[i] == ELASTICITY_SLIDING){
            sol[3*i] = 0;
        }
    }
}

/**********************************************************************/
bool AFElasticity::assembleElasticityKMatrix(void)
{
    int nNodes,nElems,elemNodes[8];
    double x[8],y[8],z[8];
    double KElem[24][24];


    if (h_hexmesh_verbose) 	 writeMessageToParetoLog("AFElasticity: assembleElasticityKMatrix ");

    if (!h_voxelgrid){
        writeMessageToParetoLog("AFElasticity: assembleElasticityKMatrix() only implemented for voxel mesh");
        return false;
    }
    if (getNumberOfParts() > 1){
        writeMessageToParetoLog("AFElasticity: assembleElasticityKMatrix() only implemented for one part");
        return false;
    }
    nNodes = getNumNodes();
    nElems = getNumElems();
    if ( (nNodes == 0) || (nElems == 0) ){
        writeMessageToParetoLog("AFElasticity: Cannot assemble; nNodes or nElems is zero");
        return false;
    }

    h_denseKMatrix.resize(3*nNodes,3*nNodes);// 3 dof per node
    h_denseKMatrix.setZero(3*nNodes,3*nNodes);

    // get Ke for the first element
    getElemNodeLocation(0,x,y,z);//for element 0
    int matID = 0;// assume only one material
    taylorKE(x,y,z,&(h_DMatrices[6*6*matID]),KElem);

    int node,globalDof[24];
    for (int elem = 0; elem < nElems; elem++){// assemble
        double EScale;
        EScale = pow(h_pseudoDensity[elem],h_Eexponent);// E = E0*(rho)^n;
        if (EScale < TOL) continue;

        getElemNodes(elem,elemNodes);
        for (int i = 0; i < 8; i++){
            node = elemNodes[i];
            globalDof[3*i] = 3*node;
            globalDof[3*i+1] = 3*node+1;
            globalDof[3*i+2] = 3*node+2;
        }
        int j;
        for (int i = 0; i < 24; i++){
#pragma omp parallel for private(j)
            for (j = 0; j < 24; j++){
                h_denseKMatrix(globalDof[i],globalDof[j]) += EScale*KElem[i][j];
            }
        }
    }
    return true;
}
/**********************************************************************/
int	AFElasticity::solveLinearSystemViaEigenProjection(void)
{
    int i,j,nNodes;
    double *temp,b[MAX_EIGEN_MODES],a[MAX_EIGEN_MODES];

    if (h_nEigenModes == 0) return -1;// nothing stored

    nNodes = h_nNodes;
    temp = (double *)malloc(3*nNodes*sizeof(double));

    getForceVector(temp);
    // get the components of the force vector along all eigen vectors
    for (i =0; i < h_nEigenModes; i++) {
        b[i] = dotprod(h_eigenModes[i],temp);
        a[i] = b[i]/h_eigenValues[i];
    }
    // copy back solution to temp as a combination of eigen vectors
    memset(temp,0,3*nNodes*sizeof(double));
    for (i =0; i < h_nEigenModes; i++) {
        for (j = 0; j < 3*nNodes; j++)
            temp[j] += a[i]*h_eigenModes[i][j];

    }
    setSolutionAtAllNodes(temp);
    return 1;
}
/**********************************************************************/
void AFElasticity::computeGeometricKgUNodal(int node,double *x, double *y)
{
    // Kg for an isotropic element of arbitrary aspect ratio
    int i, j, maxElem, codedElem, nodeIndex, elem, node2;
    double sxx,syy,szz,sxy,sxz,syz, dx,dy,dz, aa, ab, ac, bb, bc, cc;
    double uVal = 0, vVal = 0, wVal = 0, t1;

    dx = h_dx;
    dy = h_dy;
    dz = h_dz;
    double volume = dx*dy*dz;
    // Initialize Shape function gradient

    aa = 1/(16*dx*dx);
    ab = 1/(16*dx*dy);
    ac = 1/(16*dx*dz);
    bb = 1/(16*dy*dy);
    bc = 1/(16*dy*dz);
    cc = 1/(16*dz*dz);

    int N_x[8] = {-1, 1, 1, -1, -1, 1, 1, -1};
    int N_y[8] = {-1, -1, 1, 1, -1, -1, 1, 1};
    int N_z[8] = {-1, -1, -1, -1, 1, 1, 1, 1};

    maxElem = h_nNeighboringElems[node];// how many elements connected to node
    for (j =0; j < maxElem; j++) {//
        codedElem = h_neighborElems[(h_nNodes)*j + node];// process elem-j neighbor
        nodeIndex = codedElem/MAXELEMS;//ranges from 0 to 7, position of this node within this elem
        elem = codedElem - nodeIndex*MAXELEMS;
        sxx = aa*h_elemstresses[0][elem];
        syy = bb*h_elemstresses[1][elem];
        szz = cc*h_elemstresses[2][elem];
        sxy = ab*h_elemstresses[3][elem];
        sxz = ac*h_elemstresses[4][elem];
        syz = bc*h_elemstresses[5][elem];

        for (i = 0; i < 8; i++) {// now accumulate for each of the 8 nodes
            node2 = h_elems[(h_nElems)*i + elem];
            t1 = volume*(N_x[nodeIndex]*(sxx*N_x[i] + sxy*N_y[i] + sxz*N_z[i])
                         + N_y[nodeIndex]*(sxy*N_x[i] + syy*N_y[i] + syz*N_z[i])
                         + N_z[nodeIndex]*(sxz*N_x[i] + syz*N_y[i] + szz*N_z[i]));

            uVal += t1*x[3*node2];
            vVal += t1*x[3*node2 + 1];
            wVal += t1*x[3*node2 + 2];
        }
    }
    y[3*node] = -uVal;
    y[3*node + 1] = -vVal;
    y[3*node + 2] = -wVal;
}
/**********************************************************************/
void AFElasticity::computeKgUBuckling(double *u, double *result)
{

    int freeEncoded,ufree,vfree,wfree;
    int elem, node1, node2, i,j,k;
    double u_result, v_result, w_result;
    double K_temp[24][24];
    bool nodalMethod = true;

    memset(result,0,3*h_nNodes*sizeof(double));

    if (nodalMethod){
        for (node1 = 0; node1 < h_nNodes; node1++)
            computeGeometricKgUNodal(node1, u, result);
    }
    else {
        for (elem = 0; elem < h_nElems; elem++){
            if (h_pseudoDensity[elem]< h_pseudoDensityCutoff) continue;
            computeBucklingKgVoxel(elem,K_temp);
            for (i = 0; i < 8; i++) {
                node1 = h_elems[(h_nElems)*i + elem];
                u_result = 0; v_result = 0; w_result = 0;
                for (j = 0; j < 8; j++) {
                    node2 = h_elems[(h_nElems)*j + elem];
                    for (k = 0; k < 3; k++) {
                        u_result += K_temp[3*i + 0][3*j + k]*u[3*node2 + k];
                        v_result += K_temp[3*i + 1][3*j + k]*u[3*node2 + k];
                        w_result += K_temp[3*i + 2][3*j + k]*u[3*node2 + k];
                    }
                }
                result[3*node1]		-= u_result;
                result[3*node1 + 1]	-= v_result;
                result[3*node1 + 2]	-= w_result;
            }
        }

    }
    // enforce Dirichlet conditions
    for (node1 = 0; node1 < h_nNodes; node1++) {
        freeEncoded = h_free[node1];
        wfree = freeEncoded >> 2;
        vfree = (freeEncoded - wfree*4)>>1;
        ufree = (freeEncoded - (wfree << 2) -(vfree<<1));
        result[3*node1] *= ufree ;// Dirichlet condition is enforced
        result[3*node1+1] *= vfree;
        result[3*node1+2] *= wfree;
    }
}
/**********************************************************************/
double AFElasticity::RayleighQuotientBuckling(double *x)
{
    // x'*K*x/(x'*Kg*x)
    double num,denom,*y;
    allocVector(3*h_nNodes,&y);

    KuCPU(x,y);
    num = dotprod(x,y);
    computeKgUBuckling(x,y);
    denom = dotprod(x,y);
    free(y);
    return (num/denom);
}
/**********************************************************************/
bool	AFElasticity::solveBucklingModal(int nEigenModes,double *eigenValues,double **eigenModes,double eigRelativeAccuracy,double allocatedTimeInSecs)
{
    int n,i,totalIter;
    double **X,*omega,**V,**Y,iter,ref,refOld,*forceVectorSave,*solSave,cgErrorSave;
    bool success;
    Timer timer;

    timer.start();
    if (!isStaticResultValid) {
        writeMessageToParetoLog("AFElasticity: Perform FEA before calling computeBucklingKgVoxel \n");
        return false;
    }
    postprocess();// stresses are needed for buckling

    n = nEigenModes;//  additional buffer?
    allocMatrix(n,3*h_nNodes,&X);
    allocMatrix(n,3*h_nNodes,&Y);
    allocMatrix(n,n,&V);
    allocVector(3*h_nNodes,&forceVectorSave);
    allocVector(3*h_nNodes,&solSave);
    allocVector(n,&omega);

    cgErrorSave = h_CGRelativeResErr;
    h_CGRelativeResErr = 0.01;

    copy(h_sol,solSave);
    copy(h_f,forceVectorSave);
    for (i = 0; i < n;i++) {
        initializeRandomVector(X[i]);
        omega[i] = RayleighQuotientBuckling(X[i]);
    }
    ref = 1.0;
    totalIter= 0;
    iter = 0;

    success = true;
    while (1) {
        for (i = 0; i < n;i++) {
            if (omega[i] <= 0){
                if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Component is in tension; could not compute buckling");
                initializeToZeros(X[i]);
                success = false;
                break;
            }
            computeKgUBuckling(X[i],h_f); //h_f = Kg*X[i]
            scale(omega[i],h_f);// h_f *= lambda[i];
            if (!solveElasticityStatic())
                return false;// Solve K*h_sol = h_f
            //temp = X[i];X[i] = h_sol;h_sol = temp;// avoid direct copy; use previous eigen vector as starting point
            copy(h_sol,X[i]);
            omega[i] = RayleighQuotientBuckling(X[i]);
        }
        if (!success) break;
        refOld = ref;
        ref= 0;
        for (i = 0; i < nEigenModes;i++)    ref += omega[i];
        //for (i = 0; i < nEigenModes;i++) 	 writeMessageToParetoLog(" %e ",omega[i]); 		 writeMessageToParetoLog("\n");
        if (abs(ref-refOld)/ref < eigRelativeAccuracy) break;
        if (iter > 10) {
            if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Could not converge in buckling");
            success = false;
            break;
        }
        iter++;
        if (timer.getElapsedTimeInSec() > allocatedTimeInSecs) {
            writeMessageToParetoLog("AFElasticity: Exceeded max allowed time in Buckling of %.1f seconds \n",allocatedTimeInSecs);
            success = false;
            break;
        }
    }
    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Computed Buckling Mode");

    for (i = 0; i < nEigenModes;i++){
        copy(X[i],eigenModes[i]);
        if (omega[i] < 0)// probably in tension
            omega[i] = 1e12;
        eigenValues[i] = sqrt(omega[i])/(2*3.1415);
    }
    copy(solSave,h_sol);// copy the solution vector back
    computeDeformationMax();
    postprocess();
    copy(forceVectorSave,h_f);// copy the force vector back

    freeMatrix(n,X);
    freeMatrix(n,Y);
    free(omega);
    free(solSave);
    free(forceVectorSave);
    h_CGRelativeResErr = cgErrorSave;
    if (!success) return false;
    else return true;
}
/**********************************************************************/
bool	AFElasticity::solveElasticityStaticDirect(void)
{
    int nNodes,nElems;
    Timer tempTimer;

    if (h_hexmesh_verbose) 	 writeMessageToParetoLog("AFElasticity: solveElasticityStaticDirect");

    if (!h_voxelgrid){
        writeMessageToParetoLog("AFElasticity: solveElasticityStaticDirect() only implemented for voxel mesh");
        return false;
    }
    if (getNumberOfParts() > 1){
        writeMessageToParetoLog("AFElasticity: solveElasticityStaticDirect() only implemented for one part");
        return false;
    }
    nNodes = getNumNodes();
    nElems = getNumElems();
    if ( (nNodes == 0) || (nElems == 0) ){
        writeMessageToParetoLog("AFElasticity: Cannot solve; nNodes or nElems is zero");
        return false;
    }
    VectorXd                            temp_solutionVector;// u,v,w,thx,thy,thz for each node
    VectorXd                            temp_forceVector;

    tempTimer.start();
    initializeSolution();

    assembleElasticityKMatrix();
    cout << "After assembly time = " << tempTimer.getElapsedTimeInSec() << endl;
    temp_forceVector.resize(3*nNodes);// 3 dof per node
    temp_forceVector.setZero(3*nNodes);

    for (int dof = 0; dof < 3*nNodes; dof++)
        temp_forceVector(dof) = h_f[dof];

    temp_solutionVector.resize(3*nNodes);// 3 dof per node
    temp_solutionVector.setZero(3*nNodes);

    double maxValue = h_denseKMatrix.maxCoeff();
    int freeEncoded, wfree,vfree,ufree;

    // for all fixed nodes, make the diagonals huge
    for (int node = 0; node < nNodes; node++){
        freeEncoded = h_free[node];
        wfree = freeEncoded/4;// 0 (fixed) or 1 (free)
        vfree = (freeEncoded - wfree*4)/2;// 0 or 1
        ufree = (freeEncoded - wfree*4 -vfree*2);// 0 or 1
        if (ufree == 0){
            temp_forceVector(3*node) = 0;
            h_denseKMatrix(3*node,3*node) = 1e5*maxValue;
        }
        if (vfree == 0){
            temp_forceVector(3*node+1) = 0;
            h_denseKMatrix(3*node+1,3*node+1) = 1e5*maxValue;
        }
        if (wfree == 0){
            temp_forceVector(3*node+2) = 0;
            h_denseKMatrix(3*node+2,3*node+2) = 1e5*maxValue;
        }
    }
    // are there nodes with no struts? This will lead to zero diagonals
    for (int dof = 0; dof < 3*nNodes; dof++){
        if (fabs(h_denseKMatrix(dof,dof)) < TOL){
            h_denseKMatrix(dof,dof) = 1e5*maxValue;
            temp_forceVector(dof) = 0;
        }
    }
    cout << "After BC = " << tempTimer.getElapsedTimeInSec() << endl;
    bool convertIntoSparse;
    convertIntoSparse = true;
    if (convertIntoSparse){
        h_sparseKMatrix = h_denseKMatrix.sparseView();
        cout << "After sparse= " << tempTimer.getElapsedTimeInSec() << endl;
        h_sparseKMatrixSolver.compute(h_sparseKMatrix);
        cout << "After LLT = " << tempTimer.getElapsedTimeInSec() << endl;
        if (h_sparseKMatrixSolver.info() != 0) {
            writeMessageToParetoLog("solveElasticityStaticDirect: Sparse LLT decomposition failed");
            return false;
        }
        temp_solutionVector = h_sparseKMatrixSolver.solve(temp_forceVector);
        cout << "After solution = " << tempTimer.getElapsedTimeInSec() << endl;
    }
    else
        temp_solutionVector = h_denseKMatrix.llt().solve(temp_forceVector);

    for (int dof = 0; dof < 3*nNodes; dof++)
        h_sol[dof] = temp_solutionVector(dof);

    computeDeformationMax();
    if (_isnan(computeCompliance()))// likely to be disconnected body
        return false;
    return true;
}
/**********************************************************************/
bool	AFElasticity::solveElasticityStatic(void)
{
    int nIter;

    if (h_hexmesh_verbose) 	 writeMessageToParetoLog("AFElasticity: Solving Linear System");

    if ((h_voxelgrid) &&  (h_nodeBasedAssembly) && (h_KeNode == NULL)) {
        computeKeAndMeNodal(true);
    }

    initializeSolution();
    bool deflationSuccess = true;
    bool CGSuccess;

    if (ws_deflationType> DEFLATION_NONE) {
        while (!InitializeDeflationForElasticity()) {// if failure
            if (ws_nGroupsDesired < 10){// complete failure
                if (h_hexmesh_verbose) 	 writeMessageToParetoLog("\nAFElasticity: Deflation unsuccessful\n");//print first time
                deflationSuccess = false;
                break;
            }
            ws_nGroupsDesired = MAX(9, (0.9*ws_nGroupsDesired));//reduce groups
        }
        if (deflationSuccess){
            if (h_simpMode)
                CGSuccess = performPCGW(&nIter);//deflation with preconditioner
            else
                CGSuccess = performCGW(&nIter);//deflation
            if (nIter > 100){
                ws_nGroupsDesired = MIN(MAX_WORKSPACE_GROUPS,1.1*ws_nGroupsDesired);//increase groups, but beyond N  groups, more time is spent on LLT than on CG
            }
        }
        else{
            CGSuccess = performCG(&nIter);
            ws_nGroupsDesired = MAX(ws_nGroupsDesired,100);// revert back to a reasonable number of groups
        }
    }
    else
        CGSuccess = performCG(&nIter);

    if (!CGSuccess)
        return false;

    if (_isnan(computeCompliance()))// likely to be disconnected body
        return false;

    h_nCGIterations[h_nLinearSolves] = nIter;
    h_nLinearSolves++;
    // writeMessageToParetoLog("AFElasticity: #CG Iterations = %d \n",nIter);
    return true;
}
/**********************************************************************/
int	AFElasticity::getLastCGIteration(void)
{
    return h_nCGIterations[h_nLinearSolves-1];
}
/**********************************************************************/
void	AFElasticity::getCGIterations(double *cgIterations)
{
    for (int i =0; i < h_nLinearSolves;i++)
        cgIterations[i] = h_nCGIterations[i];
}
/**********************************************************************/
void	AFElasticity::performSingleKUonCPU(double *y)
{
    if (h_KETemplates == NULL) {
        writeMessageToParetoLog("AFElasticity: Ke Templates not initialized\n");
        return;
    }
    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Performing Single Ku on CPU");

    if (h_hexmesh_verbose) {
        if ((h_nodeBasedAssembly) && (h_voxelgrid))
            writeMessageToParetoLog("AFElasticity: Node-based KU\n");
        else
            writeMessageToParetoLog("AFElasticity: Elem-based KU\n");
    }
    bool releaseMemory = false;
    if (y == NULL){
        double *y = (double *) malloc(3*h_nNodes*sizeof(double));
        releaseMemory = true;
    }
    KuCPU(h_sol,y);// y = K*sol
    if (releaseMemory) free(y);
}
/**********************************************************************/
bool	AFElasticity::performCG(int *niter )
{
    // Solves Ku = f
    // Assumes K and f have been defined, and Dirichlet conditions have been set
    // Also assumes CG iterations and tolerances have been defined.
    // Solution is returned in h_sol
    Timer timer;
    double fractionCompleted,tempDouble;

    if (h_KETemplates == NULL) {
        writeMessageToParetoLog("AFElasticity: Ke Templates not initialized\n");
        return false;
    }

#ifdef COMPILE_GPUCODE
    if (usingGPU) {
        *niter = performCGOnGPU();
        computeDeformationMax();
        return true;
    }
#endif
    double rho,alpha,beta,rho_new,normr,normr0;
    double *r,*p,*a;

    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Performing CG on CPU");

    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Allocating temporary memory");
    if (h_hexmesh_verbose) {
        if ((h_nodeBasedAssembly) && (h_voxelgrid))
            writeMessageToParetoLog("AFElasticity: Node-based KU\n");
        else
            writeMessageToParetoLog("AFElasticity: Elem-based KU\n");
    }
    // use temporary CPU variables
    r = (double *) malloc(3*h_nNodes*sizeof(double));
    p = (double *) malloc(3*h_nNodes*sizeof(double));
    a = (double *) malloc(3*h_nNodes*sizeof(double));


    double *temp_force = (double *) malloc(3*h_nNodes*sizeof(double));
    memcpy(temp_force,h_f,3*h_nNodes*sizeof(double));
    for (int node = 0; node < h_nNodes; node++) {
        if (!h_nodeExists[node]) {// make sure that there is no force on hanging nodes
            temp_force[3*node] = 0;
            temp_force[3*node+1] = 0;
            temp_force[3*node+2] = 0;
        }
    }

    safeFree(h_cgNorm);
    h_cgNorm = (double *) malloc(h_CGMaxIter*sizeof(double));
    memset(h_cgNorm,0,h_CGMaxIter*sizeof(double));
    // Assume u  has been initialized (see CPU initialization)
    timer.start();
    KuCPU(h_sol,a);// a = K*sol
    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Norm of sol = %e ",Norm(h_sol));
    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Time taken for one Kx: %f (msec) ",timer.getElapsedTimeInMilliSec());
    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: normf = %e ",Norm(temp_force));

    zeaxpy(-1,1,r,a,temp_force);// r = -a + f
    free(temp_force);
    normr = sqrt(dotprod(r,r));
    normr0 = normr;

    copy(r,a);// Set a = r
    copy(a,p);// Set p = a
    rho = dotprod(a,r);
    *niter = 1;     // Init counter for number of iterations
    if (h_hexmesh_verbose) {
        if (h_nodeBasedAssembly) writeMessageToParetoLog("AFElasticity: Starting node-based CG on CPU");
        else writeMessageToParetoLog("AFElasticity: Starting elem-based CG on CPU");
        writeMessageToParetoLog("AFElasticity: normr0 = %e, rho =%e \n",normr0,rho);
    }
    fractionCompleted = 0;
    bool success = true;
    while ((*niter < 10) || (normr > h_CGRelativeResErr*normr0))  {//% Test break condition
        tempDouble = ((h_CGRelativeResErr*normr0)/normr);
        fractionCompleted = MAX(0,1+0.1*log(tempDouble));// no negative values

        h_cgNorm[*niter-1] = log10(normr/normr0);
        KuCPU(p,a);// a = K*p;
        beta = dotprod(a,p);
        alpha = rho/beta;
        axpy(alpha, p,h_sol);//u = u + alpha*p;
        axpy(-alpha,a,r);//r = r - alpha*a;
        normr = sqrt(dotprod(r,r));
        if (*niter == 1) normr0 = normr;//update for consistent scaling convergence
        copy(r,a);// Set a = r
        rho_new =  dotprod(a,r);//rho = a'*r
        zeaxpy(1,(rho_new/rho),p,a,p);//p = a + rho_new/rho * p;
        rho = rho_new;
        (*niter)++;
        h_nCGItersActual = *niter;

        if (normr >100*normr0)  {
            success = false;
            break;
        }
        if ((h_hexmesh_verbose) && ((*niter)%100 ==0)) writeMessageToParetoLog(" %d: %e ",*niter,normr/normr0);
        if (*niter == h_CGMaxIter)  {
            success = false;
            break;
        }
    }
    if (h_hexmesh_verbose)  writeMessageToParetoLog("AFElasticity: CG on CPU; nIter = %d, resErr = %e ",*niter,normr/normr0);

    computeDeformationMax();
    free(a);
    free(p);
    free(r);
    return success;
}
//*********************************************************//
bool	AFElasticity::performPCG(int *niter )
{
    //it can do both CG as well as preconditioned CG
    // Solves Ku = f
    // Assumes K and f have been defined, and Dirichlet conditions have been set
    // Also assumes CG iterations and tolerances have been defined.
    // Solution is returned in h_sol
    Timer timer;
    double fractionCompleted,tempDouble;

    if (h_KETemplates == NULL) {
        writeMessageToParetoLog("AFElasticity: Ke Templates not initialized\n");
        return false;
    }

#ifdef COMPILE_GPUCODE
    if (usingGPU) {
        *niter = performCGOnGPU();
        computeDeformationMax();
        return true;
    }
#endif
    double rho,alpha,beta,rho_new,normr,normr0;
    double *r,*p,*a, *z,*preconditionerJacobi;

    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Performing preconditioned CG on CPU");

    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Allocating temporary memory");
    if (h_hexmesh_verbose) {
        if ((h_nodeBasedAssembly) && (h_voxelgrid))
            writeMessageToParetoLog("AFElasticity: Node-based KU\n");
        else
            writeMessageToParetoLog("AFElasticity: Elem-based KU\n");
    }
    // use temporary CPU variables
    r = (double *) malloc(3*h_nNodes*sizeof(double));
    z = (double *) malloc(3*h_nNodes*sizeof(double));
    p = (double *) malloc(3*h_nNodes*sizeof(double));
    a = (double *) malloc(3*h_nNodes*sizeof(double));


    double *temp_force = (double *) malloc(3*h_nNodes*sizeof(double));
    memcpy(temp_force,h_f,3*h_nNodes*sizeof(double));
    for (int node = 0; node < h_nNodes; node++) {
        if (!h_nodeExists[node]) {// make sure that there is no force on hanging nodes
            temp_force[3*node] = 0;
            temp_force[3*node+1] = 0;
            temp_force[3*node+2] = 0;
        }
    }


    safeFree(h_cgNorm);
    h_cgNorm = (double *) malloc(h_CGMaxIter*sizeof(double));
    memset(h_cgNorm,0,h_CGMaxIter*sizeof(double));
    // Assume u  has been initialized (see CPU initialization)
    timer.start();
    KuCPU(h_sol,a);// a = K*sol
    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Norm of sol = %e ",Norm(h_sol));
    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Time taken for one Kx: %f (msec) ",timer.getElapsedTimeInMilliSec());
    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: normf = %e, norm(sol) =%e ",Norm(temp_force),Norm(h_sol));

    zeaxpy(-1,1,r,a,temp_force);// r = -a + f
    free(temp_force);
    if(h_usingPreconditioner)	{
        //Jacobi Preconditioning
        if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: computing Jacobi preconditioner");
        preconditionerJacobi= (double*) malloc(3*h_nNodes*sizeof(double));
        computeJacobiPreconditioner(preconditionerJacobi);
        ScaleByVector(z,r,preconditionerJacobi);	//here z is z0
    }
    else
        memcpy(z,r,3*h_nNodes*sizeof(double));
    normr = sqrt(dotprod(r,r));
    normr0 = normr;

    copy(z,a);// Set a = r
    copy(a,p);// Set p = a
    rho = dotprod(r,z);
    *niter = 1;     // Init counter for number of iterations
    if (h_hexmesh_verbose) {
        if (h_nodeBasedAssembly) writeMessageToParetoLog("AFElasticity: Starting node-based CG on CPU");
        else writeMessageToParetoLog("AFElasticity: Starting elem-based CG on CPU");
        writeMessageToParetoLog("AFElasticity: normr0 = %e, rho =%e \n",normr0,rho);
    }
    fractionCompleted = 0;
    bool success = true;
    while ((*niter < 10) || (normr > h_CGRelativeResErr*normr0))  {//% Test break condition
        tempDouble = ((h_CGRelativeResErr*normr0)/normr);
        fractionCompleted = MAX(0,1+0.1*log(tempDouble));// no negative values

        h_cgNorm[*niter-1] = log10(normr/normr0);
        KuCPU(p,a);// a = K*p;
        beta = dotprod(a,p);
        alpha = rho/beta;
        axpy(alpha, p,h_sol);//u = u + alpha*p;
        axpy(-alpha,a,r);//r = r - alpha*a;
        if(h_usingPreconditioner)
            ScaleByVector(z,r,preconditionerJacobi);	//here z is z0
        else
            memcpy(z,r,3*h_nNodes*sizeof(double));
        normr = sqrt(dotprod(r,r));
        if (*niter == 1) normr0 = normr;//update for consistent scaling convergence
        copy(r,a);// Set a = r
        rho_new =  dotprod(z,r);//rho = a'*r
        zeaxpy(1,(rho_new/rho),p,z,p);//p = a + rho_new/rho * p;
        rho = rho_new;
        (*niter)++;
        h_nCGItersActual = *niter;

        if (normr >1000*normr0)  {
            // writeMessageToParetoLog("AFElasticity: Diverging at %d iter, resErr = %e \n",*niter,normr);
            success = false;
            break;
        }
        if ((h_hexmesh_verbose) && ((*niter)%100 ==0)) writeMessageToParetoLog(" %d: %e ",*niter,normr/normr0);
        //if (niter%100 ==0) writeMessageToParetoLog("\n niter = %d: %e ",niter,normr/normr0);
        if (*niter == h_CGMaxIter)  {
            // writeMessageToParetoLog("AFElasticity: Did not converge in %d iter, resErr = %e \n",*niter,normr/normr0);
            success = false;
            break;
        }
    }
    if (h_hexmesh_verbose)  writeMessageToParetoLog("AFElasticity: CG on CPU; nIter = %d, resErr = %e ",*niter,normr/normr0);
    // writeMessageToParetoLog("\nAFElasticity: CG on CPU; nIter = %d, resErr = %e \n",*niter,normr);
    computeDeformationMax();
    if(h_usingPreconditioner)
        free(preconditionerJacobi);
    free(a);
    free(p);
    free(r);
    free(z);
    return success;
}
/**********************************************************/
int  AFElasticity::getCGNorm(double *nrm)
{
    memcpy(nrm,h_cgNorm,(h_nCGItersActual-1)*sizeof(double));
    return h_nCGItersActual-1;
}
/**********************************************************************/
void AFElasticity::bubbleSortIncreasingDualIndex(double *numbers, int *sortIndex1,int *sortIndex2,int array_size)
{ // sort in increasing order
    int i, j,index;
    double temp;

    for (i = (array_size - 1); i > 0; i--){
        for (j = 1; j <= i; j++) {
            if (numbers[j-1] > numbers[j]) {// swap
                temp = numbers[j-1];
                numbers[j-1] = numbers[j];
                numbers[j] = temp;
                index = sortIndex1[j-1];
                sortIndex1[j-1]= sortIndex1[j];
                sortIndex1[j] = index;
                index = sortIndex2[j-1];
                sortIndex2[j-1]= sortIndex2[j];
                sortIndex2[j] = index;
            }
        }
    }
}
/**********************************************************/
void AFElasticity::bubbleSortIncreasing(double *numbers, int *sortIndex,int array_size)
{ // sort in increasing order
    int i, j,index;
    double temp;

    for (i =0; i < array_size;i++)
        sortIndex[i] = i;

    for (i = (array_size - 1); i > 0; i--){
        for (j = 1; j <= i; j++) {
            if (numbers[j-1] > numbers[j]) {// swap
                temp = numbers[j-1];
                numbers[j-1] = numbers[j];
                numbers[j] = temp;
                index = sortIndex[j-1];
                sortIndex[j-1]= sortIndex[j];
                sortIndex[j] = index;
            }
        }
    }
}
/**********************************************************************/
void AFElasticity::swap(double *v, int *index, int i, int j)
{
    double temp;
    int t;
    temp = v[i];
    v[i] = v[j];
    v[j] = temp;

    t = index[i];
    index[i] = index[j];
    index[j] = t;
}
/**********************************************************************/
void AFElasticity::swap(double *v, int i, int j)
{
    double temp;
    temp = v[i];
    v[i] = v[j];
    v[j] = temp;
}
/**********************************************************************/
void AFElasticity::shellSort(double numbers[], int array_size)
{
    int i, j, increment;
    double temp;

    increment = 3;
    while (increment > 0)
    {
        for (i=0; i < array_size; i++)
        {
            j = i;
            temp = numbers[i];
            while ((j >= increment) && (numbers[j-increment] > temp))
            {
                numbers[j] = numbers[j - increment];
                j = j - increment;
            }
            numbers[j] = temp;
        }
        if (increment/2 != 0)
            increment = increment/2;
        else if (increment == 1)
            increment = 0;
        else
            increment = 1;
    }
}
/**********************************************************************/
void AFElasticity::quickSortNonrecursive(double *arr, int elements) 
{
#define  MAX_LEVELS  300
    int   beg[MAX_LEVELS], end[MAX_LEVELS], i=0, L, R, swap ;
    double piv;

    beg[0]=0; end[0]=elements;
    while (i>=0) {
        L=beg[i]; R=end[i]-1;
        if (L<R) {
            piv=arr[L];
            while (L<R) {
                while (arr[R]>=piv && L<R) R--; if (L<R) arr[L++]=arr[R];
                while (arr[L]<=piv && L<R) L++; if (L<R) arr[R--]=arr[L]; }
            arr[L]=piv; beg[i+1]=L+1; end[i+1]=end[i]; end[i++]=L;
            if (end[i]-beg[i]>end[i-1]-beg[i-1]) {
                swap=beg[i]; beg[i]=beg[i-1]; beg[i-1]=swap;
                swap=end[i]; end[i]=end[i-1]; end[i-1]=swap;
            }
        }
        else {
            i--;
        }
    }
}
/**********************************************************************/
void AFElasticity::quickSort(double *v,int s, int n)
{
    // sort in increasing order
    int  p, i;
    double x;

    if (n < 1) return;
    // pick pivot and swap with first element
    x = v[s + n/2];
    swap(v, s, s + n/2);
    // partition slice starting at s+1
    p = s;
    for (i = s+1; i < s+n; i++)
        if (v[i] < x) {
            p++;
            swap(v, i, p);
        }
    // swap pivot into place
    swap(v, s, p);
    // recurse into partition
    quickSort(v, s, p-s);
    quickSort(v, p+1, s+n-p-1);
}
/**********************************************************************/
void AFElasticity::quickSort(double *v, int *sortIndex,int s, int n)
{
    // sort in increasing order
    int  p, i;
    double x;

    if (n < 1) return;
    // pick pivot and swap with first element
    x = v[s + n/2];
    swap(v, sortIndex,s, s + n/2);
    // partition slice starting at s+1
    p = s;
    for (i = s+1; i < s+n; i++)
        if (v[i] < x) {
            p++;
            swap(v, sortIndex,i, p);
        }
    // swap pivot into place
    swap(v, sortIndex,s, p);
    // recurse into partition
    quickSort(v, sortIndex,s, p-s);
    quickSort(v, sortIndex,p+1, s+n-p-1);
}
/**********************************************************************/
void AFElasticity::generalizedEigen(int N,double **AMatrix,double **BMatrix,double **XMatrix,double *LVector)
// Solve A*X = B*X*L
{
    int i,j;
    TCLMatrix A(N,N,0.0),B(N,N,0.0),X(N,N,0.0);
    TCLMatrix Q(N,N,0.0), QT(N,N,0.0),Y(N,N,0.0);
    TCLVector D(N,0.0),L(N,0.0);
    int *sortIndex;

    sortIndex = (int *)malloc(N*sizeof(int));
    // ensure that A and B  symmetric
    for (i =0; i < N; i++) {
        for (j =0; j < N; j++) {
            A[i][j] = (AMatrix[i][j] + AMatrix[j][i])/2.0;
            B[i][j] = (BMatrix[i][j] + BMatrix[j][i])/2.0;
        }
    }

    // To solve A*X = B*X*L
    // First find eigen of B
    // B*Q = Q*D
    B.eigen(D,Q);
    // B = Q*D*Q'
    // QD = Q*sqrt(D)
    // So B = QD*QD'
    // Substitute in A*X = B*X*L
    // Implies A*X = (QD*QD')*X*L
    // inv(QD)*A*X = QD'*X*L
    // Let QD'*X = Y, i.e., X = inv(QD')*Y
    // inv(QD)*A*inv(QD')*Y = Y*L
    // find the eigen values of inv(QD)*A*inv(QD')

    /*  for (j = 0; j < N; j++)
        cout << D[j] << endl;
*/
    for (i = 0; i < N; i++)
        for (j = 0; j < N; j++)
            Q[i][j] = Q[i][j]*sqrt((double)(D[j]));// QD is saved in Q

    Q.inv();// inv(QD)
    QT = Q;
    A = Q*A*(~QT);
    A.eigen(L,Y);
    X = (~Q)*Y;
    for (i =0; i < N; i++)
        LVector[i] = L[i];

    bubbleSortIncreasing(LVector,sortIndex,N);
    for (i = 0; i < N; i++) {
        for (j = 0; j < N; j++) {
            XMatrix[i][j] = X[i][sortIndex[j]];
        }
    }
    free(sortIndex);
}
/**********************************************************************/
void	AFElasticity::MatrixMatrixMultiply(int L, int M, int N, double **A,double **B, double **C)
// C = A*B
{
    int i,j,k;
    for (i = 0; i < L; i++) {
        for (j =0; j < N; j++) {
            C[i][j] = 0.0;
            for (k =0; k < M; k++) {
                C[i][j] += A[i][k]*B[k][j];
            }
        }
    }
}
/**********************************************************************/
void	AFElasticity::LanczosBasis(double *x,double mu,int m,double **Z)
// Construct a basis Z= {z0,z1,...,zm-1} for the Krylov space {x,Cx, C^x, ..., C^(m-1)*x} where C = K-mu*M
/*
    z(0) = x/norm(x);
    C = A - rho*B;
    for i = 0:m-1
    w = C*z(i);
    if (i >  0), w = w - beta(i)*z(i-1); end
    alpha(i) = w'*z(i);
    w = w - alpha(i)*z(i);
    beta(i+1) = norm(w);
    z(i+1) = w/beta(i+1);
    end
    */
{
    int i;
    double *w1,*w,beta,alpha;

    allocVector(3*h_nNodes,&w1);
    allocVector(3*h_nNodes,&w);
    normalize(x,Z[0]);//z0 = x/norm(x);
    for (i = 0; i < m-1;i++) {
        KuCPU(Z[i],w);// w = K*Z[i]
        MuCPU(Z[i],w1);// w1 = M*Z[i]

        axpy(-mu,w1,w); // w = w -mu*w1, i.e., w = K*x - mu*M*x; cannot combine K and M since rho^m is different for K & M
        if (i >  0)
            axpy(-beta,Z[i-1],w);//w = w - beta(i)*z(i-1);
        alpha = dotprod(w,Z[i]);
        axpy(-alpha,Z[i],w);//w = w - alpha(i)*z(i);
        beta = normalize(w,Z[i+1]);
    }
    free(w);
    free(w1);
}
/**********************************************************************/
void	AFElasticity::KProjection(int m,double **Z,double **KZ)
//KZ = Z'*K*Z, where Z = (3*h_nNodes,m), but stored as (m,3*h_nNodes) for convenience
// KZ = (m,m)
{
    int i,j;
    double **Kz;

    allocMatrix(m,3*h_nNodes,&Kz);
    for (i = 0;i < m; i++)
        KuCPU(Z[i],Kz[i]);
    for (i = 0;i < m; i++) {
        for (j = i;j < m; j++)
            KZ[i][j] = dotprod(Z[i],Kz[j]);

        for (j=0; j <i;j++)
            KZ[i][j] = KZ[j][i];
    }

    freeMatrix(m,Kz);
}
/**********************************************************************/
void	AFElasticity::MProjection(int m,double **Z,double **MZ)
//MZ = Z'*M*Z, where Z = (3*h_nNodes,m), but stored as (m,3*h_nNodes) for convenience
//MZ = (m,m)
{
    int i,j;
    double **Mz;

    allocMatrix(m,3*h_nNodes,&Mz);
    for (i = 0;i < m; i++)
        MuCPU(Z[i],Mz[i]);

    for (i = 0;i < m; i++) {
        for (j = i;j < m; j++)
            MZ[i][j] = dotprod(Z[i],Mz[j]);
        for (j=0; j <i;j++)
            MZ[i][j] = MZ[j][i];
    }
    freeMatrix(m,Mz);
}
/**********************************************************************/
double	AFElasticity::RayleighQuotient(double *x)
{
    // x'*K*x/(x'*M*x)
    double num,denom,*y;
    allocVector(3*h_nNodes,&y);

    KuCPU(x,y);
    num = dotprod(x,y);
    MuCPU(x,y);
    denom = dotprod(x,y);
    free(y);
    return (num/denom);
}
/**********************************************************************/
void	AFElasticity::RRSubspace(int subspaceSize,double **S,double **V,double *L,double **Y)
/* Given a subspace S of dimension (3*h_nNodes,subspaceSize), solve the eigen value problem over this subspace
    KS = S'*K*S
    MS = S'*M*S
    [V,L] = eig(KS,MS);
    Y = S*V;
    */
{
    int m,i,j;
    double **KS,**MS;
    m = subspaceSize;
    allocMatrix(m,m,&KS);
    allocMatrix(m,m,&MS);
    KProjection(m,S,KS);// KS = S'*K*S
    MProjection(m,S,MS);// KS = S'*K*S
    generalizedEigen(m,KS,MS,V,L);// find m eigen-pairs, sorted in increasing order
    // Now create Y = S*V
    for (i = 0; i < m;i++){
        initializeToZeros(Y[i]);
        for (j = 0; j < m;j++){
            axpy(V[j][i],S[j],Y[i]);// because of the way S and Y are stored
        }
    }
    freeMatrix(m,KS);
    freeMatrix(m,MS);
}
/**********************************************************************/
bool	AFElasticity::solveElasticityModalOld(int nEigenModes,double *eigenValues,double **eigenModes,double eigRelativeAccuracy)
{
    int niter = 0,n,i,totalIter;
    double **X,*omega,**V,**Y,iter=0,ref,refOld,*temp;


    if ((h_voxelgrid) &&  (h_nodeBasedAssembly))
        computeKeAndMeNodal(1);

    n = nEigenModes; //  additional buffer for accuracy
    allocMatrix(n,3*h_nNodes,&X);
    allocMatrix(n,3*h_nNodes,&Y);
    allocMatrix(n,n,&V);

    allocVector(n,&omega); //K*x = omega*M*x

    for (i = 0; i < n;i++) {
        initializeRandomVector(X[i]);
        omega[i] = RayleighQuotient(X[i]);
    }
    ref = 1.0;
    totalIter= 0;

    while (1) {
        totalIter += findEigenRayleighCG(n,omega,X,1,0.01,500);
        RRSubspace(n,X,V,omega,Y);
        // Swap pointers ... avoid memory copying!!
        for (i = 0; i < n;i++) {
            temp = X[i];
            X[i] = Y[i];
            Y[i] = temp;
        }
        refOld = ref;
        ref= 0;
        for (i = 0; i < nEigenModes;i++) ref += sqrt(omega[i]);
        {for (i = 0; i < nEigenModes;i++)  writeMessageToParetoLog(" %f ",sqrt(omega[i])/(2*3.14159)); 	 writeMessageToParetoLog("\n--------------------\n");}
        if (h_hexmesh_verbose) writeMessageToParetoLog("Relative accuracy for %d modes = %e",nEigenModes,abs(ref-refOld)/ref);
        if (abs(ref-refOld)/ref < eigRelativeAccuracy)	break;
        iter++;
    }
    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Eigenmode computation done!");
    writeMessageToParetoLog("--------------------\n");
    freeMatrix(n,X);
    freeMatrix(n,Y);
    free(omega);
    return true;
}
/**********************************************************************/
bool dummyCallBack(double fractionCompleted)
{
    return true;
}
/**********************************************************************/
bool	AFElasticity::solveElasticityModal(int nEigenModes,double *eigenValues,double **eigenModes,double eigRelativeAccuracy,double allocatedTimeInSecs)
{
    int n,i,totalCGIter,iter,cgIterSave;
    double **X,*omega,**V,**Y,ref,refOld,*temp,cgErrorSave,deformationMax;
    Timer timer;

    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: In solveElasticityModal!");

    deformationMax = getDeformationMax();

    if (deformationMax == 0){
        cout << "AFElasticity: You must solve a valid static problem first" << endl;
        return false;
    }

    // the displacement and force gets overwritten, so store
    double *solTemp, *forceTemp;
    solTemp = (double *)malloc(3 * getNumNodes() * sizeof(double));
    forceTemp = (double *)malloc(3 * getNumNodes() * sizeof(double));
    getSolutionVector(solTemp);
    getForceVector(forceTemp);

    timer.start();
    if ((h_voxelgrid) &&  (h_nodeBasedAssembly)){
        computeKeAndMeNodal(1);
    }

    n = nEigenModes+1;//  additional buffer?
    allocMatrix(n,3*h_nNodes,&X);
    allocMatrix(n,3*h_nNodes,&Y);
    allocMatrix(n,n,&V);
    allocVector(n,&omega);
    for (i = 0; i < n;i++)
        initializeRandomVector(X[i]);

    cgIterSave = h_CGMaxIter;
    cgErrorSave = h_CGRelativeResErr;
    h_CGRelativeResErr = 0.0001;
    h_CGMaxIter = 300;
    ref = 1.0;
    totalCGIter= 0;
    iter = 0;

    findEigenRayleighCG(n,omega,X,false,0.01,50*n);// initial guess

    if (h_hexmesh_verbose) {
        for (i = 0; i < nEigenModes; i++)
            cout << "EigenMode " <<i+1 << " : " << sqrt(omega[i]) / (2 * 3.14159) << endl;
    }
    if (h_hexmesh_verbose) cout << "AFElasticity: Completed RayleighCG!" << endl;

    bool success = true;

    while (1) {
        for (i = 0; i < n;i++) {
            if ((_isnan(omega[i])) || (fabs(omega[i]) < 1e-10))// failed
                findEigenRayleighCG(n,omega,X,false,h_CGRelativeResErr,h_CGMaxIter);//directly compute
        }
        for (i = 0; i < n;i++) {
            MuCPU(X[i],h_f); //h_f = M*X[i]
            scale(omega[i],h_f);// h_f *= lambda[i];
            if (!solveElasticityStatic()) {// Solve K*h_sol = h_f
                success = false;
                break;
            }
            copy(h_sol,X[i]);
        }
        if (!success) break;
        RRSubspace(n,X,V,omega,Y);
        for (i = 0; i < n;i++) {// Copy pointers ... avoid memory copying!!
            temp = X[i];
            X[i] = Y[i];
            Y[i] = temp;
        }
        refOld = ref;
        ref= 0;
        for (i = 0; i < nEigenModes;i++)
            ref += sqrt(omega[i]);
        if ((abs(ref-refOld)/ref < eigRelativeAccuracy) || (iter++ > 20))
            break;
        if (h_hexmesh_verbose) {
            for (i = 0; i < nEigenModes; i++)
                cout << "EigenMode " <<i+1 << " : " << sqrt(omega[i]) / (2 * 3.14159) << endl;
        }

        //h_CGRelativeResErr *= 0.5;
        if (timer.getElapsedTimeInSec() > allocatedTimeInSecs) {
            cout << "AFElasticity: Exceeded max allowed time in ElasticityModal of  " << allocatedTimeInSecs << " seconds " << endl;
            success = true;
            break;
        }
    }
    for (i = 0; i < nEigenModes;i++){
        copy(X[i],eigenModes[i]);
        eigenValues[i] = sqrt(omega[i]) / (2 * 3.1415);
    }
    // scale all eigenmodes

    for (int mode = 0; mode < nEigenModes; mode++) {
        double modeMax, delta;
        modeMax = 0;
        for (int n = 0; n < getNumNodes(); n++) {
            delta = eigenModes[mode][3 * n] * eigenModes[mode][3 * n] +
                    eigenModes[mode][3 * n + 1] * eigenModes[mode][3 * n + 1] +
                    eigenModes[mode][3 * n+2] * eigenModes[mode][3 * n + 2];
            modeMax = max(modeMax, sqrt(delta));
        }
        for (int n = 0; n < getNumNodes(); n++) {
            for (int i = 0; i < 3; i++)
                eigenModes[mode][3*n+i] *= deformationMax / modeMax;
        }
    }
    setSolutionAtAllNodes(solTemp);
    setForceVector(forceTemp);
    free(solTemp);
    free(forceTemp);
    freeMatrix(n,X);
    freeMatrix(n,Y);
    free(omega);
    h_CGRelativeResErr = cgErrorSave;
    h_CGMaxIter = cgIterSave;
    return success;
}
/**********************************************************************/
int	AFElasticity::findEigenRayleighCG(int nEigenModes,double *eigenValues,double **eigenModes,bool useInitialGuess,double relResidual,int maxIterPerMode)
{
    // Perform Rayleigh CG to find the first few eigen mode of K*x = (omega)*M*x

    int totalIter;
#ifdef COMPILE_GPUCODE
    if (usingGPU)
        return findEigenRayleighCGOnGPU(nEigenModes,eigenValues,eigenModes, useInitialGuess,relResidual,maxIterPerMode);
#endif
    // Else
    double MNorm,alpha,omega,alphaOld,a,b,c,d,ak,bk,ck,disc,delta;
    int  niter,currentMode;
    double *x,*Kx,*Mx,*p,*Kp,*Mp,*g,**temp,s,normg0;

    allocVector(3*h_nNodes,&x);
    allocVector(3*h_nNodes,&Kx);
    allocVector(3*h_nNodes,&Mx);
    allocVector(3*h_nNodes,&p);
    allocVector(3*h_nNodes,&Kp);
    allocVector(3*h_nNodes,&Mp);
    allocVector(3*h_nNodes,&g);
    allocMatrix(nEigenModes,3*h_nNodes,&temp);

    totalIter = 0;
    for (currentMode = 0; currentMode < nEigenModes; currentMode++) {
        // writeMessageToParetoLog(" ---------------- Mode = %d ----------------\n",currentMode);
        // Compute the nth mode
        if (useInitialGuess)
            copy(eigenModes[currentMode],x);//copy the current guess of eigenmode
        else
            initializeRandomVector(x);
        initializeToZeros(p);
        // M-orthogonalize with respect all previous eigen vectors
        for (int n = 0; n < currentMode; n++) {
            MuCPU(eigenModes[n],temp[n]);
            s = dotprod(x,temp[n]);
            axpy(-s,eigenModes[n],x);// x = x - s*eigenMode[n];
        }

        MuCPU(x,Mx);// Mx = M*x
        MNorm = sqrt(dotprod(x,Mx));// MNorm = sqrt(x'*Mx);
        scale(1.0/MNorm,x);//x = x/MNorm;
        scale(1.0/MNorm,Mx);//Mx = Mx/MNorm;
        KuCPU(x,Kx);//Kx = K*x;
        omega = dotprod(x,Kx);//RayleighQuotient = x'*Kx;
        zeaxpy(2,-2*omega,g,Kx,Mx);//g = 2*(Kx- omega*Mx);
        alpha = dotprod(g,g) ;
        alphaOld = 1e20*rand()/RAND_MAX;
        normg0 = alpha;
        niter = 1;
        if (abs(alpha) < 1e-10)
            break;
        while (1) {
            zeaxpy(-1,(alpha/alphaOld),p,g,p);//p = -g + alpha/alphaOld*p; // fletcher-reeves algorithm for new direction
            // M-orthogonalize with respect all previous eigen vectors
            for (int n = 0; n < currentMode; n++) {
                s = dotprod(p,temp[n]);//temp[n] has been previously stored
                axpy(-s,eigenModes[n],p);// p = p - s*eigenMode[n];
            }
            MuCPU(p,Mp);// Mp = M*p;
            a = dotprod(x,Mp);// a = x'*Mp
            b = dotprod(Kx,p);// b = Kx'*p;
            KuCPU(p,Kp);// Kp = K*p;
            c = dotprod(p,Kp);// c = p'*Kp;
            d = dotprod(p,Mp);// d = p'*Mp;
            ak = a*c - b*d;
            bk = c - omega*d;
            ck = b - omega*a;
            disc = sqrt(bk*bk - 4*ak*ck);
            if (bk > 0) delta = -2*ck/(bk + disc);
            else if (ak !=0) delta = (-bk + disc)/(2*ak);
            else delta = -ck/bk;

            axpy(delta,p,x);// x = x + delta*p;
            axpy(delta,Mp,Mx);//Mx = Mx + delta*Mp;
            axpy(delta,Kp,Kx);//Kx = Kx + delta*Kp;
            MNorm = sqrt(dotprod(x,Mx));// MNorm = sqrt(x'*Mx);
            scale(1.0/MNorm,x);//x = x/MNorm;
            scale(1.0/MNorm,Mx);//Mx = Mx/MNorm;
            scale(1.0/MNorm,Kx);//Kx = Kx/MNorm;
            omega = dotprod(x,Kx);//RayleighQuotient = x'*Kx;;
            zeaxpy(2,-2*omega,g,Kx,Mx);//g = 2*(Kx- RayleighQuotient*Mx);
            alphaOld = alpha; // alpha = g'*g;
            alpha = dotprod(g,g);
            if ((niter > maxIterPerMode) || ((alpha/normg0) < relResidual) || (abs(alpha) < 1e-10))
                break;
            niter++;
            //if (totalIter%2000 == 0) writeMessageToParetoLog("nIter = %d, lambda = %0.3e (Hz) ",niter,sqrt(omega)/(2*3.1415));
            totalIter++;
        }
        eigenValues[currentMode] = sqrt(omega)/(2*3.1415);
        copy(x,eigenModes[currentMode]);
    }
    copy(eigenModes[0],h_sol);
    free(x);
    free(Kx);
    free(Mx);
    free(p);
    free(Kp);
    free(Mp);
    free(g);
    freeMatrix(nEigenModes,temp);
    return totalIter;
}
/**********************************************************************/
void AFElasticity::postprocess(void)
{
    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Post-processing ");
    postprocessAtElems();
    postprocessAtNodes();
    //accurateStressEstimator(h_elemWithMaxStress);
}
/**********************************************************************/
bool AFElasticity::pushInitialStaticSolutionToTessellation(void)
{
    double pt[3],uvw[3],stresses[6],vonMises;

    if (h_numTesselationPoints == 0) return false;

    for (int i = 0; i < h_numTesselationPoints; i++) {
        pt[0] =h_tessellationXYZ[3*i];
        pt[1] =h_tessellationXYZ[3*i+1];
        pt[2] =h_tessellationXYZ[3*i+2];
        getElasticitySolutionAt(pt,uvw,stresses,&vonMises);
        for (int j = 0; j < 3;j++)
            h_tessellationUVW[3*i+j] = uvw[j];

        h_tessellationVonMises[i] = vonMises;
    }
    return true;
}

/**********************************************************************/
bool AFElasticity::pushInitialModalSolutionToTessellation(double *eigenMode)
{
    double pt[3],uvwModal[3];
    int elem,nodes[8],node;
    if (!h_voxelgrid) return false;

    if (h_numTesselationPoints == 0) {
        cout << "AFElasticity:#tessellations points = 0 " << endl;
        return false;
    }

    for (int i = 0; i < h_numTesselationPoints; i++) {
        pt[0] =h_tessellationXYZ[3*i];
        pt[1] =h_tessellationXYZ[3*i+1];
        pt[2] =h_tessellationXYZ[3*i+2];

        uvwModal[0] = uvwModal[1] = uvwModal[2] = 0;
        elem = findNonVoidElemClosestTo(pt[0],pt[1],pt[2],3);// within relative tolerance
        if ((elem < 0) || (elem >= h_nElems)) {
            return false;
        }

        getElemNodes(elem,nodes);
        // at the center
        for (int m = 0;m < 8; m++) {
            node = nodes[m];
            uvwModal[0] += eigenMode[3*node]/8.0;
            uvwModal[1] += eigenMode[3*node+1]/8.0;
            uvwModal[2] += eigenMode[3*node+2]/8.0;
        }
        for (int j = 0; j < 3;j++)
            h_tessellationModalUVW[3*i+j] = uvwModal[j];
    }
    return true;
}
/**********************************************************************/
void AFElasticity::computeElemStress(double strains[6], double stresses[6])
{
    int i,materialId, offset;
    for (i = 0; i < 6; i++)
        stresses[i] = 0.0;

    materialId = 0;//assumed
    offset = 36*materialId;
    for (i = 0; i <3; i++) {
        stresses[0] += h_DMatrices[offset+i]*strains[i];//sxx
        stresses[1] += h_DMatrices[offset+6+i]*strains[i];//syy
        stresses[2] += h_DMatrices[offset+12+i]*strains[i];//szz
    }
    stresses[3] = h_DMatrices[offset+21]*strains[3];//sxy
    stresses[4] = h_DMatrices[offset+28]*strains[4];//sxz
    stresses[5] = h_DMatrices[offset+35]*strains[5];//syz
}

/**********************************************************************/
void AFElasticity::postprocessAtElems(void)
{
    // assumes that the solution is stored in private variable 'sol'
    //Compute strains and stresses in the middle of every element
    int i,elem,matl;
    double sxx,syy,szz,sxy,sxz,syz,elemVonMisesStress,T1,T2,T3,u[8],v[8],w[8],DMatrix[MAX_MATERIALS][36];

    //if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Post-processing at elements");
    h_vonmisesMax = 0;
    h_vonmisesMin = HUGE_VAL;
    h_elemWithMaxStress = 0;

    for (int part = 0; part < MAX_PARTS; part++)
        h_vonmisesMaxInPart[part] = 0;

    if (h_nMaterials == 0) {
        writeMessageToParetoLog("AFElasticity: Number of materials = 0! Error!! \n");
        return;
    }
    for ( matl = 0; matl <h_nMaterials; matl++)
        getDMatrix(matl,DMatrix[matl]);

    //  compute strains and stresses in each element
    //#pragma omp parallel for private(elem,matl,i,T1,T2,T3,sxx,syy,szz,sxy,sxz,syz,u,v,w,elemVonMisesStress)
    for (elem = 0; elem < h_nElems; elem++){
        for (i = 0; i < 6; i++)
            h_elemstresses[i][elem] = 0;// useful for removing dead material

        matl = h_materialIdOfElem[elem];
        if ( (matl < 0) || (matl >= h_nMaterials)){
            writeMessageToParetoLog("Error = matl = %d, mapping to 0 \n",matl );
            matl = 0;
        }
        if (h_pseudoDensity[elem] <h_pseudoDensityCutoff)continue; // use old value for topology optimization purpose

        for (i = 0; i < 6; i++) {
            h_elemstrains[i][elem] = 0;
            h_elemstresses[i][elem] = 0;
        }
        if (h_voxelgrid) {
            getElemNodeDeformation(elem,u,v,w);
            for (i = 0; i < 8; i++) {// contribution from all 8 nodes
                T1 = 2*h_gradNxi0[i]/h_dx;
                T2 = 2*h_gradNeta0[i]/h_dy;
                T3 = 2*h_gradNmu0[i]/h_dz;

                h_elemstrains[0][elem] += T1*u[i];// ux
                h_elemstrains[1][elem] += T2*v[i];// vy
                h_elemstrains[2][elem] += T3*w[i];// wz
                h_elemstrains[3][elem] += (T2*u[i] + T1*v[i]);// uy + vx
                h_elemstrains[4][elem] += (T3*u[i] + T1*w[i]);// uz + wx
                h_elemstrains[5][elem] += (T3*v[i] + T2*w[i]);// vz + wy
            }
        }
        else {
#pragma omp critical
            computeStrain(elem,0,0,0,NULL);// compute strain in the center of element and enter into h_elemstrains
        }
        // Now compute stresses
        for (i = 0; i <3; i++) {
            h_elemstresses[0][elem] += DMatrix[matl][i]*h_elemstrains[i][elem];//sxx
            h_elemstresses[1][elem] += DMatrix[matl][6+i]*h_elemstrains[i][elem];//syy
            h_elemstresses[2][elem] += DMatrix[matl][12+i]*h_elemstrains[i][elem];//szz
        }
        h_elemstresses[3][elem] = DMatrix[matl][21]*h_elemstrains[3][elem];//sxy
        h_elemstresses[4][elem] = DMatrix[matl][28]*h_elemstrains[4][elem];//sxz
        h_elemstresses[5][elem] = DMatrix[matl][35]*h_elemstrains[5][elem];//syz

        sxx = h_elemstresses[0][elem];
        syy = h_elemstresses[1][elem];
        szz = h_elemstresses[2][elem];
        sxy = h_elemstresses[3][elem];
        sxz = h_elemstresses[4][elem];
        syz = h_elemstresses[5][elem];


        elemVonMisesStress =  1.0/sqrt(2.0)*sqrt((sxx-syy)*(sxx-syy)+(sxx-szz)*(sxx-szz) +(syy-szz)*(syy-szz)+6*(sxy*sxy+sxz*sxz+syz*syz));

#pragma omp critical
        if ((elemVonMisesStress > h_vonmisesMax)) {
            h_elemWithMaxStress = elem;
            h_vonmisesMax = elemVonMisesStress;
        }
#pragma omp critical
        {
            int part = getPartIdOfElem(elem);
            h_vonmisesMaxInPart[part] = MAX(h_vonmisesMaxInPart[part],elemVonMisesStress);
        }
#pragma omp critical
        if ((elemVonMisesStress < h_vonmisesMin)) {
            h_vonmisesMin = elemVonMisesStress;
        }
    }

    if (h_nElems < 1000){
        double maxStressAtGP;
        maxStressAtGP = 0;
        for (int elem = 0; elem < h_nElems; elem++)
            maxStressAtGP = MAX(maxStressAtGP,computeMaxVonMisesAllGP(elem));
        h_vonmisesMax = maxStressAtGP;
    }
    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: postprocess at elems; h_vonmisesMax = %e ",h_vonmisesMax);
} 
/**********************************************************************/
bool AFElasticity::getYieldStressOfMaterial(int matId,double *yieldStress)
{
    if (matId >= h_nMaterials)
        return false;

    *yieldStress = h_Y[matId];
    return true;
}
/**********************************************************************/
double AFElasticity::getMaxStressInPart(int part)
{
    if (part >= MAX_PARTS)
        return 0;

    return h_vonmisesMaxInPart[part];
}
/**********************************************************************/
bool AFElasticity::isDesignPastYield(int *partId,double safetyFactor)
{
    // check and return the material that has yield
    if (!isStaticFEAValid()) return false;
    int matId;
    *partId = 0;
    for (int part = 0; part < MAX_PARTS; part++) {
        matId = getMaterialIDofPart(part);
        if (h_vonmisesMaxInPart[part] > h_Y[matId]/safetyFactor){
            *partId = part;
            return true;
        }
    }
    return false;
}
/**********************************************************************/
double AFElasticity::computeMaxVonMisesAtCenter(int elem)
{
    double tempStrain[6];
    int i,materialIndex,offset;
    double sxx,syy,szz,sxy,sxz,syz,vonMisesGuassPt,elemstresses[6],elemstrains[6];
    double xi,eta,mu;


    materialIndex = h_materialIdOfElem[elem];
    offset = 36*materialIndex;
    xi = 0; eta = 0; mu = 0;

    computeStrainWithBubble(elem,xi,eta,mu,tempStrain);
    for (i = 0; i < 6; i++) {
        elemstrains[i] = tempStrain[i];
        elemstresses[i] = 0;
    }
    // Now compute stresses
    for (i = 0; i <3; i++) {
        elemstresses[0] += h_DMatrices[offset+i]*elemstrains[i];//sxx
        elemstresses[1] += h_DMatrices[offset+6+i]*elemstrains[i];//syy
        elemstresses[2] += h_DMatrices[offset+12+i]*elemstrains[i];//szz
    }
    elemstresses[3] = h_DMatrices[offset+21]*elemstrains[3];//sxy
    elemstresses[4] = h_DMatrices[offset+28]*elemstrains[4];//sxz
    elemstresses[5] = h_DMatrices[offset+35]*elemstrains[5];//syz

    sxx = elemstresses[0];
    syy = elemstresses[1];
    szz = elemstresses[2];
    sxy = elemstresses[3];
    sxz = elemstresses[4];
    syz = elemstresses[5];

    vonMisesGuassPt =  1.0/sqrt(2.0)*sqrt((sxx-syy)*(sxx-syy)+(sxx-szz)*(sxx-szz) +(syy-szz)*(syy-szz)+
                                          6*(sxy*sxy+sxz*sxz+syz*syz));

    return vonMisesGuassPt;
}
/**********************************************************************/
double AFElasticity::computeMaxVonMisesAllGP(int elem)
{
    double tempStrain[6],elemMaxStress,elemMinStress;
    int i,materialIndex,offset;
    double sxx,syy,szz,sxy,sxz,syz,vonMisesGuassPt,elemstresses[6],elemstrains[6];
    double a = 1.0/sqrt(3.0);
    double xi[8] = {-a,-a,a,a,-a,-a,a,a};
    double eta[8] = {-a,a,-a,a,-a,a,-a,a};
    double mu[8] = {-a,-a,-a,-a,a,a,a,a};

    elemMaxStress= -HUGE_VAL;
    elemMinStress= HUGE_VAL;

    materialIndex = h_materialIdOfElem[elem];
    offset = 36*materialIndex;
    for (int gp = 0; gp < 8; gp++){
        computeStrain(elem,xi[gp],eta[gp],mu[gp],tempStrain);
        for (i = 0; i < 6; i++) {
            elemstrains[i] = tempStrain[i];
            elemstresses[i] = 0;
        }
        // Now compute stresses
        for (i = 0; i <3; i++) {
            elemstresses[0] += h_DMatrices[offset+i]*elemstrains[i];//sxx
            elemstresses[1] += h_DMatrices[offset+6+i]*elemstrains[i];//syy
            elemstresses[2] += h_DMatrices[offset+12+i]*elemstrains[i];//szz
        }
        elemstresses[3] = h_DMatrices[offset+21]*elemstrains[3];//sxy
        elemstresses[4] = h_DMatrices[offset+28]*elemstrains[4];//sxz
        elemstresses[5] = h_DMatrices[offset+35]*elemstrains[5];//syz

        sxx = elemstresses[0];
        syy = elemstresses[1];
        szz = elemstresses[2];
        sxy = elemstresses[3];
        sxz = elemstresses[4];
        syz = elemstresses[5];

        vonMisesGuassPt =  1.0/sqrt(2.0)*sqrt((sxx-syy)*(sxx-syy)+(sxx-szz)*(sxx-szz) +(syy-szz)*(syy-szz)+
                                              6*(sxy*sxy+sxz*sxz+syz*syz));

        elemMaxStress = MAX(elemMaxStress,vonMisesGuassPt);
        elemMinStress = MIN(elemMinStress,vonMisesGuassPt);
    }
    return elemMaxStress;
}
/**********************************************************************/
void AFElasticity::postprocessAtNodes(void)
{
    //Compute strains and stresses in the middle of every element and average out at the node
    int i,j,maxElem,elem,node,codedElemNum,nodeIndex,count,nSmoothening;
    double sxx,syy,szz,sxy,sxz,syz,nodeMaxStress,stressScaling;

    //if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Post-processing at Nodes ");

    // compute strains and stresses at each node by averaging
#pragma omp parallel for private(node,maxElem,count,nodeIndex,elem,j,i,codedElemNum,sxx,syy,szz,sxy,sxz,syz)
    for (node = 0; node < h_nNodes;node++) {
        h_nodevonmises[node] = 0;
        maxElem = h_nNeighboringElems[node];// how many elements connected to node
        count = 0;
        for (j =0; j < maxElem; j++) {//
            codedElemNum = h_neighborElems[(h_nNodes)*j + node];// process elem-j neighbor
            nodeIndex = codedElemNum/MAXELEMS;
            elem = codedElemNum - nodeIndex*MAXELEMS;
            if (h_pseudoDensity[elem] <h_pseudoDensityCutoff) continue;
            count++;
        }
        if (count == 0) continue;// there is no element connected to this node
        for (i =0; i < 6; i++) {//reset to zero
            h_nodestrains[i][node] = 0;
            h_nodestresses[i][node] = 0;
        }
        count = 0;
        for (j =0; j < maxElem; j++) {//
            codedElemNum = h_neighborElems[(h_nNodes)*j + node];// process elem-j neighbor
            nodeIndex = codedElemNum/MAXELEMS;
            elem = codedElemNum - nodeIndex*MAXELEMS;
            if (h_pseudoDensity[elem] <h_pseudoDensityCutoff) continue;
            count++;
            for (i =0; i < 6; i++) {
                h_nodestrains[i][node] += h_elemstrains[i][elem];
                h_nodestresses[i][node] += h_elemstresses[i][elem];
            }
        }
        count = MAX(1.0,count);
        //average out, and also find max and min across all nodes
        for (i =0; i < 6; i++) {
            h_nodestrains[i][node] /=  count;
            h_nodestresses[i][node] /=  count;
        }

        sxx = h_nodestresses[0][node];
        syy = h_nodestresses[1][node];
        szz = h_nodestresses[2][node];
        sxy = h_nodestresses[3][node];
        sxz = h_nodestresses[4][node];
        syz = h_nodestresses[5][node];

        h_nodevonmises[node] =  1.0/sqrt(2.0)*sqrt((sxx-syy)*(sxx-syy)+(sxx-szz)*(sxx-szz) +(syy-szz)*(syy-szz)+
                                                   6*(sxy*sxy+sxz*sxz+syz*syz));
    }

    nSmoothening = 1;
    //double stressMaxSave,weight;
    //stressMaxSave = h_vonmisesMax;
    /// for large number of elements, the max stress increases.
    // smoothen stress and take a weighted average
    //smoothenVonMisesStress(nSmoothening); // This will lower h_vonmisesMax
    // weight the depends on the number of elements
    //weight = log10(1.0*h_nElems);
    //weight = 0;
    //h_vonmisesMax = (weight*h_vonmisesMax + (1-weight)*stressMaxSave);
    /// for large number of elements, the max stress increases due to voxelization
    /*double scaling;
    scaling = MAX(1,0.65*(log10(h_nElems)-4));//heuristic!! example: for 1.5 million elements, scale by 1.4
    h_vonmisesMax /=scaling;
    */
    nSmoothening = 2;
    smoothenScalarNodalField(h_nodevonmises,nSmoothening);// for better display, does not affect h_vonmisesMax

    nodeMaxStress = 0;
    /// this is not parallelized
    for (node = 0; node < h_nNodes;node++) {
        if (h_nodevonmises[node] > nodeMaxStress) {
            h_nodeWithMaxStress = node;
            nodeMaxStress= h_nodevonmises[node];
        }
    }

    //if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: postprocess at nodes; nodeMaxStress = %e ",nodeMaxStress);

    stressScaling = h_vonmisesMax/nodeMaxStress;
#pragma omp parallel for private(node)
    for (node = 0; node < h_nNodes;node++)
        h_nodevonmises[node] *=stressScaling;
}
/**********************************************************************/
bool AFElasticity::getNormalAtNode(int node,double normal[3])
{
    // return true and the normal if the normal can be computed at that node
    //else returns false
    if ( (node < 0) || (node > h_nNodes)) return false;
    if (isNodeInInterior(node)) return false;//boundary normal makes no sense


    // the idea is to find neighbor nodes that are valid, and use th center of gravity to find the normal
    int neighborNodes[100],nNeighborNodes,counter,otherNode;
    double pt0[3],tempPt[3],cg[3],nrm;

    getNodeXYZ(node,pt0);
    nNeighborNodes = getNeighborNodesOfNode(node,neighborNodes);
    counter = 0;
    // find the center of gravity
    for (int i = 0; i < nNeighborNodes; i++) {
        otherNode = neighborNodes[i];
        if (!doesNodeExist(otherNode)) continue;
        counter++;
        getNodeXYZ(otherNode,tempPt);
        for (int j = 0; j < 3; j++)
            cg[j] += tempPt[j];
    }
    if (counter <= 1) return false;//again, boundary normal makes no sense
    for (int j = 0; j < 3; j++)
        cg[j] /= counter;

    for (int j = 0; j < 3; j++)
        normal[j] = pt0[j] - cg[j];

    nrm = NORM3D(normal);
    if (nrm < TOL) return false;//Error

    for (int j = 0; j < 3; j++)
        normal[j] /=nrm;

    return true;
}
