/**********************************************************************/
/**********************************************************************/
void	AFElasticity::transferAFElasticityToGPU(void)
{// just a wrapper

    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Transferring mesh to GPU ");
    initializeGPUHexmeshData(h_nNodes, h_nElems,  h_maxNeighboringElements,  h_nTemplateElements,
                             h_elems,h_pseudoDensity,h_nodeExists,h_templateID, h_sol,h_free,h_f,h_neighborElems,h_nNeighboringElems,h_KETemplates,
                             h_METemplates,h_nodeSignature,h_neighborNodes,h_KeNode, h_MeNode,&h_gpuData);

}
/**********************************************************************/
void	AFElasticity::transferForcesBCToGPU(void)
{// just a wrapper

    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Transferring forces and boundary conditions to GPU ");

    setGPUForcesBC(h_nNodes,h_sol,h_free,h_f,&h_gpuData);
}
/**********************************************************************/
int	AFElasticity::performCGOnGPU(void)
{
    // Assumes that
    // (1) forces are initialized in h_gpuData->d_fu, ...
    // (2) Templates are computed and d_KETemplates stored in h_gpuData
    // The solution is stored in
    // h_gpuData->d_u, ...

    // If converged, returns the number of CG iterations
    // If divergence, returns -1
    int nIter;

    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Performing CG on GPU");
    nIter = ConjugateGradientOnGPU(&h_gpuData,h_CGMaxIter,h_CGRelativeResErr,h_nodeBasedAssembly);
    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Transferring solution from GPU to CPU");
    transferSolutionFromGPU(&h_gpuData,h_sol);
    return nIter;
}

/**********************************************************************/
int	AFElasticity::findFirstEigenmodeOnGPU(double eigRelativeAccuracy,double *eigenValues,double **eigenModes)
{// just a wrapper
    int nIter;


    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Performing Rayleigh CG on GPU");
    nIter = firstEigenmodeOnGPU(&h_gpuData,h_CGMaxIter,h_nodeBasedAssembly,eigRelativeAccuracy,eigenValues,eigenModes);
    return nIter;
}
/**********************************************************************/
int	AFElasticity::findEigenRayleighCGOnGPU(int nEigmodes,double *eigenValues,double **eigenModes,int useInitialGuess,double relResidual,int maxIterPerMode)
{// just a wrapper
    int nIter;


    if (h_hexmesh_verbose) writeMessageToParetoLog("AFElasticity: Performing Rayleigh CG on GPU");
    nIter = RayleighCGOnGPU(&h_gpuData,nEigmodes,eigenValues,eigenModes,useInitialGuess,relResidual,maxIterPerMode,h_nodeBasedAssembly);
    return nIter;
}

