/**********************************************************************/
AFElasticity::~AFElasticity(void)
{

    if (h_hexmesh_verbose) writeMessageToParetoLog("Releasing AFElasticity Object ");
    if (h_nNodes == 0) return;
#ifdef COMPILE_GPUCODE
    releaseHexmeshGPUMemory(&h_gpuData);
#endif


    releaseCPUMemory();
    h_nNodes = 0;
    if (h_hexmesh_verbose) writeMessageToParetoLog("Releasing h_gridNodeToRealNode ");
    safeFree(h_gridNodeToRealNode);h_gridNodeToRealNode = NULL;

    if (h_elem27Nodes != NULL){
          for (int elem = 0; elem < getNumElems(); elem++)
              safeFree(h_elem27Nodes[elem]);
          safeFree(h_elem27Nodes);
    }
}
